(window.GIM_TS=window.GIM_TS||{})["Menachot.4"]={"from":96,"a":[["ואם כן \u0003מכל מקום\u0004 עדיין השאלה במקומה עומדת: והרי \u0003שבעה\u0004 טלאים \u0003הוו\u0004 \u0005[הם]\u0006 שצריכים להיות בלשכת הטלאים\u0005!\u0006 \u0003אלא\u0004 יש לומר כי ה\u0003תנא בעלמא קאי\u0004 \u0005[בכלל,\u0006 באופן כללי, \u0005הוא עומד,\u0006 מתייחס בדבריו\u0005],\u0006 לכל השנה כולה, \u0003ומאי\u0004 \u0005[ומה\u0006 זה\u0005]\u0006 שאמר בתוך דבריו \u0003\"כדי לשבת ושני ימים טובים של ראש השנה\"?\u0004 — \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד]\u0006 הוא, לזכור שמדובר במספר טלאים הנצרכים לשלושה ימים, ולא פחות מכך.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 בלשון המשנה, \u0003דקתני\u0004 \u0005[שהוא\u0006 התנא \u0005שנה]\u0006 בה \u0003\"כדי לשבת\u0004 ושני ימים טובים של ראש השנה\", \u0003ולא קתני\u0004 \u0005[ולא שנה]\u0006 בה \u0003\"לשבת ולשני ימים טובים של ראש השנה\"\u0004 שמשמעו: לצורך אותם ימים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא פירוש הדברים.","שנינו במשנתנו כי אף אם אירע ש\u0003לא הקריבו\u0004 את ה\u0003כבש\u0004 לקרבן תמיד הבא \u0003בבוקר\u0004 — יקריבו את כבש קרבן התמיד של בין הערביים. וכן שאם לא הקטירו את מחצית הקטורת הבאה בבוקר — יקטירו את המחצית הבאה בערב. ובענין זה \u0003אמר ר' שמעון: ו\u0004כל הקטורת \u0003כולה,\u0004 ואף המחצית שהיתה צריכה להיות מוקטרת בבוקר, \u0003היתה קריבה בין הערבים.\u0004 ובטעם הדבר: \u0003ש\u0004הרי \u0003אין מחנכין את מזבח הזהב אלא ב\u0004הקטרת מידה שלימה (מנה) של \u0003קטרת הסמים\u0004 ולא את מזבח העולה אלא בתמיד של שחר, ולא את שולחן הפנים אלא בסידור לחם הפנים ביום השבת, ולא את המנורה אלא בהדלקת שבעת נרותיה בין הערביים. ותוהים: ענין \u0003חינוך\u0004 של כלי המקדש ששנינו \u0003מאן דכר שמיה\u0004 \u0005[מי הזכיר\u0006 את \u0005שמו],\u0006 לאיזה צורך הובאו הדברים, שהרי אין זה עניינה של משנתנו?!","ומסבירים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא המשנה \u0005וכך היא שנויה]:\u0006 אם \u0003לא הקריבו כבש\u0004 לתמיד הבא \u0003בבקר\u0004 — \u0003לא יקריבו\u0004 את כבש התמיד הבא \u0003בין הערבים. במה דברים אמורים?\u0004 בזמן \u0003ש\u0004עדיין \u0003לא נתחנך המזבח\u0004 עד עכשיו. וכיון שדרך חינוכו של מזבח העולה הוא בהקרבת התמיד של שחר — אין מקריבים בו בתחילה את התמיד של בין הערביים. \u0003אבל\u0004 בזמן שכבר \u0003נתחנך המזבח,\u0004 אם לא הקריבו את כבש התמיד של שחר — \u0003יקריבו\u0004 את כבש התמיד של \u0003בין הערבים.\u0004","ובענין זה \u0003אמר ר' שמעון: אימתי\u0004 נאמרה הלכה זו? דווקא \u0003בזמן שהיו אנוסין או שוגגין\u0004 בדבר זה. \u0003אבל אם היו מזידין\u0004 בדבר, שלא הקריבוהו בזדון, כיון ש\u0003לא הקריבו\u0004 את \u0003כבש\u0004 התמיד הבא \u0003בבקר\u0004 — \u0003לא יקריבו\u0004 את כבש התמיד של \u0003בין הערבים.\u0004 ובענין הקטורת, אם \u0003לא הקטירו\u0004 את מחצית ה\u0003קטרת\u0004 הבאה \u0003בבקר\u0004 — \u0003יקטירו\u0004 את המחצית האחרת \u0003בין הערבים.\u0004","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאם לא הוקרב הכבש לקרבן תמיד של שחר, שוב אין מוקרב הכבש לתמיד של בין הערביים? \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה שנאמר בקרבנות התמיד \"את הכבש האחד תעשה בבוקר \u0003ואת הכבש השני תעשה בין הערבים\"\u0004 (שמות כט, לט) בא לומר שהקרבן ה\u0003שני\u0004 שבקרבנות התמיד של כל יום הוא הקרב \u0003בין הערבים, ולא\u0004 הקרבן ה\u0003ראשון\u0004 שבקרבנות התמיד יקרב \u0003בין הערבים.\u0004","ושבים לדברי המשנה, ובנוסח המשלים את החסר במשנתנו: \u0003במה דברים אמורים\u0004 שאין מקריבים את התמיד של בין הערביים אם לא הוקרב התמיד של שחר? רק בזמן \u0003ש\u0004עדיין \u0003לא נתחנך המזבח\u0004 עד עכשיו, שאין מקריבים את הקרבן הראשון לתחילת חינוכו של המזבח בין הערבים, שכן הכתוב \"ואת הכבש השני תעשה בין הערביים\" בחינוכו של מזבח נאמר. \u0003אבל\u0004 אם כבר \u0003נתחנך המזבח\u0004 — \u0003אפילו\u0004 את ה\u0003ראשון\u0004 מקריבים \u0003בין הערבים.\u0004","\u0003אמר ר' שמעון: אימתי\u0004 אמור דין זה? רק \u0003בזמן שהיו אנוסין או שוגגין\u0004 בזה שלא הוקרב התמיד של שחר. \u0003אבל אם היו מזידין\u0004 בדבר, אם \u0003לא הקריבו\u0004 את \u0003כבש\u0004 התמיד הבא \u0003בבקר\u0004 — \u0003לא יקריבו\u0004 את כבש התמיד של \u0003בין הערבים.\u0004 ובענין הקטורת, אף אם \u0003לא הקטירו קטרת בבוקר\u0004 — \u0003יקטירו בין הערבים.\u0004","ותוהים על דברי ר' שמעון: \u0003וכי\u0004 משום שה\u0003כהנים חטאו,\u0004 יהא ה\u0003מזבח בטל\u0004 לגמרי?! \u0003אמר\u0004 \u0003רבא, הכי קאמר\u0004 \u0005[כך הוא,\u0006 ר' שמעון \u0005אומר,\u0006 זו כוונת דבריו\u0005]:\u0006 אם לא קרב תמיד של שחר בזדון הכהנים — \u0003לא יקריבו הן\u0004 (אותם כהנים) את כבש התמיד של בין הערביים, \u0003אבל\u0004 כהנים \u0003אחרים\u0004 — \u0003יקריבו.\u0004","אבל אם \u0003לא הקטירו\u0004 הכהנים את ה\u0003קטרת בבקר\u0004 בזדון — אף אותם כהנים \u0003יקטירו\u0004 את קטורת \u0003בין הערבים,\u0004 שבזה אין קונסים אותם, ומדוע? ש\u0003כיון\u0004 שהקטרת הקטורת \u0003לא שכיחא\u0004 \u0005[אינה מצויה]\u0006 כהקרבת התמיד (שהוא קרבן עולה, הקרב לרוב), \u0003ו\u0004מלבד זאת, יש בקטורת מעלה שהיא \u0003מעתרא\u0004 \u0005[מעשירה]\u0006 את מקטיריה, משום כך הריהי \u0003חביבא להו\u0004 \u0005[חביבה עליהם,\u0006 על הכהנים\u0005],\u0006 \u0003ולא פשעי\u0004 \u0005[ולא מתרשלים]\u0006 בה.","שנינו במשנתנו ש\u0003אמר ר' שמעון\u0004 שקטורת שלא הוקטרה מחציתה בבוקר \u0003כולה היתה קריבה בין הערבים,\u0004 ושלא כדעת חכמים שרק מחציתה היתה מוקטרת בערב. וטעם שיטתו זו: \u0003ש\u0004הרי \u0003אין מחנכין את מזבח הזהב אלא בקטרת הסמים של בין הערבים וכו'.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בדרך חינוכו של מזבח הזהב שהוא נעשה \u0003בקטרת הסמים של שחר!\u0004 ומשיבים: הלכה זו במחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 שנויה, שיש אומרים שחנוכת מזבח הזהב היא בהקטרת קטורת הסמים של ערב, ויש אומרים שחינוכו בהקטרת קטורת הסמים של שחר.","וכהצעה להכרעתה של מחלוקת זו, \u0003אמר אביי: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר \u0003כ\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003בקטרת הסמים של בין הערבים\u0004 היה נחנך מזבח הזהב, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במזבח הזהב \"והקטיר עליו אהרן קטורת סמים \u0003בבקר בבקר בהיטיבו את הנרות יקטירנה.\u0004 ובהעלות אהרן את הנרות בין הערביים יקטירנה קטורת תמיד לפני ה' לדורותיכם\" (שמות ל, ז-ח).","ומתוך דברי הכתוב שהטבת הנרות נעשית בבוקר, נלמד כי קדמה לה הדלקתם של שבעת נרות המנורה בין הערביים, שהרי \u0003אי לאו דעבד\u0004 \u0005[אם לא שעשה]\u0006 כבר הכהן \u0003הדלקה מאורתא\u0004 \u0005[מהערב],\u0006 \u0003הטבה\u0004 (דישון הנרות, ניקויים מאפר הפתילות) \u0003בצפרא מהיכא\u0004 \u0005[בבוקר מהיכן\u0006 תבוא\u0005]?!\u0006 ומכאן ראיה כי חינוך המנורה הינו בהדלקת בין הערביים. ומכאן נלמד כי אף חינוך מזבח הזהב נעשה בין הערביים (שהרי כרך הכתוב כאחד את חינוכם של מזבח הזהב והמנורה)!","ושואלים: \u0003ול\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי מזבח הזהב נחנך \u0003בקטרת הסמים של שחר,\u0004 מנין לו? ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בהיקש \u0003מ\u0004דרך חינוכו של \u0003מזבח העולה, מה להלן\u0004 (שם, במזבח העולה) הריהו נחנך \u0003ב\u0004הקרבת כבש ה\u0003תמיד של שחר\u0004 ולא של בין הערביים — \u0003אף כאן,\u0004 במזבח הזהב — הריהו נחנך \u0003בקטרת הסמים של שחר,\u0004 ולא בקטורת של בין הערביים.","\u0003ו\u0004עוד שנינו במשנתנו באופני חינוך כלי המקדש כי \u0003לא\u0004 היו מחנכים \u0003את השלחן אלא בלחם הפנים\u0004 שמסדרים עליו \u0003ב\u0004יום ה\u0003שבת.\u0004 ומקשים: \u0003אלא\u0004 נסיק מכאן שסידור הלחם \u0003ב\u0004יום \u0003חול\u0004 — רק לענין \u0003איחנוכי\u0004 \u0005[חינוך]\u0006 \u0003הוא\u0004 ש\u0003לא מחנך\u0004 \u0005[חונך]\u0006 את השולחן, \u0003הא קדושי\u0004 \u0005[הרי\u0006 כי לענין \u0005קידוש]\u0006 — הלחם הריהו \u0003מיקדיש\u0004 \u0005[מוקדש]\u0006 כשמסדר אותו על השולחן בחול?! והרי זה שלא כהלכה, שכן רק סידור הלחם ביום השבת הוא המקדש את הלחם!","ומשיבים: \u0003היא גופה\u0004 \u0005[עצמה],\u0006 את ההלכה הזו \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 תנא משנתנו, \u0005משמיע לנו],\u0006 שהן ה\u0003חינוך\u0004 של השולחן, \u0003ו\u0004הן ה\u0003קידוש\u0004 של הלחם — בסידור הלחם על ה\u0003שלחן בשבת הוא.\u0004 ו\u0003כדקתני סיפא\u0004 \u0005[כמו שהוא שונה בסוף\u0006 משנתנו\u0005]\u0006 בענין חינוכה של המנורה: \u0003ולא\u0004 מחנכים \u0003את המנורה אלא ב\u0004הדלקת \u0003שבעה נרותיה בין הערבים,\u0004 והרי בכלל חינוכה של המנורה אף קידושה. וכך הוא גם בענין חינוכו וקידושו של השולחן ולחם הפנים.","ומביאים עוד בדין הקטרת הקטורת מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בעניינה של הקטרה מסויימת (שיתברר טיבה להלן) שיש בה כמה צדדי ייחוד: \u0003זהו קטרת שעלתה ל\u0004אדם \u0003יחיד,\u0004 ולא לציבור, המביא כרגיל את הקטורת, והוקטרה \u0003על מזבח החיצון,\u0004 ולא על המזבח הפנימי, מזבח הזהב, כקטורת הרגילה, \u0003ו\u0004הקטרתה לא הותרה לדורות, אלא \u0003הוראת שעה היתה,\u0004 שלא הותר לעשות כן אלא באותו זמן בלבד. ובתחילה מבררים: \u0003היכא\u0004 \u0005[היכן,\u0006 באיזו קטורת\u0005]\u0006 נאמרו הדברים הללו? \u0003אמר רב פפא:\u0004 מדובר \u0003ב\u0004קטורת שהביא עימו כל אחד מן ה\u0003נשיאים\u0004 (נשיאי שבטי ישראל) בזמן חנוכת המשכן במדבר (כנאמר בקרבנו של נחשון בן עמינדב נשיא שבט יהודה המקריב הראשון \"כף אחת עשרה זהב מלאה קטורת\". במדבר ז, יד. וכן בקרבנותיהם של שאר הנשיאים), והוקטרה קטורת זו על המזבח החיצון.","ומקשים: מן הנאמר בברייתא שהוראת שעה היתה הקרבה זו, אין אנו למדים \u0003אלא\u0004 שכרגיל (שלא בהוראת שעה) קטורתו של \u0003יחיד\u0004 דווקא \u0003על מזבח החיצון הוא\u0004 ש\u0003לא\u0004 מקטירים אותה, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נסיק ש\u0003על מזבח הפנימי\u0004 — \u0003מקריב\u0004 אותה. \u0003ותו\u0004 \u0005[ועוד]:\u0006 מן הנאמר בברייתא שבהוראת שעה היתה הקטרה זו, נלמד שכרגיל \u0003על מזבח החיצון\u0004 דווקא \u0003יחיד הוא\u0004 ש\u0003לא\u0004 מקטיר קטורת, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נסיק ש\u0003ציבור מקרבו\u0004 \u0005[מקריבים]\u0006 קטורת על מזבח החיצון.","\u0003ו\u0004אולם \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 מפורשת שלא כשני דיוקים אלה. שכן שנינו בה: \u0003יכול יהא\u0004 הדין ש\u0003יחיד מתנדב\u0004 קטורת למקדש \u0003ומביא, כיוצא בה\u0004 בקטורת הנשיאים שבאה ב\u0003נדבה, וקורא אני בה\u0004 בנדבה זו, כמו בשאר נדבות, את הכתוב \u0003\"מוצא שפתיך תשמר ועשית\u0004 כאשר נדרת לה' אלהיך נדבה אשר דברת בפיך\" (דברים כג, כד)? \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) במזבח הפנימי \u0003\"לא תעלו עליו קטרת זרה\"\u0004 (שמות ל, ט). הרי איפוא שאין היחיד מקטיר קטורת על המזבח הפנימי, שלא כדיוק הראשון בדברי הברייתא!","ועוד שנינו בה בהמשך אותה ברייתא: \u0003יכול לא יהא\u0004 כן הדין אלא רק ב\u0003יחיד\u0004 ה\u0003מביא\u0004 קטורת, וטעם הדבר: \u0003ש\u0004הרי \u0003אין\u0004 היחיד \u0003מביא חובתו כיוצא בה,\u0004 שהרי אין עליו שום קרבן חובה של קטורת,"],["\u0003אבל\u0004 ב\u0003צבור יהא מביא\u0004 קטורת בנדבה, \u0003ש\u0004הרי הציבור אף \u0003מביא\u0004 קטורת \u0003חובה כיוצא בה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בלשון רבים \u0003\"לא תעלו\u0004 עליו קטורת זרה\" (שמות ל, ט), להורות שאף הציבור אינם מביאים קטורת נדבה.","ועדיין שמא \u0003יכול\u0004 שמכתוב זה למדים אנו כי \u0003לא יעלו\u0004 הציבור קטורת נדבה דווקא \u0003על מזבח הפנימי,\u0004 \u0003אבל יעלו\u0004 הציבור קטורת נדבה \u0003על מזבח החיצון?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בעשיית המשכן \"ו \u0003את שמן המשחה ואת קטרת הסמים לקדש ככל אשר צויתך יעשו\"\u0004 (שם לא, יא) — לומר: \u0003אין לך אלא מה שאמור בענין\u0004 ולא באופן אחר, שאין הקטורת באה אלא בציבור, וכחובה, ומוקטרת על המזבח הפנימי. וקשה על הדיוק השני בדברי הברייתא, שהציבור מביא קטורת נדבה!","\u0003אמר רב פפא:\u0004 אין זה קשה שכן בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה הוא אומר].\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 לומר שה\u0003ציבור\u0004 אינו מקטיר קטורת נדבה \u0003על מזבח החיצון,\u0004 שהרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 בציבור אופן כזה של הקטרה. \u0003ו\u0004כמו כן \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 לומר שה\u0003יחיד\u0004 אינו מקטיר \u0003על מזבח הפנימי,\u0004 שהרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 בו אופן זה של הקטרה. \u0003אלא אפילו\u0004 הקטרת \u0003יחיד על מזבח החיצון, דאשכחן\u0004 \u0005[שמצאנו]\u0006 כיוצא בה \u0003בנשיאים\u0004 — גם היא אסורה, שכן אף הקטרת הנשיאים \u0003הוראת שעה היתה\u0004 ואין למדים ממנה.","שתים עשרה חלות המצות (הנעשות מעשירית האיפה סולת) של מנחת \u0003חביתי כהן גדול\u0004 (ונקראת מנחה זו \"מנחת חביתין\" — על שמטגנים אותה במחבת אחר אפייתה) המובאות בכל יום מחציתן בבוקר ומחציתן בערב, \u0003לא היו באין\u0004 מביתו של הכהן הגדול בשני \u0003חצאין,\u0004 שיביא בכל פעם את המחצית הקריבה, \u0003אלא\u0004 הריהו \u0003מביא\u0004 בכל יום למנחתו \u0003עשרון\u0004 (\"עשירית האיפה סולת\", ויקרא ו, יג) \u0003שלם, וחוצהו\u0004 לשני חצאים — והריהו \u0003מקריב מחצה\u0004 אחת \u0003בבקר ו\u0004את ה\u0003מחצה\u0004 השנית \u0003בין הערבים.\u0004","\u0003כהן\u0004 גדול \u0003שמביא\u0004 (הקריב) את ה\u0003מחצה\u0004 הראשונה ב\u0003שחרית,\u0004 \u0003ו\u0004לאחר מכן \u0003מת, ומינו כהן אחר תחתיו\u0004 לשמש ככהן גדול — \u0003לא יביא\u0004 הכהן הגדול החדש \u0003חצי עשרון מביתו\u0004 לצורך הקרבת בין הערביים, וכמו כן לא יקריב את \u0003חצי עשרונו של\u0004 הכהן הגדול ה\u0003ראשון\u0004 (הקודם) שמת, \u0003אלא\u0004 \u0003מביא\u0004 מביתו \u0003עשרון שלם, וחוצהו\u0004 ו\u0003מקריב מחצה\u0004 אחת בין הערביים, \u0003ו\u0004אילו ה\u0003מחצה\u0004 השנית \u0003אבד,\u0004 שאינו קרב. \u0003נמצאו\u0004 איפוא כי במקרה זה \u0003שני חצאין\u0004 של שני העשרונות הללו (מחצית אחת משל הכהן הראשון, ומחצית אחת משל השני) \u0003קריבין, ושני\u0004 ה\u0003חצאין\u0004 האחרים \u0003אובדין.\u0004","שנינו במשנתנו בדין הבאת שתי מחציותיה של מנחת חביתים. ומביאים עוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על הכתוב במנחת החביתים \"זה קרבן אהרן... עשירית האיפה סולת מנחה תמיד מחציתה בבוקר ומחציתה בערב\" (שם): \u0003אילו\u0004 היה \u0003נאמר \"מנחה\u0004 תמיד \u0003מחצית\u0004 בבוקר ומחצית בערב\" — \u0003הייתי אומר\u0004 מכאן שהכהן הגדול \u0003מביא חצי עשרון\u0004 (\"מחצית\") \u0003מביתו\u0004 ב\u0003שחרית ומקריב\u0004 אותו, ואחר כך מביא עוד \u0003חצי עשרון מביתו\u0004 ב\u0003ערבית ומקריב\u0004 אותו — לכך","\u0003תלמוד לומר\u0004 \u0003\"מחציתה בבקר ומחציתה בערב\"\u0004 — \u0003מחצה משלם הוא מקריב, הא\u0004 \u0005[הרי]\u0006 זה \u0003כיצד\u0004 נעשה? הריהו \u0003מביא\u0004 מביתו \u0003בבוקר\u0004 \u0003עשרון\u0004 סולת \u0003שלם וחוצהו\u0004 לשתי מחציות, \u0003ומקריב מחצה\u0004 אחת \u0003בבקר, ו\u0004את ה\u0003מחצה\u0004 השנית הריהו מקריב \u0003בין הערבים.\u0004","ואם אירע ולאחר שקרבה המחצית של שחר, \u0003נטמא\u0004 ה\u0003מחצה של בין הערבים, או שאבד\u0004 מחצה זה, \u0003יכול\u0004 צריכים היינו לומר ש\u0003יביא\u0004 הכהן הגדול \u0003חצי עשרון מביתו\u0004 ב\u0003ערבית ויקריב?\u0004 לכך \u0003תלמוד לומר \"מחציתה בבקר ומחציתה בערב\"\u0004 — \u0003מחצה משלם הוא מביא.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 זה \u0003כיצד\u0004 נעשה? הריהו \u0003מביא עשרון שלם\u0004 נוסף \u0003מביתו,\u0004 לפני בין הערביים, \u0003וחוצהו\u0004 לשתי מחציות. \u0003ומקריב\u0004 \u0003מחצה\u0004 אחת מהן, \u0003ו\u0004ה\u0003מחצה\u0004 השנית \u0003אבד. נמצאו\u0004 איפוא כי \u0003במקרה זה\u0004 \u0003שני חצאין\u0004 (מחצית העשרון הראשון שקרבה בבוקר, ומחצית העשרון השני שקרבה בין הערביים) \u0003קריבין, ושני חצאין\u0004 (המחצית השניה של העשרון הראשון שנטמאה או שאבדה, והמחצית השניה של העשרון השני)","\u0003אובדין. כהן גדול ש\u0004הביא עשרון סולת מביתו, ו\u0003הקריב\u0004 את ה\u0003מחצה\u0004 הראשונה שלו ב\u0003שחרית ומת\u0004 לאחר מכן, \u0003ומינו\u0004 כהן גדול \u0003אחר תחתיו, יכול\u0004 תאמר ש\u0003יביא\u0004 הכהן הגדול החדש \u0003חצי עשרון מביתו\u0004 להקרבת מחצית מנחת החביתים של בין הערביים. \u0003או\u0004 שיביא הכהן הגדול החדש את \u0003חצי עשרונו של\u0004 הכהן הגדול ה\u0003ראשון\u0004 (הקודם)? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"ומחציתה בערב\"\u0004 — \u0003מחצה משלם הוא מביא ומקריב.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 זה \u0003כיצד\u0004 יעשה הכהן הגדול החדש? הריהו \u0003מביא\u0004 מביתו \u0003עשרון\u0004 סולת \u0003שלם, וחוצהו, ומקריב\u0004 מחצית אחת, \u0003ו\u0004אילו ה\u0003מחצה\u0004 השנית של עשרון \u0003זה —\u0004 \u0003אבד. נמצאו\u0004 איפוא כי במקרה זה \u0003שני חצאין\u0004 (המחצית השניה של עשרון הכהן הגדול שמת, והמחצית השניה של עשרון הכהן הגדול החדש) — \u0003אובדין, ושני חצאין\u0004 (המחצית הראשונה של עשרון הכהן הגדול שמת, והמחצית הראשונה של עשרון הכהן הגדול החדש) — \u0003קריבין.\u0004","שנינו בברייתא בדין מנחת חביתים של כהן גדול שמת לאחר הקרבת מנחת חביתים של בוקר והתמנה כהן גדול חדש תחתיו, כי שתי מחציות אבדו, זו של הכהן שמת וזו של הכהן החדש. ובענין זה \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: מחצה\u0004 של הכהן ה\u0003ראשון\u0004 (שמת) \u0003ומחצה\u0004 של הכהן ה\u0003שני\u0004 שהולכות לאיבוד — \u0003תעובר צורתן\u0004 תחילה. כלומר, ימתין להם עד שיעבור עליהם לילה ויפסלו בלינה, \u0003ו\u0004אז \u0003יצאו לבית השריפה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן:\u0004 \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן\u0005]\u0006 שיש לפסול בלינה את החצי של הכהן ה\u0003ראשון\u0004 לפני שמוציאים אותו לשריפה — שכן \u0003איחזי\u0004 \u0005[היה ראוי]\u0006 חצי זה \u0003להקרבה\u0004 מתחילה, לפני שמת הכהן הגדול הקודם, ולכן אי אפשר לאבדו מיד. \u0003אלא\u0004 החצי של הכהן הגדול ה\u0003שני למה ליה\u0004 \u0005[לו]\u0006 \u0003עיבור צורה?\u0004 והרי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006, מייד כשהובא עשרון סולת שלם ונחצה לשניים, לא היה ראוי חצי זה להקרבה והיה ברור כי \u0003לאיבוד קא אתי\u0004 \u0005[הוא הולך]\u0006 ומדוע יהא צריך לעיבור צורה?","אלא זה ש\u0003אמר לך\u0004 גירסה זו של דבריך, \u0003מני\u0004 \u0005[מי הוא]?\u0006 ה\u0003תנא דבי\u0004 \u0005[של בית\u0006\u0003]\u0004 מדרשו של \u0003רבה בר אבוה הוא,\u0004 שכן \u0003אמר\u0004 רבה בר אבוה כי כל קודש שנפסל, ו\u0003אפילו\u0004 פסול \u0003פיגול\u0004 שחמור, ופסול מן התורה — אינו נשרף מייד, אלא \u0003טעון\u0004 תחילה \u0003עיבור צורה,\u0004 ורק לאחר מכן יוצא לבית השריפה.","\u0003רב אשי אמר\u0004 הסבר אחר לנוסח הדברים: \u0003אפילו\u0004 \u0003תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על רבה בר אבוה, וסבורים כי הנפסל בפיגול אינו טעון עיבור צורה, \u0003כיון דבעידנא דפלגי בהו\u0004 \u0005[שבזמן שחולק אותם]\u0006 הכהן הגדול החדש את שתי המחציות מהעשרון שהביא, \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — הרי את \u0003האי\u0004 \u0005[זה]\u0006 החצי הוא \u0003מקריב, ואי בעי\u0004 \u0005[ואם רוצה]\u0006 — את \u0003האי\u0004 \u0005[זה]\u0006 החצי השני הוא \u0003מקריב,\u0004 שהרי אין חצי מסויים שהוגדר מתחילה לקדושה, אם כן שני החצאים הללו נחשבים כ\u0003מיחזא חזו\u0004 \u0005[ראויים]\u0006 להקרבה, ולכך יש להמתין בשריפתו של השני עד שייפסל בלינה\u0005.\u0006","ומביאים עוד בדין מנחת חביתים. \u0003איתמר\u0004 \u0005[נאמר]\u0006 בברייתא: \u0003חביתי כהן גדול, כיצד\u0004 בדיוק \u0003עושין אותן?\u0004 שכן נאמר בהם \"על מחבת בשמן תעשה מורבכת תביאנה תופיני מנחת פתים תקריב\" (שם יד), והרי אלה אופני עשייה שונים. \u0003ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן\u0004 שכך מנחת חביתים נעשית: בתחילה הריהו \u0003אופה\u0004 בתנור, \u0003ואחר כך\u0004 הריהו \u0003מטגנה\u0004 במחבת. ואילו \u0003ר' אסי אמר\u0004 בשם \u0003ר' חנינא\u0004 שבתחילה \u0003הריהו\u0004 \u0003מטגנה\u0004 במחבת, \u0003ואחר כך\u0004 הוא \u0003אופה\u0004 בתנור.","ומסבירים חכמים אלה את שיטותיהם, \u0003אמר ר' חייא בר אבא: כוותיה דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר]\u0006 לומר — שכן הכתוב \u0003\"תפיני\"\u0004 פירושו: \u0003תאפינה נאה,\u0004 שצריכה המנחה להיות נאה בשעה שהיא נאפית בתנור, ואילו יטגנוה בתחילה ורק לאחר מכן יאפוה — אין היא נאה בשעת אפייה. ואילו \u0003ר' אסי אמר: כוותיה דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר]\u0006 לומר — שכן הכתוב \u0003\"תפיני\"\u0004 פירושו: \u0003תאפינה נא,\u0004 שבשעת אפייתה בתנור תהא המנחה כבר מבושלת במקצת, אך לא מבושלת כל צורכה (\"נא\"). ולכך יש לטגנה לפני אפייתה.","ומעירים: מחלוקת אמוראים זו \u0003הריהי\u0004 \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 שחלקו כבר בנושא זה. שכך שנינו בברייתא: משמעות הכתוב \u0003\"תפיני\"\u0004 — \u0003תאפינה נא.\u0004 ואילו \u0003רבי אומר:\u0004 משמעות \"תופיני\" — \u0003תאפינה נאה.\u0004 ועוד דעה נוספת, \u0003ר' יוסי אומר:\u0004 אמר הכתוב \"תופיני\" בלשון רבים — \u0003תאפינה רבה\u0004 (הרבה), לומר שאופים אותה, ולאחר מכן מטגנים אותה, ושבים ואופים אותה. שכן \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 ר' יוסי הן את הדעה הסבורה שיש לאפות את המנחה כשהיא \u0003נא\u0004 (ולכך מטגננים אותה לפני אפייתה), \u0003ו\u0004אולם \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 ר' יוסי גם את הדעה הסבורה שיש לאפות את המנחה כשהיא \u0003נאה\u0004 (לפני טיגון), ולכך הריהו מצריך שתי אפיות, לפני טיגון ולאחר טיגון.","ועוד בדרך עשייתה של מנחת חביתי כהן גדול, \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה בהמשך\u0005]:\u0006 \u0003חביתי כהן גדול\u0004 — \u0003לישתן ועריכתן ואפייתן בפנים\u0004 העזרה שבמקדש, \u0003ודוחות את השבת.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שדוחה עשייתן את השבת? \u0003אמר רב הונא:\u0004 בענין מנחה זו נאמר \u0003\"תפיני\",\u0004 וכוונתו \u0003—\u0004 \u0003תאפינה נאה,\u0004 שכשהן אפויות שתהיינה נאות \u0003ואי אפי לה\u0004 \u0005[ואם אופה אותה]\u0006 \u0003מאתמול\u0004 — \u0003אינשפה\u0004 \u0005[התקלקלה]\u0006 \u0003לה\u0004 ושוב אינה נאה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 אם טעם הדבר הוא כדי למנוע את קלקולה של המנחה — \u0003אימא\u0004 \u0005[אמור]\u0006 שיאפה אותה בערב שבת, ו\u0003דכביש ליה בירקא\u0004 \u0005[ושיכבוש אותה,\u0006 יכסנה, \u0005בירק]\u0006 כדי שלא תתקלקל!","טעם אחר להיתר אפייתה של מנחת חביתים בשבת, החכם \u0003דבי\u0004 \u0005[של ביתו]\u0006 מדרשו של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 נאמר \"על מחבת בשמן תעשה\", והלשון \u0003\"תעשה\"\u0004 באה להדגיש שתיעשה המנחה בכל אופן ומצב, \u0003ואפילו בשבת, \"תעשה\"\u0004 — \u0003ואפילו בטומאה.\u0004","טעם אחר \u0003אביי אמר,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"סלת מנחה תמיד\"\u0004 (שם),"],["ומלשון הכתוב למדים אנו שדין מנחת חביתים \u0003הרי היא כמנחת תמידין.\u0004 ומכאן נסיק כי כשם שקרבנות התמיד דוחים את השבת (כנאמר בהם \"עולת שבת בשבתו על עולת התמיד ונסכה\", במדבר כח, י) — אף עשיית מנחת החביתים דוחה את השבת.","\u0003רבא אמר\u0004 מקור אחר, שכן מה שנאמר בה \u0003\"על מחבת\u0004 בשמן תיעשה...\" (ויקרא ו, יד) \u0003מלמד ש\u0004מנחת חביתים \u0003טעונה כלי\u0004 שרת לעשייתה. \u0003ו\u0004מעתה \u0003אי אפי לה\u0004 \u0005[אם אופה אותה]\u0006 שלא ביום השבת, אלא \u0003מאתמול\u0004 — \u0003איפסיל ליה\u0004 \u0005[נפסלה לה]\u0006 המנחה \u0003בלינה,\u0004 שהרי התקדשה בכלי השרת. \u0003ומעירים:\u0004 \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא:\u0004 מה שנאמר \u0003\"על מחבת\"\u0004 — \u0003מלמד שטעונה כלי.\u0004","ומאחר שהביאו את תחילתה של ברייתא זו, מביאים עוד מדבריה על הכתוב \"על מחבת בשמן תיעשה\": המלה \u0003\"בשמן\"\u0004 שבכתוב זה (בה\"א הידיעה, וכאילו נאמר \"בהשמן\") — מורה כי \u0003יש\u0004 \u0003להוסיף לה\u0004 למנחה זו \u0003שמן\u0004 יתר\u0003.\u0004 \u0003ו\u0004אולם עדיין \u0003איני יודע\u0004 מלימוד \u0003זה\u0004","\u0003כמה\u0004 שמן יש להוסיף. ולכך \u0003הריני דן \u0004דבר זה כך: \u0003נאמר כאן\u0004 (במנחת חביתים) \u0003\"שמן\", ו\u0004כמו כן \u0003נאמר להלן\u0004 (שם, בספר שמות) \u0003במנחת\u0004 ה\u0003נסכים\u0004 \u0003\"שמן\"\u0004 (\"וזה אשר תעשה על המזבח כבשים בני שנה שנים ליום תמיד... ועשרון סולת בלול בשמן כתית רבע ההין ונסך רביעית ההין יין לכבש האחד\". שם לח-מ). \u0003מה להלן\u0004 במנחת נסכי התמיד — שיעור השמן הניתן הוא \u0003שלשת לוגין\u0004 שמן \u0003לעשרון\u0004 סולת, \u0003אף כאן\u0004 במנחת חביתים — שיעור השמן הניתן הוא \u0003שלשת לוגין\u0004 שמן \u0003לעשרון\u0004 סולת.","\u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך\u0004 דרשה \u0003זו: נאמר כאן\u0004 במנחת חביתים \u0003\"שמן\", ו\u0004כמו כן \u0003נאמר במנחת נדבה \"שמן\"\u0004 (\"ונפש כי תקריב קרבן מנחה לה' סולת יהיה קרבנו ויצק עליה שמן ונתן עליה לבונה\". ויקרא ב, א). \u0003מה להלן\u0004 במנחת נדבה — שיעור השמן הניתן הוא \u0003לוג אחד\u0004 לעשרון (כנלמד להלן מנחות פח,א). \u0003אף כאן\u0004 (במנחת חביתים) — שיעור השמן הניתן בעשרון הוא \u0003לוג אחד.\u0004","ומאחר שיש שתי אפשרויות לימוד, \u0003נראה למי\u0004 מבין אלה \u0003דומה\u0004 יותר מנחת חביתים. מצד אחד יש לומר כי ראוי הוא שנהיה \u0003דנין\u0004 (למדים בגזירה שווה) דבר שיש בו ארבעה דינים שסימנם בראשי תיבות הוא \u0003תבש\"ט מ\u0004דבר שאף בו יש ארבעת הדינים הללו שסימנם הוא \u0003תבש\"ט,\u0004 שהם ראשי תיבות של המלים: \u0003תדיר\u0004 (שהרי הן מנחת התמיד והן מנחת חביתים באות פעמיים בכל יום ויום, מה שאין כן מנחת נדבה הבאה לעיתים); \u0003באה חובה\u0004 (שהן מנחת התמיד והן מנחת חביתים הן חובה, מה שאין כן מנחת נדבה); \u0003דוחה שבת\u0004 (שהן מנחת התמיד והן מנחת החביתים דוחות את השבת, מה שאין כן מנחת נדבה); \u0003דוחה טומאה\u0004 (שכן מנחת התמיד ומנחת החביתים, בהיותן מנחות ציבור, קרבות אף בטומאה. מה שאין כן מנחת נדבה), וראוי איפוא ללמוד ממנחת נסכי התמיד את דין מנחת חביתים.","\u0003ואין\u0004 אנו \u0003דנין\u0004 את דינו של דבר שיש בו \u0003תבש\"ט מ\u0004דבר (כמנחת נדבה) \u0003שאינו תבש\"ט.\u0004","\u0003או\u0004 שמא \u0003כלך לדרך זו: דנין\u0004 דבר זה שיש בו ארבעה דינים שסימנם בראשי תיבות הוא \u0003יגי\"ל מ\u0004דבר זה שאף בו יש ארבעת הדינים הללו שסימנם הוא \u0003יגי\"ל,\u0004 שהם ראשי תיבות של המלים: \u0003יחיד\u0004 (שהן מנחת נדבה והן מנחת חביתים באות על ידי היחיד. מה שאין כן מנחת נסכי התמיד שהיא קרבן ציבור); באה \u0003בגלל עצמה\u0004 (הן מנחת נדבה והן מנחת חביתים באות כשלעצמן, שאינן נלוות לקרבן כלשהו. מה שאין כן מנחת נסכי התמיד שנלווית לתמיד); טעונה \u0003יין\u0004 (הן למנחת הנדבה והן למנחת החביתים נלווה יין. מה שאין כן למנחת הנסכים עצמה אין נסכי היין הבאים אתה נלווים אליה אלא לקרבן התמיד); וטעונה \u0003לבונה\u0004 (הן מנחת הנדבה והן מנחת החביתים. מה שאין כן מנחת נסכי התמיד).","\u0003ואין\u0004 אנו \u0003דנין\u0004 את דינו של דבר שיש בו \u0003יגי\"ל\u0004 כמנחת חביתים \u0003מ\u0004דבר \u0003שאינו יגי\"ל.\u0004 ונמצא איפוא כי שקולות הן שתי אפשרויות הלימוד הללו.","ומעתה בהכרעת השאלה מהו שיעור השמן הבא במנחת חביתים, \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 נאמר במנחת חביתים \"זה קרבן אהרן... עשירית האיפה סלת מנחה תמיד מחציתה בבוקר ומחציתה בערב\" (ויקרא ו, יג), ובא הכתוב \u0003\"סלת מנחה תמיד\"\u0004 המכנה את מנחת אהרן \"תמיד\" — להורות: \u0003הרי היא לך ב\u0004דינה של \u0003מנחת תמידין,\u0004 ונלמד ממנחת התמידים: \u0003מה מנחת תמידין\u0004 — שיעור השמן המובא בה הוא \u0003שלשה לוגין לעשרון\u0004 סולת, \u0003אף\u0004 במנחה \u0003זו\u0004 (מנחת חביתים) — שיעור השמן המובא בה הוא \u0003שלשה לוגין לעשרון.\u0004","\u0003שמעון אומר: ריבה כאן\u0004 (במנחת נדבה) הכתוב בשיעור ה\u0003שמן\u0004 הניתן בה, \u0003ו\u0004כן \u0003ריבה\u0004 הכתוב \u0003במנחת\u0004 נסכי ה\u0003כבשים\u0004 בשיעור ה\u0003שמן\u0004 המובא בה, שהוא יותר מלוג שמן. \u0003מה להלן\u0004 (שם, במנחת נסכי הכבשים) — שיעור שמנם הוא \u0003שלשת לוגין לעשרון\u0004 סולת, \u0003אף כאן\u0004 במנחת חביתים — שיעור שמנה הריהו\u0003 שלשת לוגין לעשרון\u0004 סולת.","\u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך זו: ריבה\u0004 הכתוב \u0003כאן\u0004 ב\u0003שמן, ו\u0004כמו כן \u0003ריבה\u0004 הכתוב אף \u0003במנחת\u0004 הנסכים הבאה עם ה\u0003פרים ו\u0004ה\u0003אילים\u0004 בשיעור ה\u0003שמן\u0004 המובא בהם. \u0003מה להלן\u0004 (שם, במנחת נסכי פרים ואילים) — שיעור שמנם הוא \u0003שני לוגין לעשרון\u0004 סולת, \u0003אף כאן\u0004 במנחת חביתים — שיעור שמנם הוא \u0003שני לוגין לעשרון?\u0004","ומעתה, ששתי אפשרויות לימוד הן, \u0003נראה למי\u0004 מבין אלה השתיים \u0003דומה\u0004 יותר מנחת חביתים. מצד אחד ראוי שנהיה \u0003דנין\u0004 (למדים) את דינה של מנחת חביתים שהיא \u0003מנחה הבאה\u0004 מ\u0003עשרון\u0004 סולת בלבד \u0003מ\u0004דינה של מנחת נסכי הכבשים, שאף היא \u0003מנחה הבאה בעשרון,\u0004 \u0003ואין\u0004 ראוי שנהיה \u0003דנין\u0004 את דינה של ה\u0003מנחה הבאה עשרון מ\u0004דינה של \u0003מנחה הבאה שנים ושלשה עשרונים\u0004 כמנחת פרים ואילים.","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה,\u0006 סותרים דבריה אלה את אלה\u0005],\u0006 שכן בתחילה \u0003אמרת\u0004 בברייתא שהכתוב \u0003\"בשמן\"\u0004 האמור במנחת חביתים בא להורות כי יש \u0003להוסיף לה שמן\u0004 יותר על הלוג האחד המובא במנחת נדבה. \u0003והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]\u0006 כהצעה שכיון ש\u0003נאמר כאן \"שמן\", ונאמר במנחת נדבה \"שמן\",\u0004 שיהיה שיעור השמן הניתן במנחת חביתים כשמן הניתן במנחת נדבה, והרי כבר למדנו כי הכתוב בא לרבות במתן השמן במנחת חביתים!","\u0003אמר אביי\u0004 בתירוץ שאלה זו: כשיטת \u0003מאן\u0004 \u0005[מי]\u0006 דעת ה\u0003תנא\u0004 הסבור שהכתוב \u0003\"בשמן\"\u0004 בא \u0003להוסיף\u0004 בשיעור שמנה של מנחת חביתים? — שיטת \u0003ר' שמעון היא,\u0004 הסבור כי מכתוב זה למדים שהתרבה שמנה של מנחת חביתים, ואולם כמה הוא ריבוי זה, הוא למד ממנחת נסכי הכבשים שהם שלשה לוגים שמן. \u0003ו\u0004בדרך \u0003\"אילו לא נאמר\" קאמר\u0004 \u0005[הוא,\u0006 ר' שמעון, \u0005אומר],\u0006 שאילו לא היה נאמר ריבוי זה של \"בשמן\" — היינו מעמידים את דינה של מנחת החביתים בלוג שמן אחד. \u0003וב\u0004הצעת השאלה שהועלתה בברייתא לאחר מכן שיילמד \u0003דינא\u0004 \u0005[הדין,\u0006 הגזירה שווה\u0005]\u0006 ממנחת נדבה, ולא יהיה שיעור מנחת חביתים אלא לוג אחד בלבד — \u0003מאן קא מהדר\u0004 \u0005[מי הוא המחזיר,\u0006 השואל\u0005]\u0006? \u0003—\u0004 \u0003ר' ישמעאל\u0004 הוא.","ואילו \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר\u0004 הסבר אחר בתירוצה של שאלה זו: ברייתא זו \u0003כולה,\u0004 כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא,\u0004 הלמד את דין כמות השמן במנחת חביתים מהשוואתה למנחת התמיד.","\u0003ו\u0004אשר לאפשרות כי יילמד דינה של מנחת חביתים ממנחת נדבה, ויהיה שיעור שמנה לוג אחד בלבד — \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 לא בא הכתוב \u0003\"בשמן\"\u0004 אלא ללמדנו שיש \u0003להוסיף לה\u0004 למנחת החביתים \u0003שמן\u0004 על מידת השמן שבשאר מנחות. וראיה לדבר: \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שבא הכתוב רק \u0003לקבוע שמן,\u0004 כלומר, שיהיה בה שמן — לכך \u0003לא צריך\u0004 כתוב מיוחד במנחת חביתים, שהרי \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"על מחבת\"\u0004 — \u0003כמנחת מחבת דמיא\u0004 \u0005[\u0006הריהי \u0005דומה],\u0006 וממילא הריהי באה בשמן.","\u0003או\u0004 שמא תאמר כי כתוב זה אכן \u0003אינו\u0004 בא \u0003אלא לקבוע לה\u0004 חובת נתינת \u0003שמן,\u0004 וטעם הדבר שנצרכים אנו לכך — \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא כתב רחמנא\u0004 \u0005[לא היתה כותבת התורה]\u0006 \u0003\"בשמן\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003תיהוי\u0004 \u0005[תהיה]\u0006 מנחת החביתים \u0003כמנחת חוטא\u0004 שאין בה שמן כלל.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 ר' ישמעאל בנו של ר' יוחנן בן ברוקה בברייתא: אף אם \u0003תיהוי נמי\u0004 \u0005[תהיה גם כן]\u0006 כאפשרות השניה שהוצעה, שלא בא הכתוב \"בשמן\" אלא בשביל \u0003לקבוע לה שמן,\u0004 על כל פנים \u0003תיתי מדינא\u0004 \u0005[תילמד מהדין,\u0006 מגזירה שווה\u0005]\u0006 כמה שמן היא צריכה. \u0003ודן דינא\u0004 \u0005[דין,\u0006 גזירה שווה ממנחת נסכים\u0005]\u0006 \u0003ו\u0004אולם \u0003לא אתיא ליה\u0004 \u0005[באה,\u0006 עלתה \u0005לו]\u0006 הדרשה, שכן כנגדה אפשר להציב גזירה שווה אחרת. ולאחר שלא נלמד בדרך זו, \u0003עמד\u0004 \u0003ואצרכא קרא\u0004 \u0005[והצריך\u0006 לכך את דרשת ה\u0005מקרא]\u0006 \u0003\"סלת מנחה תמיד\" כ\u0004דרך שאמנם \u0003מסיים ר' ישמעאל\u0004 בנו של ר' יוחנן בן ברוקה את \u0003מילתיה\u0004 \u0005[הדבר,\u0006 את דברי הברייתא\u0005].\u0006","\u0003רבה אמר\u0004 הצעת הסבר אחרת בדברי ברייתא זו: \u0003כולה\u0004 כשיטת \u0003ר' שמעון\u0004 היא, \u0003ו\u0004בלשון \u0003\"אילו לא נאמר\" קאמר\u0004 \u0005[הוא אומר],\u0006","\u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 הכתוב \u0003\"בשמן\"\u0004 מלמדנו כי יש \u0003להוסיף לה שמן,\u0004 וטעם הדבר: \u0003דאי\u0004 \u0005[שאם]\u0006 לא בא הכתוב אלא כדי \u0003לקבוע לה\u0004 חובת נתינת \u0003שמן\u0004 (ובשיעור לוג) — לכך \u0003לא צריך\u0004 כתוב זה להיאמר, שהרי היינו יודעים זאת מעצמנו. ש\u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"על מחבת\"\u0004 — הרי \u0003כמחבת\u0004 \u0003דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שכשם שבמנחת מחבת יש שמן כך גם בה, \u0003ועד שלא יאמר\u0004 הכתוב \u0003\"בשמן\"\u0004 כבר \u0003יש לי\u0004 הלכה זו של חיוב מנחת חביתים בשמן, \u0003בדין.\u0004","הוסיף ר' שמעון \u0003ודן דינא\u0004 \u0005[דין,\u0006 גזירה שווה ממנחת נדבה\u0005]\u0006 ללמוד שאין במנחת חביתים אלא לוג אחד של שמן, ואולם \u0003לא אתיא ליה\u0004 \u0005[לא באה,\u0006 עלתה \u0005לו]\u0006 הדרשה, שכן כנגדה אפשר להציב גזירה שווה אחרת. ולאחר שלא נלמד הדבר בגזירה שווה, עמד \u0003ואצרכא\u0004 \u0005[והצריכה]\u0006 את דרשת הכתוב \u0003\"בשמן\".\u0004 ואולם, אף לאחר דרשה זו, אין אנו יודעים אלא שמרובה היא שיעור שמנה של מנחת חביתים משאר מנחות, ועדיין אין אנו יודעים בכמה. לכך \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר:\u0004 שמא \u0003תיהוי\u0004 \u0005[תהיה]\u0006 מנחת חביתים \u0003כמנחת פרים ואילים,\u0004 ששיעור שמנם הוא שני לוגים ולא שלושה.","ו\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 כי אין לומר כן, משום ש\u0003דנין\u0004"],["\u0003מנחה הבאה\u0004 מ\u0003עשרון\u0004 סולת ממנחה הבאה מעשרון סולת, ואין למדים דינה של מנחה הבאה מעשרון סולת ממנחה הבאה משלושה עשרונים (כמנחת נסכי הפר) או משני עשרונים (כמנחת נסכי האיל).","כהן גדול שהביא מנחת חביתים והקריב את מחציתה של בוקר ומת, ועדיין \u0003לא מינו כהן\u0004 גדול \u0003אחר תחתיו,\u0004 ועתה צריכים להקריב את מנחת החביתים של בין הערביים, \u0003מ\u0004נכסיו \u0003של מי היתה קריבה? ר' שמעון אומר: משל ציבור\u0004 היא באה. \u0003ר' יהודה אומר: מ\u0004נכסיהם \u0003של\u0004 ה\u0003יורשין\u0004 של הכהן הגדול היא באה. \u0003ו\u0004מודים הכל כי מנחת חביתים זו, כל עוד לא נתמנה כהן גדול חדש, מעשירית האיפה (\"עשרון\") סולת \u0003שלימה היתה קריבה.\u0004","בשאלה מממונו של מי באה מנחת חביתים בזמן שמת הכהן הגדול ועדיין לא מינו כהן גדול אחר תחתיו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כהן גדול שמת ולא מינו כהן אחר תחתיו, מנין שתהא מנחתו קריבה מ\u0004נכסיהם \u0003של\u0004 ה\u0003יורשין?\u0004 \u0003תלמוד לומר\u0004 בדינה של מנחת חביתים \u0003\"...והכהן המשיח תחתיו מבניו יעשה אתה\u0004 חק עולם לה' כליל תקטר\" (ויקרא ו, טו), ומן הנאמר \"והכהן המשיח תחתיו מבניו יעשה אותה\" למדים אנו שמשל יורשיו של הכהן הגדול הריהי נעשית.","\u0003יכול\u0004 שיורשו של הכהן הגדול שמת, אף הוא \u0003יקריבנה חצאין\u0004 כדרך שהיה מקריב הכהן הגדול שמת? לכך \u0003תלמוד לומר \"אתה\"\u0004 — לומר: את עשירית האיפה סולת \u0003כולה\u0004 הוא מביא \u0003ולא\u0004 את \u0003חציה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר:\u0004 מה שנאמר בכתוב \u0003זה\u0004 \u0003\"חק עולם\"\u0004 בא להורות כי באופן זה שמת הכהן הגדול, ולא מינו עדיין כהן גדול אחר, באה מנחת החביתים \u0003משל עולם\u0004 (הכלל, הציבור). ומה שנאמר בכתוב זה \u0003\"כליל תקטר\"\u0004 בא להורות: \u0003ש\u0004כיון שהיא באה משל ציבור, \u0003תהא כולה בהקטרה,\u0004 שהריהי קריבה שלימה ואינה נאכלת.","ומבררים את השיטות: ר' יהודה למד מן הכתוב \"והכהן המשיח תחתיו מבניו יעשה אותה\", \u0003ו\u0004אולם האם \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"הכהן המשיח\" להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד?","והרי \u0003האי מיבעי ליה\u0004 \u0005[זה\u0006 הכתוב \u0005נצרך לו]\u0006 לדרשה אחרת, \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"זה קרבן אהרן ובניו אשר יקריבו לה' ביום המשח אתו\"\u0004 בא להורות שכל כהן וכהן, הדיוט או גדול, מביא מנחה זו ביום היכנסו לעבודה (\"מנחת חינוך\"). ועדיין יש מקום לשאול: כיון שאחז הכתוב לשון יחיד (\"זה קרבן אהרן ובניו\") \u0003יכול\u0004 יהא הדין ש\u0003יהו אהרן ובניו מקריבין קרבן אחד\u0004 ביום המשחם? לכך \u0003תלמוד לומר\u0004 לאחר מכן \u0003\"אשר יקריבו לה' \"\u0004— \u0003אהרן\u0004 מקריב מנחה \u0003בפני עצמו\u0004 ככהן גדול, \u0003ובניו\u0004 מקריבים מנחה \u0003בפני עצמן,\u0004 ככהנים הדיוטות הנכנסים עתה לעבודתם, שאינה קרבה אלא פעם אחת. שכן \u0003\"בניו\"\u0004 — \u0003אלו כהנים הדיוטות.\u0004","ואולם עדיין יש מקום לשאול: \u0003אתה אומר\u0004 שכוונת הדברים ב\"בניו\" היא ל\u0003כהנים הדיוטות\u0004 ולגבי מנחת חינוכם, \u0003או\u0004 שמא מובן המלה \"בניו\" \u0003אינו אלא כהנים גדולים\u0004 הבאים אחרי אהרן הכהן הגדול הראשון, וללמדנו שדין מנחת חביתי כהן גדול נוהג בכל הכהנים הגדולים שיעמדו אחרי אהרן? \u0003הרי\u0004 \u0003כשהוא\u0004 (הכתוב) \u0003אומר\u0004 באותו ענין \u0003\"והכהן המשיח תחתיו מבניו\"\u0004 — \u0003הרי\u0004 דין מנחת חביתי \u0003כהן גדול אמור\u0004 כאן, ומעתה \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003מה אני מקיים\u0004 (מעמיד) את הכתוב \u0003\"בניו\"\u0004 האמור בפסוק \"זה קרבן אהרן ובניו\"? \u0003אלו כהנים הדיוטות,\u0004 ולענין מנחת חינוכם. הרי שאין עניינו של הכתוב הזה לענין יורשיו של כהן גדול שמת!","ומשיבים: פסוק זה בא ללמד הן לענין הבאת מנחת חביתיו של כהן גדול בידי יורשיו, והן לענין חובת הבאת מנחת חביתים בכל כהן גדול שיעמוד אחר אהרן הכהן. וראיה לדבר, ש\u0003אם כן\u0004 שבא הכתוב רק לענין הבאת מנחת חביתיו של כהן גדול בידי יורשיו — \u0003לכתוב קרא\u0004 \u0005[\u0006די היה \u0005שיכתוב המקרא]\u0006 \u0003\"הכהן המשיח תחתיו בניו יעשה\", מאי\u0004 \u0005[מה]\u0006 הוא לשון \u0003\"מבניו\"? שמעת מינה תרתי\u0004 \u0005[למד אתה מכאן שני\u0006 דברים\u0005],\u0006 הן לענין מנחת חביתים של כהן גדול שמת המובאת מאת יורשיו, והן לענין מנחת חביתים של כל כהן גדול שיעמוד \u0005אחר אהרן הכהן.\u0006","\u0003ו\u0004שואלים: \u0003ור' שמעון\u0004 הלמד מן הכתוב \"כליל תקטר\", שהריהי קרבה כולה ולא חציה. \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"אתה\"\u0004 ממנו למד ר' יהודה דבר זה, \u0003מאי עביד ליה\u0004 \u0005[מה עושה בו,\u0006 למד ממנו\u0005]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה \u0003ל\u0004עניינו של \u0003כהן גדול שמת\u0004 לאחר שהביא את מחצית המנחה של הבוקר \u0003ומינו אחר תחתיו\u0004 באותו יום, ולהשמיענו \u0003שלא יביא\u0004 הכהן הגדול החדש רק \u0003חצי עשרון מביתו, ו\u0004כן ש\u0003לא\u0004 יביא לצורכה את \u0003חצי\u0004 ה\u0003עשרון של\u0004 ה\u0003ראשון\u0004 שהובא מתחילתו לשם כך. אלא יביא עשרון שלם, ויחצהו, וחצי אחד יוקרב למנחת החביתים, וחציו האחר יאבד.","ומקשים על הסבר זה: \u0003ו\u0004מדוע נזקק ר' שמעון ללימודה של הלכה זו מהכתוב \"אותה\", \u0003תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד, \u0005לו\u0006 הלכה זו\u0005]\u0006 \u0003מן\u0004 הכתוב בפרשיה זו \u0003\"ומחציתה\"\u0004 (וכדרך שנלמדה הלכה זו בדף הקודם)! ומשיבים: לא למד ר' שמעון הלכה זו מן הכתוב \"ומחציתה\", שכן את ה\u0003וי\"ו\u0004 היתירה שבמלה \"ומחציתה\" הוא \u0003לא דריש\u0004 \u0005[אינו דורש]\u0006.","שואלים עוד: \u0003ור' יהודה\u0004 אשר למד את דינו מן הכתוב \"והכהן המשיח \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"חק עולם\"\u0004 ממנו למד ר' שמעון דין זה \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 ר' יהודה \u0005עושה לו,\u0006 למד ממנו\u0005]?\u0006 ומשיבים: הרי זה מלמדנו שמצות הבאת מנחת חביתים בידי כהן גדול \u0003חוקה לעולם תהא.\u0004","ועוד שואלים: לשיטת ר' יהודה הכתוב \u0003\"כליל תקטר\" למה לי\u0004 (מה מלמדנו)? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה ללמדנו, \u0003לכדתניא\u0004 \u0005[לכמו ששנינו\u0006 בברייתא\u0003]:\u0004 מהכתוב שלפנינו \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 בדינה של המנחה הנזכרת \u0003עליונה\u0004 (למעלה, מקודם), היא \u0003מנחת\u0004 חביתי \u0003כהן גדול\u0004 שהיא \u0003ב\u0004מצוות \u0003\"כליל תקטר\". ו\u0004בדינה של המנחה הנזכרת \u0003תחתונה\u0004 (למטה, אחר כך), שהיא \u0003מנחת\u0004 נדבתו של \u0003כהן הדיוט\u0004 שהיא \u0003ב\u0004איסור \u0003\"לא תאכל\".\u0004","ואולם \u0003מנין\u0004 לי \u0003ליתן את האמור של זה בזה ואת האמור של זה בזה,\u0004 שנוהגת מצות \"כליל תקטר\" אף במנחת נדבתו של כהן הדיוט, ונוהג איסור \"לא תאכל\" אף במנחת חביתים של כהן גדול? \u0003לכך\u0004 \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפרשיה זו \u0003\"כליל\"\u0004 ו\u0003\"כליל\"\u0004 (\"כליל תקטר\" \"כליל תהיה\"), \u0003לגזירה שוה, נאמר כאן\u0004 (במנחת חביתי כהן גדול) \u0003\"כליל\" ונאמר להלן\u0004 (שם, במנחת נדבתו של כהן הדיוט) \u0003\"כליל\",\u0004","\u0003מה כאן,\u0004 במנחת חביתים — הריהי \u0003ב\"כליל תקטר\", אף להלן,\u0004 במנחת הדיוט — הריהי \u0003ב\"כליל תקטר\". ו\u0004מצד אחר, \u0003מה להלן,\u0004 במנחת נדבתו של כהן הדיוט — בא הכתוב \u0003ליתן\u0004 איסור \u0003לא תעשה על אכילתו, אף כאן,\u0004 במנחת חביתים — יש \u0003ליתן לא תעשה על אכילתה.\u0004 ושואלים על דבריהם: ר' שמעון הביא ראיה לשיטתו מן הכתוב \"חק עולם\".","\u0003ו\u0004אולם האם אכן \u0003סבר ר' שמעון\u0004 כי דין זה שמביאים \u0003מ\u0004נכסיו \u0003של ציבור\u0004 הריהו \u0003דאורייתא\u0004 \u0005[מן התורה]?\u0006","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת שקלים\u0005]\u0006 כי \u0003אמר ר' שמעון: שבעה דברים\u0004 בעניינים שונים \u0003התקינו בית דין, וזה\u0004 (התקנה שהוזכרה קודם, בענין המוצא בהמה בירושלים או בסמוך לה) הריהי \u0003אחד מהן.\u0004 והתקנה השניה הריהי בדינו של \u0003גוי ששלח\u0004 את קרבן \u0003עולתו ממדינת הים,\u0004 שאם \u0003שלח עמה\u0004 את דמי ה\u0003נסכים\u0004 שהרי טמאים הם — נסכי קרבן זה \u0003קריבה משלו,\u0004 מדמי הנסכים ששלח עם הקרבן. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שלח הגוי דמי נסכים עם הקרבן — הרי הנסכים \u0003קריבין משל ציבור\u0004","\u0003וכן\u0004 תקנה שלישית, בעניינו של \u0003גר שמת\u0004 ואין לו יורשים, \u0003והניח\u0004 אחריו בהמות שהוקדשו ל\u0003זבחים\u0004 (קרבנות), אם \u0003יש לו\u0004 לקרבנותיו \u0003נסכים\u0004 הבאים עימם, שהפריש הגר נסכים לצורכם — הנסכים \u0003קריבין משלו, ואם לאו\u0004 \u0005[לא]\u0006 הפריש נסכים בחייו — נסכיו \u0003קריבין משל ציבור. ו\u0004תקנה רביעית, ש","\u0003תנאי בית דין הוא\u0004 זה, בדינו של \u0003כהן גדול שמת ו\u0004עדיין \u0003לא מינו כהן\u0004 גדול \u0003אחר תחתיו, שתהא מנחתו\u0004 (מנחת חביתיו) \u0003קריבה משל ציבור.\u0004 וכך מפרט ר' שמעון עוד שלש תקנות נוספות. ובכל אופן דעתו המפורשת של ר' שמעון כי הלכה זו שמנחת חביתים של כהן גדול שמת מובאת משל ציבור הריהי מתקנת חכמים, ולא מדין תורה!","\u0003אמר ר' אבהו\u0004 בתשובה: אכן סבור ר' שמעון כי הלכה זו היא מדין תורה, ואולם בענין זה \u0003שני תקנות הוו\u0004 \u0005[היו],\u0006 שכן בתחילה נהג דין זה שמ","\u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 והביאו את מנחת החביתים במקרה זה \u0003מ\u0004של \u0003ציבור,\u0004 מתרומת הלשכה, ואולם \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 חכמים \u0003דקא מידחקא\u0004 \u0005[ש\u0006על ידי כך \u0005היא נדחקת\u0006 מתדלדלת מנכסיה\u0005]\u0006 ה\u0003לישכה\u0004 שבבית המקדש — עמדו ו\u0003תקינו דלגבי\u0004 \u0005[תיקנו שיגבו]\u0006 את מנחת החביתים \u0003מ\u0004ה\u0003יורשים\u0004 של הכהן הגדול שמת. ואולם \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 חכמים \u0003דקא פשעי\u0004 \u0005[שהם,\u0006 היורשים, \u0005פושעים,\u0006 מתרשלים\u0005]\u0006 \u0003בה\u0004 בהבאתה של מנחת החביתים \u0003—\u0004 חזרו ו\u0003אוקמוה אדאורייתא\u0004 \u0005[העמידו אותה\u0006 שוב \u0005על דין תורה]\u0006 שצריך להביאה משל \u0003ציבור.\u0004","כיון שהובאה הברייתא, דנים בנושא אחר נזכר בה. ששנינו בה: \u0003ו\u0004עוד תקנה שהתקינו בית דין \u0003על פרה\u0004 אדומה \u0003שלא יהא מועלין באפרה\u0004 (שאין הנהנה ממנו חייב בקרבן מעילה). ושואלים: וכי תקנת חכמים היא זו, והרי \u0003דאורייתא\u0004 \u0005[מדין תורה]\u0006 \u0003היא! דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 לשון הכתוב \"חטאת\" שנאמר בפרה אדומה \u0003\"חטאת היא\"\u0004 (במדבר יט, ט), \u0003מלמד\u0004 שדין הפרה האדומה כדין החטאת, ומכאן \u0003שמועלין בה,\u0004 בפרה אדומה עצמה. ואילו הכתוב \u0003\"היא\"\u0004 שהריהו לשון מיעוט — מלמד שדווקא \u0003בה מועלין,\u0004"],["אבל \u0003באפרה אין מועלין.\u0004 הרי שדין זה הוא מן התורה, ולא מתקנת חכמים!","\u0003אמר רב אשי\u0004 בהסבר הדבר: אכן מדין תורה אין מועלים באפר פרה אדומה, ואולם \u0003שתי תקנות\u0004 חכמים היו בענין זה. שכן בתחילה \u0003הואי\u0004 \u0005[היה]\u0006 נהוג דין \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 האומר כי דווקא \u0003בה\u0004 עצמה \u0003מועלין,\u0004 ואילו \u0003באפרה אין מועלין.\u0004 ברם \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 חכמים \u0003דקא מזלזלי\u0004 \u0005[שהם,\u0006 העוסקים באפר פרה, \u0005מזלזלים]\u0006 \u0003בה, וקא עבדי מיניה\u0004 \u0005[והם עושים ממנו,\u0006 מן האפר\u0005]\u0006 תרופה \u0003למכתן\u0004 (לפצע) — \u0003גזרו ביה\u0004 \u0005[בו,\u0006 באפר\u0005]\u0006 שיהיה בו דין \u0003מעילה,\u0004 שאין ליהנות ממנו.","ואולם \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 חכמים כי על ידי כך \u0003דקא פרשי\u0004 \u0005[שהם פ\u0006 \u0003ורשים,\u0004 נמנעים\u0003]\u0004 \u0003מ\u0004להזות מאפר הפרה במקרים של \u0003ספק הזאות\u0004 (על אדם שהוא ספק טמא מת), מפני החשש שמא מועלים הם האנשים שהיזו עליהם, לכך עמדו חכמים וחזרו ו\u0003אוקמוה\u0004 \u0005[העמידו]\u0006 הלכה זו \u0003אדאורייתא\u0004 \u0005[על דין תורה],\u0006 שאין מועלים באפר פרה.","ומתוך שהובאה מחלוקת ר' שמעון ור' יהודה במקרה שמת הכהן הגדול, מנכסי מי מובאת מנחת החביתים, מביאים עוד מחלוקת שחלקו ביניהם בענין דומה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003פר העלם דבר של ציבור\u0004 (ששגגו בית דין בהוראה והתירו אחת מהעבירות שזדונן כרת ושגגתן חטאת, וטעו רוב העם ועשו על סמך הוראה זו, ולאחר מכן נודעה להם טעותם), \u0003ושעירי עבודה זרה\u0004 (שהורו בית דין בשגגה כי הותר איסור עבודה זרה, ועשו הציבור על פיהם, ואחר כך נודעה טעותם) — \u0003בתחילה\u0004 (מראש), עוד לפני שנוצר צורך זה להקריב את הקרבנות הללו, היו גבאי המקדש \u0003מגבין להן,\u0004 שמבעוד מועד היו שמורים במקדש כספים מיוחדים לצורך רכישת קרבנות אלה, אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 דין קרבנות אלה כדין שאר קרבנות הציבור, ש\u0003מתרומת הלשכה הן באין.\u0004","ותוהים על ייחוס הדעות הללו לחכמים אלה: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שלשונה היא \u0003איפכא\u0004 \u0005[הפוכה],\u0006 שבה נמסר כי \u0005ר' יהודה הוא האומר שמתרומת הלשכה הם באים, ואילו ר' שמעון\u0006 סובר שמראש היו נגבים לצורך קרבנות אלה, ומעתה יש לברר \u0003הי מינייהו אחריתא\u0004 \u0005[איזו מהן\u0006 משתי הברייתות הללו היא \u0005המאוחרת\u0006 יותר בזמן אמירתה\u0005],\u0006 ובה נאמרות דעותיהם היותר מדוייקות של ר' יהודה ור' שמעון?","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים\u0006 להצעה הבאה \u0005לפני]\u0006 \u0003רב אשי: לימא קמייתא\u0004 \u0005[האם נאמר\u0006 שהברייתא \u0005הראשונה\u0006 שהוזכרה בסוגייתנו\u0005],\u0006 שבה שנינו כי ר' שמעון סובר שמתרומת הלשכה הם באים, היא זו \u0003אחריתא\u0004 \u0005[המאוחרת\u0006 יותר\u0005],\u0006 וראיה לדבר, \u0003דשמעינן ליה\u0004 \u0005[ש\u0006כן \u0005שמענו אותו]\u0006 את שיטתו של \u0003ר' שמעון דחייש\u0004 \u0005[שחושש]\u0006 הוא \u0003לפשיעה\u0004 ולרשלנותם של אנשים.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אשי\u0004 לחכמים בדחיית הצעתם: מכאן אין להביא ראיה, שכן \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 כי \u0003בתרייתא\u0004 \u0005[\u0006הברייתא \u0005האחרונה\u0006 שהוזכרה בסוגייתנו\u0005]\u0006 היא זו ה\u0003אחריתא\u0004 \u0005[המאוחרת\u0006 יותר\u0003]\u0004 שבה נאמר כי ר' שמעון סבור שגובים מראש מן הציבור לצורכם של קרבנות אלה — אין קושי בדבר. שכן \u0003כי קא חייש\u0004 \u0005[כאשר הוא חושש]\u0006 \u0003ר' שמעון לפשיעה\u0004 — הרי זה דווקא \u0003במילתא דלית בהו\u0004 \u0005[בדבר שאין להם,\u0006 לאנשים המביאים\u0005]\u0006 \u0003כפרה בגווה\u0004 \u0005[בו],\u0006 וכגון במנחת חביתים. ואולם \u0003במילתא דאית להו\u0004 \u0005[בדבר שיש להם\u0006 לאנשים המביאים את הקרבן\u0005]\u0006 \u0003כפרה בגווה\u0004 \u0005[בו],\u0006 וכגון בקרבנות אלה הבאים בעקבות חטא שחטא הציבור — \u0003לא חייש\u0004 \u0005[לא חושש]\u0006 \u0003ר' שמעון לפשיעה.\u0004","ומעתה שלא נפתרה השאלה, שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 איזו מן הברייתות הללו מאוחרת ומדוייקת יותר\u0005?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה זוטי לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו \u0005ממה\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר בקרבן התמיד \"צו את בני ישראל ואמרת אליהם \u0003את קרבני לחמי לאשי ריח ניחחי תשמרו להקריב לי במועדו\"\u0004 (במדבר כח, ב), בא \u0003לרבות\u0004 אף \u0003פר העלם דבר של ציבור ושעירי עבודה זרה שבאין\u0004 גם הם \u0003מתרומת הלשכה,\u0004 אלו \u0003דברי ר' שמעון.\u0004 הרי איפוא כי ר' שמעון הוא זה שאומר שקרבנות אלה באים מתרומת הלשכה.","\u0003ו\u0004עוד שנינו במשנתנו כי מנחת החביתים (כאשר מת הכהן הגדול, ועדיין לא מינו כהן גדול אחר במקומו) — לא היתה באה במחצית \u0003עשירית האיפה, אלא עשירית האיפה\u0004 \u0003שלימה היתה קריבה.\u0004 ובפירושם של דברים אלה \u0003אמר ר' חייא בר אבא\u0004 כי \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן:\u0004 האם הכוונה היא שמביא עשירית האיפה \u0003שלימה\u0004 למנחת החביתים של \u0003שחרית ו\u0004עשירית האיפה \u0003שלימה\u0004 לזו של \u0003בין הערבים,\u0004 שאין דין מחצית במנחת חביתים אלא בכהן גדול בלבד. וכשאין עדיין כהן גדול הריהי באה בשני עשרונים בכל יום. \u0003או דילמא\u0004 \u0005[שמא]\u0006 בכגון זה היו מביאים עשירית האיפה \u0003שלימה\u0004 ב\u0003שחרית, ובטילה\u0004 זו של \u0003בין הערבים?\u0004","\u0003אמר רבא\u0004 בפתרון הבעיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו \u0005בסדר העבודות של תשעת הכהנים שזכו בהעלאת האיברים של קרבן התמיד לכבש, בין של שחר ובין של בין הערבים שהיו אלה עומדים בשורה, כל אחד ואחד מיועד לתפקידו, והכהן ה\u0006\u0003שמיני\u0004 שבשורה היה מחזיק \u0003ב\u0004מנחת \u0003ה\u0004\u0003חביתים.\u0004 והרי זה סדר קבוע, שהתקיים תמיד במקדש. \u0003ו\u0004יש לשאול: \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר שכאשר מת הכהן הגדול ועדיין לא מינו אחר תחתיו, היתה הבאת מנחת החביתים \u0003בטילה בין הערבים\u0004 — \u0003הא זמנין\u0004 \u0005[הרי פעמים]\u0006 ש\u0003לא משכח ליה\u0004 \u0005[לא נמצא\u0006 \u0003לו]\u0004 שימוש לכהן \u0003שמיני\u0004 זה שיביא \u0003חביתים,\u0004 \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר]?\u0006 במקרה ש\u0003מת\u0004 ה\u0003כהן\u0004 ה\u0003גדול\u0004 לאחר שהביא את מנחתו בבוקר \u0003ולא מינו אחר תחתיו,\u0004 ומכיון שאין מביאים כלל בכגון זה את מנחת בין הערבים, מכאן אם כן ראיה כפתרון בעייתו של ר' יוחנן, אלא ודאי הכוונה שבאה מנחת החביתים בעשירית האיפה שלימה הן בבוקר והן בין הערביים.","ונמסר כי \u0003אמרוה\u0004 את ההוכחה \u0003רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003ר' ירמיה, אמר\u0004 ר' ירמיה בדחיית הדברים: \u0003בבלאי טפשאי\u0004 \u0005[בבליים טפשים],\u0006 \u0003משום דיתבו באתרא דחשוכא אמרי שמעתתא דמחשכן\u0004 \u0005[משום ש\u0006הם \u0005יושבים במקום חשוך,\u0006 בארץ נמוכה, הם \u0005אומרים\u0006 דברים \u0005של חשיכה,\u0006 מוטעים\u0005],\u0006 שאין זו ראיה, שאם תאמר כדבריך,","\u0003אלא\u0004 מעתה אפשר להוסיף ולשאול בדומה, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בה כי הכהן ה\u0003שביעי\u0004 שבשורת הכהנים הריהו אוחז \u0003בסלת\u0004 למנחת התמיד, ואילו הכהן ה\u0003תשיעי\u0004 אוחז \u0003ביין\u0004 לנסך התמיד. ומעתה האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר בהם שהם \u0003לא בטלי\u0004 \u0005[לא בטלים]\u0006 לעולם?","והלא שנינו על הכתוב \u0003בפרשת קרבנות המועדים\u0004 \u0003\"מנחתם ונסכיהם\"\u0004 (במדבר כט, כד) כי הרי זה בא לרבות את הבאתם של הנסכים אף \u0003בלילה,\u0004 וכן שנינו על האמור עוד שם (פסוק לז) \u0003\"מנחתם ונסכיהם\"\u0004 כי הריהו בא לרבות שקרבים הנסכים \u0003אפילו למחר.\u0004 ואם כן, לדבריך כיון שאפשר למנחות והנסכים שייעשו למחר, ובאותו יום לא ייעשו, יש אם כן מקרה שאין נזקקים לכהן השביעי ולכהן התשיעי.","\u0003אלא\u0004 נלמד מכאן שאין כוונת המשנה לומר שתמיד היו שם תשעה כהנים, ומה ששנינו הריהו הסדר הרגיל והמצוי, ואילו מקרים המבוססים על \u0003\"דאי\"\u0004 \u0005[שאם]\u0006, וכגון שלא הביאו את הנסכים ביום זה אלא למחרתו — \u0003לא קתני\u0004 \u0005[לא שונה]\u0006 המשנה. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש לומר בענין ראייתו של רבא, מקרה זה \u0003דאי\u0004 \u0005[שאם]\u0006 \u0005מת הכהן הגדול ולא מינו אחר תחתיו\u0006 — \u0003לא קתני\u0004 \u0005[לא שונה]\u0006 המשנה. ואין איפוא להביא מכאן כל ראיה.","ומסופר כי \u0003אהדרוה\u0004 \u0005[החזירוה],\u0006 השיבו את דבריו אלה של ר' ירמיה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא, אמר\u0004 בתחילה רבא על כך: \u0003מבישותין\u0004 \u0005[מ\u0006הדברים \u0005הרעים שלנו,\u0006 הניתנים לדחייה\u0005]\u0006 — \u0003אמרי קמייהו\u0004 \u0005[\u0006\u0005אומרים לפניהם,\u0006 לפני חכמי ארץ ישראל\u0005],\u0006 ואילו \u0003מטיבותין\u0004 \u0005[מ\u0006הדברים \u0005הטובים שלנו,\u0006 שאינם ניתנים לדחייה\u0005]\u0006 — \u0003לא אמרי קמייהו\u0004 \u0005[אין אומרים לפניהם].\u0006","\u0003ו\u0004אולם לאחר מכן \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: הני\u0004 \u0005[אלה]\u0006 הדברים שאמרתי, \u0003נמי טיבותין\u0004 \u0005[גם כן מ\u0006הדברים \u0005הטובים שלנו]\u0006 \u0003היא,\u0004 שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בדינה של מנחת החביתים של כהן גדול \u0003\"סלת מנחה תמיד\u0004 מחציתה בבוקר ומחציתה בערב\" (ויקרא ו, יג) — הושוותה מנחת החביתים לקרבן התמיד, לומר: \u0003הרי היא לך כמנחת תמידין,\u0004 וכשם שהתמיד בא בבוקר ובערב, כן גם מנחת החביתים, ואף כשמת הכהן הגדול וטרם מינו כהן אחר תחתיו.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו של ר' יוחנן, האם מקבלים את פתרונו זה של רבא? \u0003אמר רב נחמן בר יצחק: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 מפורשת, שכאשר מת הכהן הגדול ועדיין לא מינו כהן גדול אחר תחתיו, מנחת החביתים באה בעשירית האיפה \u0003שלימה\u0004 ב\u0003שחרית ו\u0004בעשירית האיפה \u0003שלימה בין הערבים.\u0004","\u0003אמר ר' יוחנן:\u0004 בשיעורה של הלבונה הבאה כרגיל, במנחת חביתים של הכהן הגדול, \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בהלכה זו \u0003אבא יוסי בן דוסתאי ורבנן\u0004 \u0005[וחכמים],\u0006 ש","\u0003אבא יוסי בן דוסתאי אומר\u0004 שהיה הכהן הגדול \u0003מפריש לה\u0004 ומביא מביתו בכל יום יחד עם עשרון הסולת \u0003שני קמצים של לבונה,\u0004 \u0003קומץ\u0004 אחד קרב עם מחצית העשרון שבמנחת החביתים \u0003של\u0004 \u0003שחרית, ו\u0004ה\u0003קומץ\u0004 השני קרב עם זה של \u0003בין הערבים. ורבנן אמרי\u0004 \u0005[וחכמים אומרים]\u0006 כי הכהן הגדול היה \u0003מפריש לה קומץ אחד\u0004 בלבד של לבונה, וחוצהו לשנים, \u0003חצי\u0004 ה\u0003קומץ\u0004 האחד הריהו מביא ב\u0003שחרית, ו\u0004את \u0003חצי\u0004 ה\u0003קומץ\u0004 השני הריהו מביא \u0003בין הערבים.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם חלוקים]?\u0006 \u0003אבא יוסי בן דוסתאי סבר\u0004 כי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 בכתוב שיאמר ש\u0003חצי קומץ\u0004 הוא זה \u0003דקריב\u0004 \u0005[שקרב],\u0006 ולכך יש להביא בכל יום שני קמצים של לבונה, קומץ עבור אחת ממנחות החביתים. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 \u0003עשרון\u0004 אחד של סולת \u0003דבעי\u0004 \u0005[ש\u0006הריהו \u0005צריך]\u0006 \u0003שני קמצים\u0004 של לבונה. לכך יש להביא בכל יום עשרון אחד של סולת, וקומץ אחד של לבונה. עד כאן שיטות החכמים בדרך הרגילה של הבאת הלבונה.","ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן:\u0004 במקרה של \u0003כהן גדול שמת ולא מינו אחר תחתיו,\u0004"],["האם \u0003ל\u0004שיטתם של \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שבכל יום מביאים למנחת החביתים שני עשרונים אחד לבוקר ואחד לבין הערביים, האם גם \u0003הוכפלה לבונתו\u0004 ומביא שני קמצים של לבונה, אחד לבוקר ואחד לבין הערביים. \u0003או\u0004 \u0003לא\u0004 ומביאים קומץ אחד של לבונה בלבד, וכדרך שמביא הכהן הגדול עצמו. וצדדי הספק: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו],\u0006 שבמקרה זה \u0003מתוך\u0004 \u0003שהוכפלה סלתו\u0004 (שמביאים שני עשרונים במקום עשרון אחד של סולת במנחת כהן הגדול עצמו) — \u0003הוכפלה\u0004 גם \u0003לבונתו,\u0004 ומביאים שני קמצים של לבונה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לומר: \u0003מאי דגלי\u0004 \u0005[מה שגילה]\u0006 לנו הכתוב — \u0003גלי\u0004 \u0005[גילה],\u0006 ואילו \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דלא גלי\u0004 \u0005[שלא גילה]\u0006 לנו הכתוב — \u0003לא גלי\u0004 \u0005[לא גילה],\u0006 ואין לנו בו אלא קומץ אחד בלבד, חצי עשרון לבוקר וחצי עשרון לערב. ואין ספק זה אלא לחכמים הסבורים שכרגיל באה שיעור הלבונה בקומץ אחד, שהרי לדעת אבא יוסי, אף בכל יום שיעור הלבונה המובא הריהו שני קמצים. \u0003ו\u0004ספק נוסף הוא: שיעור ה\u0003שמן\u0004 המובא במנחת החביתים כשמת הכהן הגדול ועדיין לא מינו כהן גדול אחר, \u0003בין ל\u0004דעת \u0003אבא יוסי בן דוסתאי ובין ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003מהו?\u0004 האם כמנחת חביתים הבאה על ידי הכהן הגדול עצמו, שלשה לוגים בכל יום. או שמא עתה, שמביאים עשרון סולת שלם בבוקר, ועשרון סולת שלם בערב, אף כמות השמן תוכפל ויביאו ששה לוגים שמן, שלושה לבוקר ושלושה לערב.","","ובפתרונה של בעיה זו \u0003אמר רבא:\u0004 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה באשר לשאלה מהו שיעור הלבונה במקרה זה לשיטתם של חכמים, ממה ששנינו במשנה (להלן מנחות קו, ב) כי \u0003חמשה\u0004 \u0003קמצין\u0004 (דברים ששיעורם בקומץ) \u0003הן,\u0004 ונמנו באותה משנה חמשה דברים, ואין קומץ לבונה של חביתים נמנה איתם (שהרי הוא קרב מחצית הקומץ בבוקר ומחצית הקומץ בערב). \u0003ו\u0004מעתה נאמר: \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר ששיעור הלבונה הבאה במקרה שהכהן הגדול מת, הריהו שני קמצים, אחד לשחר ואחד לבין הערביים, \u0003זימנין דמשכחת לה\u0004 \u0005[פעמים שאתה מוצא אותה,\u0006 שיעור קומץ\u0003]\u0004 ב\u0003שבעה\u0004 אופנים, החמישה הנזכרים במשנה, וקומץ לבונה של בוקר, וקומץ לבונה של בין הערביים! ודוחים: אין זו ראיה, שכן אין דרכה של המשנה למנות אלא את הדברים שב\u0003סדר הרגיל, ואילו מקרים המבוססים על\u0004 \u0003\"דאי\"\u0004 \u0005[שאם]\u0006, וכגון במקרה זה שמת הכהן הגדול ולא מינו עדיין כהן גדול אחר תחתיו — \u0003לא קתני\u0004 \u0005[לא שונה]\u0006 המשנה. ונמסר כי \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב פפא וקאמר לה להא שמעתא\u0004 \u0005[והיה אומר אותה את השמועה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בר שמעיה לרב פפא\u0004 בקושיה על דחיית ההצעה: \u0003והא\u0004 \u0005[והרי]\u0006 בין חמשת הקמצים הנזכרים באותה משנה, נזכר אף המקרה של מי שהוא \u0003מעלה\u0004 (מקטיר) \u0003את ה\u0004\u0003קומץ בחוץ\u0004 לעזרה, שהריהו חייב כרת (אם עשה כן במזיד), אף שאין זה מקרה רגיל, אלא \u0003\"דאי הוה\"\u0004 \u0005[שאם היה]\u0006 הוא זה, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[הוא שונה]\u0006 אותו. ומאחר שכן, אף ראייתו של רבא יכולה להיות ראיה.","","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיייתו של ר' יוחנן? \u0003אמר רב נחמן בר יצחק: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כהן גדול שמת ולא מינו אחר תחתיו\u0004 — מביאים עשירית האיפה סולת \u0003שלימה\u0004 במנחת חביתים של \u0003שחרית, ו\u0004עשירית האיפה סולת \u0003שלימה\u0004 במנחת חביתים של \u0003בין הערבים. ומפריש לה שני קמצין\u0004 של לבונה, וחוצה אותם, ומביא \u0003קומץ\u0004 אחד למנחת חביתים של \u0003שחרית ו\u0004ה\u0003קומץ\u0004 השני של הלבונה בא במנחת חביתים של \u0003בין הערבים. ומפריש לה שלשת לוגין\u0004 של שמן. וחוצה אותם, כאשר \u0003לוג ומחצה\u0004 ניתן בעשרון של סולת הבא ב\u0003שחרית,\u0004 וה\u0003לוג ומחצה\u0004 השני ניתן בעשרון של סולת הבא \u0003בין הערבים.\u0004","ונברר: כדעת \u0003מני\u0004 \u0005[מי היא]\u0006 הברייתא הזו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 דין \u0003לבונתה\u0004 ש\u0003הוכפלה\u0004 שיעורה מהשיעור המובא על ידי הכהן הגדול עצמו, והריהי באה בשני קמצים, \u0003ומאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 הוא דין \u0003שמנה\u0004 ש\u0003לא הוכפלה\u0004 מהשיעור המובא על ידי הכהן הגדול עצמו, אלא היא באה בשלושה לוגים שמן בלבד?","\u0003אלא\u0004 צריך לומר שכשיטת \u0003אבא יוסי בן דוסתאי היא\u0004 ברייתא זו, ש\u0003אמר\u0004 כי מנחת \u0003חביתי כהן גדול בעלמא\u0004 \u0005[בכלל,\u0006 כרגיל\u0005]\u0006 הריהי \u0003שני קמצין בעיא\u0004 \u0005[צריכה],\u0006 \u0003ו\u0004מה ששנינו בברייתא כי במקרה זה של כהן גדול שמת באה מנחת החביתים בשני קמצים של לבונה — \u0003ה\u0004\u0003לבונה לא הוכפלה\u0004 משיעורה הרגיל. \u0003ו\u0004כמו כן גם שיעור ה\u0003שמן לא הוכפל\u0004 במנחת זו, והריהו בא בשיעור שלשה לוגים כשאר מנחת חביתים. \u0003ומ\u0004תוך שלמדנו כי שיעור ה\u0003שמן ל\u0004שיטת \u0003אבא יוסי בן דוסתאי לא הוכפלה,\u0004 מכאן נלמד ש\u0003לבונתה ושמנה ל\u0004שיטת \u0003רבנן נמי\u0004 \u0005[חכמים גם כן]\u0006 \u0003לא הוכפלו.\u0004 הסוגיה נפתחה בהבאת דברי ר' יוחנן את מחלוקתם של אבא יוסי וחכמים בשיעור הלבונה המובאת עם מנחת החביתים על ידי הכהן הגדול, ועתה מביאים את ההכרעה בענין זה. ש\u0003אמר ר' יוחנן: הלכה\u0004 במחלוקת זו \u0003כאבא יוסי בן דוסתאי.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: הלכה כסתם משנה\u0004 (משנה ששנויים דברים בלא יחוסם לתנא מסויים), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה להלן\u0005]\u0006 כי \u0003חמשה קמצין הן\u0004 ולא יותר, ואין מונים בתוכם את שני קומץ לבונה של שחר וקומץ לבונה של בין הערביים (לשיטת אבא יוסי), והרי זו משנה סתם!","","","ומסבירים: שתי מסורות הלכה אלה, של \u0003אמוראי נינהו\u0004 \u0005[אמוראים\u0006 שונים \u0005הן],\u0006 \u0003ו\u0004שני האמוראים הללו אמרו את דבריהם \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוחנן,\u0004 שזה אמר כך בדבריו וזה אמר אחרת.","","\u0003כל המנחות באות\u0004 במקדש לקרבן כשהן \u0003מצה,\u0004 שמקפידים שלא יחמיץ הבצק, \u0003חוץ מ\u0004עשר חלות \u0003חמץ ש\u0004מתוך ארבעים הלחמים הבאים כמנחה \u0003ב\u0004קרבן ה\u0003תודה\u0004 (\"לחמי תודה\") \u0003ו\u0004כן \u0003שתי הלחם\u0004 הבאות בחג השבועות \u0003ש\u0004אף \u0003הן באות חמץ.\u0004 ונחלקו חכמים בשאלה כיצד היו מחמיצים את המנחות הבאות חמץ. ש\u0003ר' מאיר אומר:\u0004 את \u0003השאור\u0004 (בצק חמוץ, הניתן לעיסה ומחמץ אותה) היה עושה המנחה \u0003בודה\u0004 (מפריש) \u0003להן\u0004 למנחות הללו \u0003מתוכן\u0004 עצמן, שהיה נוטל מתוכן חלק, שאותו היה מחמיץ, ולאחר מכן היה חוזר ומניחו בתוך בצקן של המנחות הללו \u0003ומחמצן\u0004 בכך \u0003.\u0004 \u0003ר' יהודה אומר: אף\u0004 זו \u0003היא אינה\u0004 מצוה \u0003מן המובחר\u0004 (טובה וראויה), שכן בדרך זו משתמשים להחמצת המנחה בשאור חדש, ואין בצק בא בדרך זו לכלל החמצה נאותה, \u0003אלא\u0004 כך יש לעשות: \u0003מביא את השאור\u0004 מעיסה אחרת, ישנה, והרי זה שאור ישן המחמץ יפה, \u0003ונותנו לתוך המדה,\u0004 כלי מידת העשרון בה מודדים את הסולת למנחה, \u0003ו\u0004לאחר מכן הריהו מוסיף סולת על שאור זה עד שהוא \u0003ממלא את המדה.\u0004 הקשו חכמים על שיטתו זו של ר' יהודה ו\u0003אמרו לו: אף היא,\u0004 דרך זו, אינה ראויה, שכן באופן זה \u0003היתה\u0004 המנחה נמצאת או שהיא \u0003חסרה\u0004 משיעור הסולת הראוי למנחה, שאם היה השאור רך, שנבלל קמחו במים מרובים, נמצא איפוא שגדול נפח השאור, ואילו היה עדיין קמח שלא גיבלוהו כלל במים — אין בו שיעור הראוי למלא את המידה הראויה לסולת המנחה, \u0003או\u0004 כשהיא \u0003יתרה\u0004 על שיעור הסולת הראוי למנחה, שאם נבלל קמח השאור במים מועטים, נמצא נפחו קטן, ואילו היה עדיין קמח — היה בו יותר מן השיעור הראוי למלא את מידת המנחה.","","","שנינו במשנתנו כי כל המנחות באות כשהן מצה, ובענין זה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' פרידא מר' אמי: מנין ל\u0004הלכה זו ש\u0003כל המנחות שהן באות\u0004 כשהן \u0003מצה?\u0004 ותהה ר' אמי על השאלה: מה מקום לשאלה זו \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 שהרי המנחה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 בתורה במפורש שהיא באה מצה — הרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה,\u0004 ואף המנחה \u0003דלא כתיב\u0004 \u0005[שלא נאמר]\u0006 \u0003בה\u0004 בתורה במפורש שהיא באה מצה, על כל פנים \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004"],["\u0003\"זאת תורת המנחה הקרב אתה בני אהרן לפני ה' אל פני המזבח... והנותרת ממנה יאכלו אהרן ובניו מצות תאכל\"\u0004 (ויקרא ו, ז— ט). הרי שהיא מצוה כללית הנוהגת בכל המנחות (\"זאת תורת המנחה\") שתהיינה מצה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פרידא לר' אמי: מה הוא המקור שה\u0003מצוה\u0004 לכתחילה היא שתהיינה המנחות באות מצה — \u0003לא קא מיבעיא\u0004 \u0005[לא נשאלה]\u0006 \u0003לי\u0004 שנלמד כן ממקרא זה. ואולם \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלתי הוא מהו המקור שאף \u0003לעכב\u0004 חל דין זה, שאם עברו והביאו מנחה שאינה מצה שהיא פסולה בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: המקור שדין זה הוא אף \u0003לעכב,\u0004 \u0003נמי כתיב\u0004 \u0005[גם כן נאמר],\u0006 שכן יש כתוב נוסף בדין המנחות \u0003\"לא תאפה חמץ\"\u0004 (שם י), הרי שאין המנחה נאפית חמץ, \u0003אלא\u0004 \u0003מצה.\u0004 והשמיע כן הכתוב פעם נוספת, ללמדנו שאף אם עבר והביאה כשאינה מצה, שהיא פסולה בכך אף בדיעבד (\"שנה עליו הכתוב\", חזר וכתב פעם שנית — \"לעכב\").","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על תשובת ר' אמי\u0005]\u0006 \u0003רב חסדא:\u0004 אף מכתוב זה עדיין אין ללמוד שהן פסולות אף בדיעבד. \u0003ו\u0004\u0003שמא\u0004 \u0003אימא\u0004 \u0005[אמור]\u0006 את דרשת הכתוב באופן שונה: \u0003\"לא תאפה חמץ\",\u0004 שלא תיאפה במצב של החמצה מלאה במשמעות \"חמץ\", ורק באופן זה פסולות המנחות הבאות מצה, \u0003אלא\u0004 יכול אתה לומר שתיאפנה אף כשעברו \u0003שיאור\u0004 (החמצה מעטה), אף שאינן בכלל מצה (שהרי הוחמצו מעט) אין בכך פסול?! ודנים בשאלתו זו של רב חסדא: והרי נחלקו חכמים בהגדרת \"שאור\", שלשיטת ר' מאיר הריהו הבצק בתחילת חימוצו, משהכסיפו פניו, ולשיטת ר' יהודה אין זה חמץ כלל, אלא שאור הריהו רק מזמן שנראו בבצק סדקים כקרני חגבים.","ומעתה יש לברר: \u0003שיאור\u0004 זה שהציע רב חסדא בדרשת הכתוב, \u0003דמאן\u0004 \u0005[של מי]\u0006 לפי הגדרתו של איזה תנא הוא? \u0003אי\u0004 \u0005[אם]\u0006 המדובר כהגדרת שאור בשיטת \u0003ר' מאיר,\u0004 ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004 הסבור שאין זה חמץ כלל — אין מקום לקושיית רב חסדא, שהרי לדעת ר' יהודה \u0003מצה מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003היא\u0004 זו! ו\u0003אי\u0004 \u0005[אם]\u0006 כהגדרת שאור בשיטת \u0003ר' יהודה\u0004 (\"נראו בו סדקים\") ו\u0003ל\u0004שיטת \u0003ר' מאיר\u0004 הסבור שהוא חמץ גמור — גם כן אין מקום לקושיית רב חסדא, שהרי \u0003חמץ מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא!\u0004","ו\u0003אי\u0004 \u0005[אם]\u0006 כהגדרת שאור לשיטת \u0003ר' מאיר,\u0004 ו\u0003ל\u0004דעת \u0003ר' מאיר\u0004 — גם כן אין מקום לשאלת רב חסדא. שהרי \u0003מ\u0004כיון שדינו של האוכל שאור שכזה בפסח \u0003דלקי עליה\u0004 \u0005[שלוקה עליו],\u0006 לדעת ר' מאיר, הרי ש\u0003חמץ\u0004 גמור \u0003הוא! אלא\u0004 צריך לומר שקושיית רב חסדא מדברת בהגדרת שאור של \u0003ר' יהודה\u0004 ו\u0003ל\u0004דעת \u0003ר' יהודה\u0004 שמצב זה אינו מוגדר כחמץ גמור.","ובדומה לקושיית רב חסדא על תשובת ר' אמי \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 גם \u0003רב נחמן בר יצחק: ואימא\u0004 \u0005[ואמור]\u0006 כך את דרשת הכתוב: \u0003\"לא תאפה חמץ\"\u0004 — \u0003אלא\u0004 הבא את המנחה כשהיא במצב של \u0003חלוט\u0004 (שניתנה העיסה במים רותחים), שאף שאין זה חמץ, גם איננו בכלל מצה! ותוהים: \u0003חלוט מאי ניהו\u0004 \u0005[מה הוא],\u0006 מהו עניינה של חליטה זו? — הרי זו ה\u0003רביכה\u0004 האמורה בתורה במנחות הבאות רבוכות (שנאמר בהן \"מורבכת תביאנה\", ויקרא ו, יד). ומעתה, אין צורך לענין החליטה לדרשה מיוחדת מהכתוב \"לא תאפה חמץ\", שכן \u0003אי\u0004 \u0005[אם]\u0006 היא מנחה \u0003דאיכא\u0004 \u0005[שיש]\u0006 בה דין \u0003רביכה\u0004 — הרי כבר \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בתורה במפורש שהיא באה \u0003רביכה, ו\u0004מנחה שאינה באה ברביכה — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא כתיב\u0004 \u0005[לא\u0006 \u0003נאמר]\u0004 \u0003בה\u0004 שנעשית \u0003רביכה.\u0004","ומשיבים: \u0003ואימא\u0004 \u0005[ו\u0006שמא יכול אתה \u0005לומר]\u0006 כך את דרשת הכתוב \"לא תאפה חמץ\": מנחה זו \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 מפורש שתיעשה \u0003רביכה\u0004 — הרי זו \u0003מצוה ברביכה, ו\u0004אילו זו ש\u0003לא כתיב\u0004 \u0005[לא נאמר]\u0006 \u0003בה רביכה\u0004 — תלוי הדבר ברצונו, ש\u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003רביכה לייתי\u0004 \u0005[יביא],\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003מצה לייתי\u0004 \u0005[יביא],\u0006 ולכך בא הכתוב \"לא תאפה חמץ\" לומר שאף הרביכה פוסלת את המנחה!","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על שאלת ר' אמי בדומה לכך גם \u0003רבינא: ואימא\u0004 \u0005[ואמור]\u0006 כי הכתוב \u0003\"לא תאפה חמץ\"\u0004 — בא \u0003למיקם גברא בלאו בעלמא\u0004 \u0005[להעמיד\u0006 את \u0005האיש\u0006 המביא מנחת חמץ \u0005ב\u0006איסור \u0005לאו בלבד],\u0006 \u0003ו\u0004אולם לענין \u0003איפסולי\u0004 \u0005[פסילת]\u0006 המנחה שאינה מצה — \u0003לא מיפסלא\u0004 \u0005[אינה נפסלת]\u0006 בכך?!","ולאחר שהוקשו כל הקושיות הללו, להוכיח שאת הפסוק \"לא תאפה חמץ\" אפשר לדרוש לענין אחר, ולא בהכרח לעכב בדין הבאת מנחות מצה, יש איפוא לחזור ולשאול: \u0003אלא מנלן\u0004 \u0005[מנין לנו]\u0006 שכל המנחות פסולות אם לא הובאו מצה? ומשיבים: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בדין המנחה \u0003\"מצה\u0004 תהיה\" (ויקרא ב, ה), ומן הלשון \"מצה\" \u0003יכול\u0004 שאין ללמוד אלא \u0003ש\u0004\u0003מצוה\u0004 לכתחילה שתהיה המנחה מצה, ואולם אינה פסולה כשאינה מצה? לכך \u0003תלמוד לומר: \"תהיה\"\u0004 — ללמדנו כי \u0003הכתוב קבעה חובה,\u0004 שאם לא נעשתה כן, נפסלה.","וכיוצא בזה עוד \u0003בעא מינה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' פרידא מר' אמי: מנין,\u0004 מה המקור להלכה הנוגעת \u0003לכל המנחות\u0004 הבאות מצה \u0003ש\u0004הן \u0003נילושות ב\u0004מים \u0003פושרין, ומשמרן\u0004 העושה אותן \u0003שלא יחמיצו?\u0004 האם \u0003נלמדנה מ\u0004האמור באיסור חמץ בחג ה\u0003פסח, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ושמרתם את המצות\"\u0004 (שמות יב, יז), ללמדנו שכל מאפה האמור להיות מצה יש לשמור את בצקו לבל יגיע לכלל חימוץ?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: אין דין המנחה נלמד מדין חמץ בפסח, \u0005שכן\u0006 \u0003בגופה\u0004 (בה עצמה, בפרשת המנחה) \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"מצה תהיה\",\u0004 ונקראים הדברים (בחילופי האותיות ה'— ח'): מצה \u0003החייה,\u0004 שאתה צריך לשמר אותה כפי שהיא (בחייה), שלא תחדל להתקיים כמצה ותהיה חמץ.","ומקשים: \u0003והא אפיקתיה\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת,\u0006 דרשת\u0005]\u0006 את המלה הזו \"תהיה\" ללמוד שהמנחה צריכה להיות בכל אופן מצה שדין זה הוא \u0003לעכב!\u0004 ומשיבים: \u0003אם כן\u0004 שלא בא הכתוב אלא ללמדנו הלכה זו בלבד, \u0003ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"מצה היא\", מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 נאמר \"מצה \u0003תהיה\"? שמעת מינה תרתי\u0004 \u0005[לומד אתה ממנה שני\u0006 דברים\u0005].\u0006","כיון שהובאו דברים של ר' פרידא, מביאים גם מהמסופר עליו. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לר' פרידא:\u0004 החכם \u0003ר' עזרא,\u0004 הוא מיוחס ביותר לפי שהוא \u0003בר בריה\u0004 \u0005[בן בנו]\u0006 של החכם \u0003ר' אבטולס,\u0004 ש\u0003הוא\u0004 דור \u0003עשירי לר' אלעזר בן עזריה,\u0004 ו\u0003הוא\u0004 (ר' אלעזר בן עזריה) הריהו דור \u0003עשירי לעזרא\u0004 הסופר, \u0003קאי אבבא\u0004 \u0005[עומד\u0006 ממתין \u0005בשער]\u0006 הבית ומבקש להיכנס פנימה. \u0003אמר\u0004 להם ר' פרידא לחכמים: \u0003מאי כולי האי\u0004 \u0005[מה כל\u0006 הפירוט \u0005הזה]\u0006 של היחוס?","שכן \u0003אי בר אוריין\u0004 \u0005[אם בן תורה]\u0006 \u0003הוא\u0004 — \u0003יאי\u0004 \u0005[ראוי\u0006\u0003]\u0004 הוא כשלעצמו לקבל רשות להיכנס, ואין הוא נזקק לציון יחוסו כדי לקבל רשות להיכנס. ו\u0003אי\u0004 \u0005[אם]\u0006 הוא גם \u0003בר אוריין\u0004 \u0005[בן תורה]\u0006 \u0003ו\u0004גם \u0003בר אבהן\u0004 \u0005[בן אבות,\u0006 מיוחס\u0005]\u0006 — \u0003יאי\u0004 \u0005[ראוי\u0006\u0003]\u0004 הוא להיכנס, שיש בו מזה ומזה. \u0003ו\u0004אולם \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003בר אבהן\u0004 \u0005[בן אבות]\u0006 \u0003ולא בר אוריין\u0004 \u0005[בן תורה]\u0006 — מוטב ש\u0003אישא תיכליה\u0004 \u0005[תאכל אותו האש],\u0006 ואל יכנס לביתי, שמעלה זו של ייחוס הריהי מקטרגת עליו, על שאין הוא כאבותיו החכמים! \u0003אמרו ליה\u0004 \u0005[לו]\u0006 החכמים \u0005לר' פרידא: ר' עזרא זה,\u0006 \u0003בר אוריין\u0004 \u0005[בן תורה]\u0006 \u0003הוא. אמר להו\u0004 \u0005[להם]:\u0006 אם כן, \u0003ליעול וליתי\u0004 \u0005[שיכנס ויבוא].\u0006","כשנכנס ר' עזרא לביתו של ר' פרידא \u0003חזייה\u0004 \u0005[ראהו]\u0006 ר' פרידא \u0003דהוה עכירא דעתיה\u0004 \u0005[שהיתה דעתו\u0006 של ר' עזרא \u0005עכורה]\u0006 מפני צער ועלבון העיכוב שעיכבו אותו, \u0003פתח\u0004 ר' פרידא \u0003ואמר\u0004 דרשה זו לכבודו של ר' עזרא, להניח דעתו: נאמר בכתוב \u0003\"אמרת לה' אדני אתה טובתי בל עליך\"\u0004 (תהלים טז, ב), שכך \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, החזק לי טובה,\u0004 על \u0003שהודעתיך\u0004 (פרסמתי את שמך) \u0003בעולם\u0004 (\"אמרת לה' אדני אתה\").","\u0003אמר לה: \"טובתי בל עליך\"\u0004 — \u0003איני מחזיק טובה\u0004 על כך \u0003אלא ל\u0004שלושת האבות, \u0003אברהם יצחק ויעקב ש\u0004הם \u0003הודיעוני תחלה בעולם, ש\u0004כן \u0003נאמר\u0004 בהמשך כתוב זה \u0003\"לקדושים אשר בארץ המה ואדירי כל חפצי בם\"\u0004 (שם, ג), ו\"קדושים\" הם האבות ו\"כל חפצי בם\". ורמז לו על חשיבותם וייחוסם של האבות, ובכלל זה כמובן עזרא הסופר, שר' עזרא מתייחס אליו.","\u0003כיון דשמעיה דקאמר\u0004 \u0005[ששמע\u0006 ר' עזרא את ר' פרידא \u0005שהוא אומר]\u0006 את המלה \u0003\"אדיר\"\u0004 (\"ואדירי כל חפצי בם\"), \u0003פתח\u0004 אף הוא \u0003ואמר\u0004 דרשה שעניינה המלה \"אדיר\" בהטיות שונות: \u0003\"יבא אדיר ויפרע לאדירים מאדירים באדירים\".\u0004","וחזר ופירש את הדברים: \u0003\"יבא אדיר\"\u0004 — \u0003זה הקדוש ברוך הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"אדיר במרום ה' \"\u0004(שם צג, ד). \u0003\"ויפרע לאדירים\"\u0004 — \u0003אלו ישראל, שנאמר\u0004 בהם: \u0003\"ואדירי כל חפצי בם\". \"מאדירים\"\u0004 — \u0003אלו המצרים, דכתיב\u0004 \u0005[שנאמר]\u0006 בהם בקריעת ים סוף: \u0003\"צללו כעופרת במים אדירים\"\u0004 (שמות טו, י). \u0003\"באדירים\"\u0004 — \u0003אלו מים, שנאמר\u0004 בהם: \u0003\"מקלות מים רבים אדירים משברי ים\"\u0004 (תהלים צג, ד).","ועוד דרש ר' עזרא, כעין זה: \u0003\"יבא ידיד בן ידיד, ויבנה ידיד לידיד בחלקו של ידיד, ויתכפרו בו ידידים\".\u0004","ופירש דבריו: \u0003\"יבא ידיד\"\u0004 — \u0003זה שלמה המלך,\u0004 שכך כינויו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו, לאחר שנולד: \u0003\"וישלח ביד נתן הנביא ויקרא שמו ידידיה בעבור ה' \"\u0004(שמואל ב יב, כה)."],["\u0003\"בן ידיד\"\u0004 — \u0003זה אברהם, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"מה לידידי בביתי\"\u0004 (ירמיהו יא, טו), שיתבאר בהמשך. \u0003\"ויבנה ידיד\"\u0004 — \u0003זה בית המקדש, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"מה ידידות משכנותיך\"\u0004 (תהלים פד, ב). \u0003\"לידיד\"\u0004 — \u0003זה הקדוש ברוך הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"אשירה נא לידידי\"\u0004 (ישעיהו ה, א).","\u0003\"בחלקו של ידיד\"\u0004 — \u0003זה בנימין\u0004 שנבנה בית המקדש בתחום שבטו, \u0003שנאמר\u0004 בו בברית משה: \u0003\"לבנימין אמר ידיד ה' ישכן לבטח עליו\"\u0004 (דברים לג, יב). \u0003\"ויתכפרו בו ידידים\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]\u0006 בהם: \u0003\"נתתי את ידידות נפשי בכף אויביה\"\u0004 (ירמיהו יב, ז).","ועוד דרש ר' עזרא בדומה לזה: \u0003\"יבא טוב, ויקבל טוב מטוב לטובים\".\u0004 ופירש: \u0003\"יבא טוב\"\u0004 — \u0003זה משה, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ותרא אותו כי טוב הוא\"\u0004 (שמות ב, ב). \u0003\"ויקבל טוב\"\u0004 — \u0003זו\u0004 ה\u0003תורה, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"כי לקח טוב נתתי לכם\u0004 תורתי אל תעזובו\" (משלי ד, ב). \u0003\"מטוב\"\u0004 — \u0003זה הקדוש ברוך הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"טוב ה' לכל\"\u0004 (תהלים קמה, ט). \u0003\"לטובים\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]\u0006 בהם: \u0003\"הטיבה ה' לטובים\"\u0004 (שם קכה, ד).","ועוד דרש ר' עזרא: \u0003\"יבא זה, ויקבל זאת מזה לעם זו\".\u0004 ופירש: \u0003\"יבא זה\"\u0004 — \u0003זה משה, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"כי זה משה האיש\"\u0004 (שמות לב, א). \u0003\"ויקבל זאת\"\u0004 — \u0003זו התורה, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"וזאת התורה אשר שם משה\"\u0004 (דברים ד, מד), \u0003\"מזה\"\u0004 — \u0003זה הקדוש ברוך הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"זה אלי ואנוהו\"\u0004 (שמות טו, ד). \u0003\"לעם זו\"\u0004 — \u0003אלו ישראל, שנאמר\u0004 בהם: \u0003\"עם זו קנית\"\u0004 (שם טז).","מתוך שהובא הכתוב \"מה לידידי בביתי\" לענין כינויו של אברהם \"ידיד\", מביאים בדרשת כתוב זה והכתובים הבאים אחריו. שנאמר: \"מה לידידי בביתי עשותה המזמתה הרבים ובשר קודש יעברו מעליך כי רעתכי אז תעלוזי. זית רענן יפה פרי תואר קרא ה' שמך לקול המולה גדולה הצית אש עליה ורעו דליותיו\" (ירמיה יא, טו— טז). ובדרשת כתוב זה \u0003אמר ר' יצחק: בשעה שחרב בית המקדש, מצאו הקדוש ברוך הוא לאברהם שהיה עומד בבית המקדש, אמר לו:\u0004 \u0003מה לידידי בביתי?\u0004","\u0003אמר לו\u0004 אברהם בתשובה: \u0003על עיסקי בני באתי,\u0004 מדוע מחריב ה' את בית המקדש ומגלה אותם מן הארץ. \u0003אמר לו\u0004 הקדוש ברוך הוא: טעם הדבר, משום ש\u0003בניך חטאו, ו\u0004לכן נענשו ו\u0003גלו\u0004 מן הארץ. \u0003אמר לו\u0004 אברהם לקדוש ברוך הוא: \u0003שמא בשוגג חטאו,\u0004 ואין מגיע להם עונש שכזה? \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003\"עשותה המזמתה\"\u0004 — מעשיהם הרעים היו במזימה, במזיד ולא בשגגה, ועל כך הם נענשים. \u0003אמר לו\u0004 אברהם: \u0003שמא\u0004 רק \u0003מיעוטן\u0004 של בני ישראל הם ש\u0003חטאו,\u0004 ואין ראוי שייענש כל העם מחמת מיעוט שבו? \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003\"הרבים\"\u0004 — רובם של בני ישראל חטאו.","אמר לו אברהם: ואף על פי כן \u0003היה לך לזכור\u0004 לבני ישראל את זכות \u0003ברית מילה\u0004 שהם נימולים, ולא להענישם על חטאיהם! \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003\"ובשר קדש יעברו מעליך\"\u0004 — שאף עברו וביטלו את קדושת בשרם, מצות ברית המילה. \u0003אמר לו\u0004 אברהם: ועדיין לא היה להענישם על חטאיהם, \u0003שמא אם המתנת להם, היו חוזרין בתשובה. אמר לו\u0004 הקדוש ברוך הוא: \u0003\"כי רעתכי אז תעלזי\"\u0004 — ראוי היה להענישם על חטאיהם, ולא להמתין עד שישובו בתשובה. שכן בשעה שחוטאים הם, ואין הם נענשים על כך אלא עושים ימיהם בטוב ובנעימים (\"אז תעלוזי\") — אין הם חוזרים בתשובה, אלא מוסיפים על חטאיהם (\"כי רעתיכי\").","כיון שנדחו כל דבריו, \u0003מיד הניח\u0004 אברהם את \u0003ידיו על ראשו\u0004 כאדם האבל ומצטער, \u0003והיה צועק ובוכה, ואמר לו\u0004 להקדוש ברוך הוא: \u0003שמא חס ושלום אין להם\u0004 לבני ישראל עוד \u0003תקנה? יצתה בת קול ואמרה לו: \"זית רענן יפה פרי תאר קרא ה' שמך\"\u0004 — \u0003מה זית זו\u0004 אין \u0003אחריתו\u0004 (תכליתו) מתקיימת אלא \u0003בסופו\u0004 לכשקוטפים את פירותיו, \u0003אף ישראל\u0004 אין \u0003אחריתן\u0004 מתקיימת אלא \u0003בסופן.\u0004","ועוד נאמר בכתוב זה \u0003\"לקול המולה גדלה הצית אש עליה ורעו דליותיו\"\u0004 (ירמיה יא, טז). \u0003אמר ר' חיננא בר פפא\u0004 בדרשת הכתוב: \u0003לקול מיליהן\u0004 (\"לקול המולה\") \u0003של מרגלים\u0004 ששלח משה לתור את הארץ והוציאו דיבת הארץ רעה, \u0003ניתרועעו דליותיהן\u0004 (ענפיהם) \u0003של ישראל.\u0004 שכן \u0003אמר ר' חיננא בר פפא\u0004 בגודל חטאם של המרגלים: \u0003דבר\u0004 של חטא \u0003גדול דברו מרגלים באותה שעה,\u0004 \u0003שאמרו:\u0004 \u0003\"כי חזק הוא ממנו\"\u0004 (במדבר יג, לא) — \u0003אל תיקרי\u0004 (תקרא) \u0003\"ממנו\"\u0004 במובן מאיתנו, \u0003אלא \"ממנו\"\u0004 — מן הקדוש ברוך הוא, וכרוצים לומר: \u0003כביכול, שאפילו בעל הבית\u0004 (הקדוש ברוך הוא) \u0003אינו יכול להוציא כליו משם,\u0004 שאמרו שהעם שם חזק אף מהקדוש ברוך הוא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' חייא בר' חיננא: האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"לקול המולה גדלה\",\u0004 לדרך פירושך את הכתוב (\"לקול מיליהן של מרגלים\"), \u0003\"לקול מלה\" מיבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא\u0004 כך הוא פירושו של כתוב זה, ונסמך על דרשתו של ר' יצחק האמורה למעלה, כי באברהם אבינו הטוען לפני הקדוש ברוך הוא בזמן החורבן אמורים הדברים: \u0003אמר לו הקדוש ברוך הוא לאברהם: קולך שמעתי\u0004 (\"לקול\") \u0003וחמלתי\u0004 (\"המולה\" — חמלה, בחילופי אותיות ח' ה') \u0003עליהם,\u0004 ומקל אני בדינם. שכן \u0003אני אמרתי\u0004 בתחילה כי \u0003ישתעבדו\u0004 בני ישראל \u0003בארבע מלכיות\u0004 (בבל, פרס, יון ורומי), ב\u0003כל אחת ואחת\u0004 מהמלכויות הללו \u0003כשיעור\u0004 שקבעתי מלכתחילה לשיעבוד כל ה\u0003ארבע מלכיות\u0004 גם יחד.","\u0003השתא\u0004 \u0005[עכשיו]\u0006 מכיון שהתפללת וביקשת עליהם, ישתעבדו בני ישראל ב\u0003כל חדא וחדא\u0004 \u0005[אחת אחת]\u0006 מארבע המלכויות הללו רק כשיעור \u0003מאי דפסיק\u0004 \u0005[מה שנפסק,\u0006 נקבע\u0005]\u0006 \u0003לה\u0004 בלבד. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 שכך אמר הקדוש ברוך הוא לאברהם: \u0003אני אמרתי\u0004 בתחילה שימשלו בבני ישראל המלכויות הללו \u0003בזה אחר זה,\u0004 כל אחת בזמן שקבעתי לשיעבודה, \u0003עכשיו\u0004 אני גוזר שתהיה ממשלתם \u0003בבת אחת,\u0004 ויתמעט בכך זמן השיעבוד.","באותם כתובים שבספר ירמיה נמשלו ישראל לזית (\"זית רענן יפה פרי תואר קרא ה' שמך\"). ובענין זה \u0003אמר ר' יהושע בן לוי: למה נמשלו\u0004 בני \u0003ישראל ל\u0004עץ ה\u0003זית? לומר לך: מה\u0004 עץ ה\u0003זית אין עליו נושרין, לא בימות החמה ולא בימות הגשמים, אף\u0004 בני \u0003ישראל אין להם בטילה עולמית, לא בעולם הזה ולא בעולם הבא. ו\u0004עוד בענין דימויים של בני ישראל לזית, \u0003אמר ר' יוחנן: למה נמשלו\u0004 בני \u0003ישראל ל\u0004פרי ה\u0003זית? לומר לך: מה\u0004 פרי ה\u0003זית אינו מוציא שמנו אלא על ידי כתיתה\u0004 (שבירה וריסוק), \u0003אף\u0004 בני \u0003ישראל\u0004 אם חוטאים הם, \u0003אין\u0004 הם \u0003חוזרין למוטב אלא על ידי יסורין,\u0004 המשברים את הגוף ואת הנפש.","שנינו במשנתנו כי \u0003ר' מאיר אומר\u0004 שאת \u0003השאור\u0004 בו הוא אמור להחמיץ את מנחות החמץ הריהו \u0003בודה\u0004 (מפריש) \u0003להן מתוכן,\u0004 מהעיסה עצמה, \u0003ומחמיצן.\u0004 ואילו ר' יהודה אומר שמביאו מעיסה אחרת, ישנה. והקשו חכמים על ר' יהודה, שלשיטתו נמצאת המידה חסירה או יתירה. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חסירה או יתירה\"\u0004 שאמרו חכמים?","\u0003אמר רב חסדא\u0004 בהסבר הדברים: אם היתה \u0003עיסת השאור\u0004 אותה הוא מביא ממקום אחר \u0003עבה,\u0004 שהקמח שבה בלול במעט מים, ונפחו קטן (שאילו היה עדיין קמח היה נפחו מדוייק), ומעתה כשימדוד את השאור העבה הזה עם הסולת במידת העשרון — \u0003נמצאת\u0004 מדת סולת המנחה \u0003יתירה\u0004 בתוך \u0003מדת העשרון,\u0004 שיש יותר בעשרון ממה שצריך להיות, שהרי צריך להשלים מן הסולת את הכמות החסרה בשל היות השאור קטן מהראוי. ומן הצד האחר, אם היתה עיסת השאור \u0003רכה,\u0004 שהקמח שבה בלול בהרבה מים, נמצא שנפחו גדול מהראוי וכדי להשלים את מדת העשרון הריהו מוסיף שיעור סולת הקטן מהראוי, ו\u0003נמצאת\u0004 מדת סולת המנחה \u0003חסירה\u0004 בתוך מידת העשרון.","ומקשים על הסברו של רב חסדא: מה בכך אם נעשה השאור מבלילה עבה או גסה, והרי \u0003סוף סוף\u0004 (בסופו של דבר), \u0003כי קא כייל\u0004 \u0005[כאשר הוא,\u0006 עושה המנחה, \u0005מודד]\u0006 עתה את השאור הבא מבחוץ ואת הסולת למנחה, הלא \u0003ל\u0004מידת \u0003עשרון\u0004 הראוי \u0003קא כייל\u0004 \u0005[הוא מודד]!\u0006","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]\u0006 אותה תשובה: כדי להגיע לשיעור הנכון יש לדעת כמה קמח היה במקור בשאור קודם שניתנו בו מים והפך לשאור, וכן בסולת, שכן \u0003לכמות\u0004 (כמו) \u0003שהן\u0004 (קמח \u0003השאור וסולת המנחה)\u0004 \u0003היתה\u0004 לפני הבלילה \u0003משערינן\u0004 \u0005[משערים,\u0006 מודדים, \u0005אנו]\u0006 את מדת העשרון, ולא לפי המידה הנוכחית.","ושואלים: אף לשיטת חכמים שאין לעשות כשיטת ר' יהודה, מפני החשש לחסרה או יתירה, והרי יש דרך לעשות \u0003שאור בחוץ, בלא חשש חסר או יתר,\u0004 \u0003ו\u0004באופן זה: \u0003לישקול פורתא מיניה\u0004 \u0005[שיקח מעט\u0006 סולת \u0005ממנו],\u0006 ממידת העשרון, לאחר שנמדד ונמצא כשיעור, \u0003וליחמציה מאבראי\u0004 \u0005[ושיחמיץ אותו מחוץ\u0006 לעיסה\u0005],\u0006 באופן שיחמיץ היטב, ולאחר מכן ישוב \u0003וליתיה, ונילושיה בהדיה\u0004 \u0005[ויביא אותה, וילוש אותה ביחד\u0006 עם העיסה\u0005]!\u0006 ומשיבים: אין לעשות כן, שכן \u0003גזירה\u0004 היא שגזרו חכמים שלא לעשות כן, מפני החשש שיאמרו הרואים את השאור המובא מהחוץ, שמביאים את עיסת המנחה מן החוץ, ובעקבות זאת \u0003דלמא אתי לאיתויי מעלמא\u0004 \u0005[שמא יבואו להביא מן החוץ]\u0006 עיסה שאינה קדושה למנחה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מחמיצין\u0004 (מביאים לידי חימוץ) את המנחות הבאות חמץ"],["\u0003ב\u0004מיץ היוצא מפירות ה\u0003תפוחים,\u0004 שאין זה חימוץ ראוי. \u0003משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל אמרו\u0004 חכמים \u0003כי\u0004 \u0003מחמיצין\u0004 את המנחות הללו במיץ תפוחים, והרי זה חימוץ ראוי. ומעירים כי \u0003רב כהנא מתני לה\u0004 \u0005[היה שונה אותה]\u0006 הלכה, לא בשמו של ר' חנינא בן גמליאל, אלא \u0003ב\u0004שמו של \u0003ר' חנינא בן תרדיון.\u0004","ודנים במחלוקת זו: \u0003כמאן אזלא הא דתנן\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 משנה \u0005זו ששנינו]:\u0006 פרי \u0003תפוח\u0004 של תרומה, \u0003שריסקו, ונתנו בתוך העיסה\u0004 של חולין, \u0003ו\u0004מיץ התפוח \u0003חימצה\u0004 את העיסה — \u0003הרי זו\u0004 העיסה \u0003אסורה\u0004 באכילה למי שאינו רשאי לאכול תרומה.","ומעתה יש לברר: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 משנה זו. ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שכדעת \u0003ר' חנינא בן גמליאל,\u0004 הסבור שהתפוחים מחמיצים כראוי, \u0003היא\u0004 משנה זו, \u0003ולא\u0004 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים שאין התפוחים מחמיצים כראוי! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנה זו היא כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הריהי גם כן מובנת. שכן יש לומר, \u0003נהי\u0004 \u0005[אמנם]\u0006 לדעת חכמים הבצק שהוחמץ על ידי תפוחים \u0003חמץ גמור\u0004 הוא \u0003לא הוי\u0004 \u0005[לא נהיה]\u0006 בכך, ואולם חמץ \u0003נוקשה\u0004 (חלוש) \u0003מיהא הוי\u0004 \u0005[בכל אופן נהיה].\u0006 ומשום כך, העיסה שהוחמצה על ידי תפוח התרומה, נאסרה.","בעמוד הקודם הובאו דבריהם של רבה ורב יוסף בדרך שיעור המדידה של עיסת השאור, הנעשית לא לפי מצבה הנוכחי בהיותה כבר מגובלת במים, אלא כפי שהיתה לפני הגיבול, קמח. ודנים עוד בענין זה. ובתחילה מביאים מה ש\u0003אמר ר' אילא:\u0004 מכל המנחות \u0003אין לך\u0004 מנחה \u0003הקשה\u0004 \u0003ל\u0004עבודת ה\u0003קמיצה יותר ממנחת חוטא.\u0004 שכן מנחה זו הריהי יבישה (שהרי אסרה תורה לתת בה שמן), וקשה ביותר לקמוץ ממנה באופן שלא יהיה הקומץ חסר משיעורו הראוי. שכאשר עושה הכהן את הקמיצה בשתי אצבעותיו, האגודל והזרת, נשמטת כמות גדולה של קמח. ואילו \u0003רב יצחק בר אבדימי אמר:\u0004 אין קמיצתה של מנחת חוטא קשה מקמיצתן של שאר המנחות, שכן אף שאסרה התורה לתת שמן ב\u0003מנחת חוטא,\u0004 מכל מקום הריהו \u0003מגבלה במים, וכשרה\u0004 היא.","ודנים במחלוקתם: \u0003לימא בהא קא מיפלגי\u0004 \u0005[האם נאמר\u0006 כי \u0005בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רב יצחק בר אבדימי, \u0005סבור]:\u0006 את המנחות, \u0003כמות שהן\u0004 עכשיו לפנינו, כשהן כבר בלולות לעיסה, \u0003משערינן\u0004 \u0005[משערים אנו].\u0006 וכיון שעתה כשהן בלולות במים הריהן מוכשרות לעבודתן, אף הקמיצה בהן אינה כה קשה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אילא, \u0005סבור]\u0006 כי את המנחות, \u0003לכמות שהיו\u0004 לפני בלילתן, כשהן עדיין קמח, \u0003משערינן\u0004 \u0005[משערים אנו].\u0006 ומעתה אם יבלול את הקמח במעט מים — תהיה העיסה שתתקבל עבה מדי, ונפחה יקטן. ואם יתן בקמח הרבה מים — תתקבל עיסה שהיא דקה מדי, ונפחה גדול. ובשני אופנים אלה, לא יהיה בקמיצה שיעור קומץ הקמח הראוי, ולכן אין נותנים בעיסה מים.","ודוחים: \u0003לא\u0004 בזה היתה המחלוקת, \u0003דכולי עלמא\u0004 \u0005[ש\u0006כן \u0005לדעת הכל]\u0006 \u0003כמות שהן\u0004 עתה \u0003משערינן\u0004 \u0005[משערים אנו],\u0006 \u0003ו\u0004אולם \u0003בהא קא מיפלגי\u0004 \u0005[בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יצחק בר \u0005אבדימי,\u0006 \u0005סבור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חרבה\"\u0004 האמורה במנחת חוטא (\"וכל מנחה בלולה בשמן וחרבה\", ויקרא ז, י)? — \u0003חריבה\u0004 \u0003משמן,\u0004 ואולם מים יכול לתת בה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אילא, \u0005סבור]:\u0006 כי מנחת חוטא צריכה להיות \u0003חריבה מכל דבר,\u0004 הן משמן והן ממים.","השאלה בדין המנחה אם נמדדת כפי שהיא עתה בלולה, או כפי שהיתה קודם שנבללה, הריהי שאלה הלכתית עקרונית שבדומה לה דנים אף בהלכות אחרות. \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במסכת עוקצין\u0005]:\u0006 \u0003בשר העגל שנתפח\u0004 בבישול (שכך היא דרכו של בשר העגל שהוא גדל בנפחו כשהוא מתבשל במים), או \u0003בשר\u0004 בהמה \u0003זקנה שנתמעך\u0004 (שהתמעט) תוך כדי בישול, (שכך היא דרכו של בשר זה, שהוא מצטמק כשהוא מתבשל) — הרי אלו \u0003משתערין\u0004 (נמדדים) לענין הטומאה (לקבל טומאה, ולטמא אחרים בטומאת אוכלים) אם יש בהם כשיעור ביצה, \u0003לכמות שהן.\u0004 ובפירוש הביטוי \"לכמות שהן\" נחלקו חכמים.","ש\u0003רב ו\u0004כן \u0003ר' חייא ור' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 הכוונה היא שהם \u0003משתערין כמות שהן\u0004 עתה לפנינו, לאחר בישולם. ואילו \u0003שמואל ו\u0004כן \u0003ר' שמעון בר רבי, וריש לקיש אמרי\u0004 \u0005[אומרים]:\u0006 הכוונה היא שהם \u0003משתערין לכמות שהן\u0004 היו לפני בישולם. ולכן בשר העגל אף שלאחר הבישול יש בו כביצה, אם לפני הבישול לא היה בו כביצה — אינו בדין טומאה. ואילו בשר הבהמה הזקנה אף שלאחר הבישול אין בו כביצה, אם לפני הבישול היה בו כביצה — הריהו בדין טומאה.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 על החכמים הסבורים שכמות שהיו הם משתערים, ממה ששנינו בברייתא: \u0003בשר העגל שלא היה בו כשיעור\u0004 טומאה קודם בישולו, ונטמא, והתבשל, \u0003ו\u0004כתוצאה מהבישול \u0003תפח ועמד על כשיעור\u0004 טומאה (בכביצה) — הריהו \u0003טהור לשעבר,\u0004 כלומר, אין הוא נחשב טמא בשל אותה טומאה, כיון שזו נגעה בו כשלא היה בו כשיעור קבלת טומאה. \u0003ו\u0004הריהו \u0003טמא\u0004 ומטמא \u0003מיכן\u0004 (מכאן, מעתה) \u0003ולהבא.\u0004 הרי איפוא, שדין הטומאה נקבע על פי מדידת הדבר עתה!","ומשיבים: מכאן אין להקשות, שכן אפשר לומר שמדין תורה אכן אין בשר זה בדין טומאה אף מכאן ולהבא, כיון שנמדד שיעורו כפי שהיה קודם הבישול, וטומאה זו אינה אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין טומאה זו אלא מדברי סופרים, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: \u0003וכן\u0004 הדין \u0003ב\u0004קדשים שנפסלו משום \u0003פיגול\u0004 (שחשב עליו הכהן בשעת עבודה לאוכלו שלא בזמנו הראוי), \u0003וכן בנותר\u0004 (שעבר הזמן המותר באכילתו). ומעתה יש לומר: \u0003אי אמרת בשלמא דאורייתא\u0004 \u0005[נניח,\u0006 מובנים דברי הברייתא, \u0005אם אומר אתה ש\u0006הדין האמור בה הוא \u0005מן התורה],\u0006 \u0003היינו דאיכא\u0004 \u0005[זהו שיש]\u0006 מקום לשנות בה \u0003דין\u0004 \u0003פיגול ונותר,\u0004 שאף הוא מדין תורה. \u0003אלא אי אמרת דרבנן\u0004 \u0005[אם אומר אתה ש\u0006דין הברייתא הוא \u0005מדברי סופרים],\u0006 יש לשאול: \u0003פיגול ונותר בדרבנן מי איכא\u0004 \u0005[מדברי סופרים האם\u0006 בכלל \u0005יש]?\u0006","ומשיבים, \u0003אימא\u0004 \u0005[אמור]\u0006 כך בדברי הברייתא: \u0003וכן בטומאת פיגול, וכן בטומאת נותר.\u0004 שכן גזרו בהם חכמים שיטמאו את הידים, אף אם לא נטמאו. ומשמיעה לנו הברייתא בסופה, שאף בטומאה זו שמדברי חכמים, כך הוא הדין, שאם יש בהם כשיעור טומאה רק משעת בישול הריהם בכלל דין טומאה.","כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004כל עיקרה של \u0003טומאת פיגול וטומאת נותר\u0004 רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא,\u0004 ולהחמיר \u0003כולי האי\u0004 \u0005[כל זה,\u0006 כה הרבה\u0005],\u0006 שיטמאו (מכאן ולהבא) אף דברים שקודם בישולם לא היה בהם שיעור טומאה, \u0003ב\u0004טומאה שהיא \u0003רק\u0004 \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא עבוד רבנן\u0004 \u0005[לא עשו חכמים],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא שבסוף הברייתא \u0005משמיע לנו]\u0006 שנוהג דין זה אף בטומאה שמדברי סופרים.","ומוסיפים עוד לענין מחלוקת זו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003בשר\u0004 בהמה \u0003זקנה שהיה בו\u0004 מתחילה \u0003כשיעור\u0004 טומאה, ונטמא, והתבשל, \u0003ו\u0004כתוצאה מכך \u0003צמק\u0004 עד ל\u0003פחות מכשיעור\u0004 טומאה — הריהו נחשב \u0003טמא ל\u0004ענין הטומאות שנגעו בו בזמן \u0003שעבר,\u0004 כאשר היה בו שיעור קבלת טומאה, \u0003ו\u0004הריהו \u0003טהור מיכן\u0004 (מכאן, מעתה) \u0003ולהבא.\u0004 הרי איפוא שיש למדוד לפי המצב הנוכחי.","\u0003אמר רבה\u0004 בפירוש מחלוקת חכמים זו, ובאופן שלא יקשה על אחת השיטות ממה ששנינו כאן: \u0003כל היכא דמעיקרא הוה ביה\u0004 \u0005[כל מקום,\u0006 מקרה \u0005שמתחילה היה בו]\u0006 שיעור, \u0003והשתא לית ביה\u0004 \u0005[\u0006\u0005ועכשיו אין בו]\u0006 — \u0003הא לית ביה\u0004 \u0005[הרי אין בו],\u0006 וברור הוא שיש לשער כפי המצב הנוכחי. \u0003ו\u0004כמו כן, \u0003כל היכא דמעיקרא לא הוה ביה\u0004 \u0005[כל מקום,\u0006 מקרה, \u0005שמתחילה לא היה בו]\u0006 שיעור, \u0003והשתא הוה ביה\u0004 \u0005[ועכשיו יש בו]\u0006 — הריהו מטמא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006"],["\u0003כי פליגי\u0004 \u0005[כאשר,\u0006 באיזה מקרה, \u0005נחלקו]\u0006 חכמים אלה — \u0003כגון שהיה בו\u0004 בתחילה \u0003כשיעור\u0004 טומאה, \u0003ו\u0004לאחר מכן \u0003צמק\u0004 (התכווץ) ואין בו עוד כשיעור טומאה, \u0003ו\u0004לאחר מכן \u0003חזר ותפח\u0004 לכלל שיעור טומאה. ובכך נחלקו חכמים אלו: \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 שמואל ור' שמעון ברבי וריש לקיש, \u0005סבור]\u0006 כי כלל הוא ש\u0003יש דיחוי באיסורא\u0004 \u0005[באיסור],\u0006 וכמו כן יש דיחוי בטומאה. שכיון שבשלב מסויים (כשצמק שיעורו) נדחה הדבר מכלל דין טומאה — הריהו נדחה לגמרי, אף אם יתפח וישוב לכלל שיעור טומאה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב ור' חייא ור' יוחנן, \u0005סבור]\u0006 כי \u0003אין דיחוי באיסורא\u0004 \u0005[באיסור],\u0006 וכמו כן אין דיחוי בטומאה, ואף אם בשלב מסויים נדחה הדבר מדין טומאה (כשצמק משיעורו), אם תפח וחזר לשיעורו — חזר לדין הטומאה.","ומקשים על הסברו זה של רבה: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003יש דיחוי באיסורין? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 דבר שיש בו שיעור \u0003כביצה\u0004 שהוא מן ה\u0003אוכלין\u0004 (דברי מאכל) הטמאים, \u0003שהניחה בחמה ו\u0004כתוצאה מכך \u0003נתמעטו\u0004 משיעור ביצה. \u0003וכן\u0004 \u0003כזית מן\u0004 בשר \u0003המת,\u0004 וכן \u0003כזית מן הנבלה, וכעדשה מן השרץ\u0004 המטמאים\u0003, וכזית פיגול, וכזית נותר, וכזית חלב\u0004 שהניחם בחמה, וכתוצאה מכך פחתו משיעור כזית — הרי אלה \u0003טהורין\u0004 מלטמא אחרים, \u0003ואין חייבין עליהן משום פיגול ונותר וחלב.\u0004","ואם נטל את כל אלה, לאחר שצמקו בחמה, וחזר ו\u0003הניחן בגשמים ו\u0004כתוצאה מכך \u0003תפחו\u0004 שוב לכשיעור הראוי לענין טומאה — הרי אלו שוב \u0003טמאין,\u0004 כדרך שהיו לפני שצמקו, בין לטומאת מת ונבילה ובין לטומאת אוכלים, \u0003וחייבין עליהם משום פיגול ונותר וחלב.\u0004 הרי איפוא שאין דיחוי, והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה],\u0006 לדרך הסברו של רבה, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003יש דיחוי באיסורין!\u0004 ומסכמים: אכן, הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ונדחו דבריו.","ושבים לבירור המחלוקת אם משערים כמות שהן או כמות שהיו. ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו כי \u0003תורמין\u0004 (מפרישים תרומות ומעשרות) מן ה\u0003תאנים\u0004 הטריות \u0003על הגרוגרות\u0004 (התאנים שיובשו וצמקו מנפחן המקורי). ודרך הפרשה זו אינה נעשית אלא \u0003במנין\u0004 כגון שמפריש עשר תאנים לחות על תשעים גרוגרות. ואין מפרישים בדרך מדידה, שיטול מהתאנים עשירית מידתן של הגרוגרות (שכן בדרך זו הריהו מפריש פחות מכמות התאנים שהיו מופרשות בדרך המנין, שהרי נפחן של התאנים הלחות גדול מנפחן של הגרוגרות).","ומעתה יש לברר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר, \u0005אם אומר אתה]\u0006 כי \u0003לכמות שהן\u0004 (שהיו בעבר) \u0003משערינן\u0004 \u0005[משערים אנו],\u0006 אם כן אף הגרוגרות התחייבו במידת תרומות ומעשרות כזמן שהיו הן עצמן לחות ונפחן גדול יותר — \u0003שפיר\u0004 \u0005[יפה,\u0006 ברור\u0005]\u0006 הוא דין זה ששנינו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי ל\u0003כמות שהן\u0004 עתה אנו משערים, והרי עתה הרי הגרוגרות נפחן קטן משל התאנים הלחות, ואנו מפרישים תרומות ומעשרות יותר מאשר עשירית נפחן זה, \u0003הוה ליה\u0004 \u0005[הריהו נהיה]\u0006 בכך בכלל ה\u0003מרבה במעשרות,\u0004","\u0003ותנן\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]\u0006 כי זה \u0003המרבה\u0004 (המפריש יותר מן הראוי) \u0003במעשרות\u0004 — \u0003פירותיו\u0004 אמנם \u0003מתוקנים\u0004 ומותרים באכילה, אבל \u0003מעשרותיו מקולקלין,\u0004 שכן בתוך המעשר הניתן יש גם חלק (זה שניתן מעבר לנדרש) שאינו מעשר, והריהו איפוא בכלל איסור טבל (פרי שלא הופרשו ממנו מעשרותיו)!","ודוחים את הראיה: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה מבקש להוכיח מכאן, כי \u0003לכמות שהן\u0004 היו בעבר אנו משערים, אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף]\u0006 דברי אותה ברייתא: אין מפרישים מן ה\u0003גרוגרות על התאנים\u0004 אלא \u0003במדה\u0004 (של נפח), שיטול מן הגרוגרות עשירית נפחן של התאנים, ולא במנין (שיפריש מספר גרוגרות שהוא עשירית מספרן של התאנים), שהרי בכך ממעט הוא את נתינתו.","ונדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח,\u0006 זה מובן, \u0005אם אומר אתה]\u0006 כי \u0003כמות שהן\u0004 עתה משערים אנו — \u0003שפיר\u0004 \u0005[יפה,\u0006 ברור\u0005]\u0006 הוא דין זה ששנינו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003לכמות שהן\u0004 מתחילתן אנו משערים, כשהיו גרוגרות אלה תאנים לחות, אם כן די היה במספר קטן יותר של תאנים לשמש כמעשר, ועתה בהיותן גרוגרות מפריש הוא מספר רב יותר, והרי בכך נמצא ש\u0003מרבה במעשרות הוא!\u0004 הרי שאין להביא ראיה מברייתא זו, לא לדעה שמשערים כמו שהן עכשיו ולא לדעה שמשערים כמות שהיו.","\u0003אלא\u0004 מאחר שסותרים תחילתה וסופה זו את זו, יש לומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא זו אין מדובר בכלל המעשרות, שיש להם שיעור מוגדר להפרשתם, אלא \u0003בתרומה גדולה\u0004 (שאין שיעור מוגדר להפרשתה) בלבד \u0003עסקינן\u0004 \u0005[עוסקים אנו].\u0006 \u0003ו\u0004מעתה יובנו דברי הברייתא: ב\u0003רישא\u0004 \u0005[ראשה,\u0006 בתחילתה\u0005]\u0006 מדובר שרוצה הוא לתרום \u0003בעין יפה.\u0004 שמדין תורה די בחיטה אחת הניתנת כתרומה גדולה על כל התבואה, ותיקנו חכמים שתינתן התרומה אם כאחד מששים (\"עין רעה\"), אם כאחד מחמשים (\"עין בינונית\"), ואם כאחד מארבעים (\"עין יפה\"), ועל כן הריהו תורם באופן שמוסיף על המדה. \u0003ו\u0004כן ב\u0003סיפא\u0004 \u0005[סופה]\u0006 בתורם \u0003בעין יפה היא\u0004 עוסקת, שמוסיף על המדה.","ומקשים על הסבר זה של הברייתא: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר בה בתרומה גדולה, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה],\u0006 \u0003אמר ר' אלעזר בר' יוסי: אבא\u0004 ר' יוסי \u0003היה נוטל\u0004 (מפריש) \u0003עשר גרוגרות\u0004 יבשות \u0003ש\u0004נמצאות \u0003במקצוע\u0004 (הכלי בו ניתנות הגרוגרות. וראה \"החיים\"), \u0003על תשעים\u0004 תאנים לחות \u0003ש\u0004נמצאות \u0003בכלכלה\u0004 (סל). \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר בברייתא זו \u0003בתרומה גדולה, עשר מאי עבידתיה\u0004 \u0005[מה מעשהו,\u0006 עניינן\u0005]?\u0006 שהרי אין מפרישים עשירית לתרומה גדולה.","\u0003אלא\u0004 יש לומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא זו, \u0003בתרומת מעשר\u0004 שנותן הלוי לכהן מהמעשר ראשון שניתן לו \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאכן שיעורה הוא אחד מעשרה, \u0003ו\u0004כשיטת \u0003אבא אלעזר בן גומל הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא אלעזר בן גומל אומר:\u0004 נאמר בדין תרומת המעשר \"ואל הלויים תדבר ואמרת אליהם כי תקחו מאת בני ישראל את המעשר אשר נתתי לכם בנחלתכם והרמותם ממנו תרומת ה' מעשר מן המעשר. \u0003ונחשב לכם תרומתכם\u0004 כדגן מן הגורן וכמלאה מן היקב\" (במדבר יח, כו— כז) — \u0003בשתי תרומות\u0004 הניתנות לכהנים \u0003הכתוב מדבר, אחת\u0004 היא \u0003תרומה גדולה\u0004 הניתנת מישראל לכהן, השווה כתוב זה את תרומת המעשר אליה (\"ונחשב לכם תרומתכם כדגן מן הגורן\"), \u0003ואחת\u0004 היא \u0003תרומת מעשר\u0004 הניתנת מהלוי לכהן, האמורה בכתוב במפורש.","ללמדנו כי \u0003כשם שתרומה גדולה\u0004 שאין לה שיעור מסוים מן התורה \u0003ניטלת באומד\u0004 (בהערכה בלא מדידת שיעור מדוייק) \u0003ובמחשבה,\u0004 ודי שקובע בדעתו שיהא חלק זה לתרומה, \u0003כך תרומת מעשר\u0004 אינה צריכה להימדד במדוייק, והריהי \u0003ניטלת באומד\u0004"],["\u0003ובמחשבה.\u0004 ועוד למדים מהשוואתן של שתי תרומות אלה: \u0003מה תרומה גדולה\u0004 השיעור הראוי לנתינתה הוא \u0003בעין יפה, אף תרומת מעשר\u0004 ראוי שתהיה זו הפרשה \u0003בעין יפה.\u0004 ומשום כך אף המפריש תרומת מעשר מתאנים לחות על גרוגרות, ראוי שיפריש בעין יפה (כגון עשר תאנים לחות על תשעים גרוגרות), וכאילו היה נפחן של הגרוגרות כנפחן של תאנים לחות.","ומדייקים: \u0003ומינה\u0004 \u0005[וממנה]\u0006 מדברי ר' אלעזר בר' יוסי שבברייתא אפשר להביא ראיה לשיטה האומרת כי לכמות שהן היו בעבר אנו משערים. שכן \u0003אמר ר' אלעזר בר ר' יוסי: אבא\u0004 (ר' יוסי) \u0003היה נוטל עשר גרוגרות ש\u0004נתונות \u0003במקצוע\u0004 ומפרישן כתרומת מעשר \u0003על תשעים\u0004 תאנים לחות \u0003ש\u0004נתונות \u0003בכלכלה.\u0004 ויש לדון בדבריו: \u0003אי אמרת בשלמא\u0004 \u0005[נניח,\u0006 מובנים הדברים, \u0005אם אומר אתה]\u0006 כי \u0003לכמות שהן\u0004 היו בעבר \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 בקביעת השיעורים — \u0003שפיר\u0004 \u0005[יפה],\u0006 שנראה שר' יוסי מתייחס אל הגרוגרות המופרשות למעשר, כאילו הן תאנים לחות כפי שהיו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי יש לקבוע את השיעור \u0003כמות שהן\u0004 עתה, והרי זה המפריש עשר תאנים יבשות (גרוגרות) על תשעים תאנים לחות \u0003בציר להו\u0004 \u0005[מפחית אותן]\u0006 משיעורן, שכן נפחן של עשר תאנים יבשות הריהו פחות מנפחן של עשר תאנים לחות. אלא ודאי שבכל דבר הולכים אחר השיעור שהיה בעבר!","ומשיבים: אין ללמוד \u0003מגרוגרות לשאר דברים, שהרי\u0004 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשמו של \u0003ר' אלעזר\u0004 את הסברם של דברים אלה: \u0003שאני\u0004 \u0005[שונה,\u0006 נבדל\u0005]\u0006 הוא דינם של \u0003גרוגרות\u0004 מדינם של שאר דברים שנשתנה שיעורם, \u0003הואיל ויכול\u0004 לשוב \u0003לשולקן\u0004 (במים) \u0003ולהחזירן לכמות שהן\u0004 היו לפני כן, בהיותן תאנים לחות. ולכן מפרישים מהן על התאנים הלחות בשיעור כפי שהן עתה, ואולם אין ללמוד מכאן לשאר דברים.","ודנים עוד בדין המעשר מתאנים על הגרוגרות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תורמין\u0004 במנין, מן ה\u0003תאנים\u0004 הלחות \u0003על הגרוגרות\u0004 היבשות. שנוטלים למעשר עשר תאנים לחות על תשעים גרוגרות יבשות. ואין דין זה אמור אלא \u0003במקום ש\u0004בו \u0003רגילין לעשות\u0004 מ\u0003תאנים גרוגרות,\u0004 ויכול הכהן שקיבל תאנים לעשותן גרוגרות. \u0003ו\u0004אולם \u0003לא\u0004 תורמים מן ה\u0003גרוגרות על\u0004 ה\u0003תאנים\u0004 הלחות, \u0003ואפילו במקום שרגילין לעשות\u0004 מ\u0003תאנים גרוגרות.\u0004 ודנים בדברים הללו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו כי \u0003תורמין תאנים על הגרוגרות במקום שרגילין לעשות תאנים גרוגרות.\u0004 ויש איפוא לדייק בדבריו: דווקא \u0003במקום שרגילין\u0004 לעשות גרוגרות — \u0003אין\u0004 \u0005[כן]\u0006 יתרום מתאנים על גרוגרות. אבל \u0003במקום שאין רגילין\u0004 לעשות גרוגרות — \u0003לא\u0004 יתרום מהתאנים על הגרוגרות, שהרי אין המעשר מתקיים, שעלולות התאנים להתקלקל, עד שתינתנה לכהן.","ויש לברר: \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק\u0006 מקרה זה\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר בזמן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כהן\u0004 לפנינו, ויכול התורם לתת לו מייד — אפילו ב\u0003מקום שאינו רגיל\u0004 לעשות גרוגרות, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יתרום מהתאנים על הגרוגרות, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 כי בכל \u0003מקום שיש כהן\u0004 לפנינו, בעל הפירות \u0003תורם מן היפה\u0004 ואף כאן התאנים הלחות יפות ומשובחות מן הגרוגרות אף שהגרוגרות מתקיימות יותר!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כהן\u0004 לפנינו, ויעבור זמן עד שימצא כהן לתת לו, ועלולות התאנים להתקלקל בינתיים, ואם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 עתה את \u0005סוף]\u0006 אותה ברייתא ששנינו: \u0003ולא\u0004 תורמים מן ה\u0003גרוגרות על התאנים, ואפילו במקום שרגיל לעשות תאנים גרוגרות. ואי\u0004 \u0005[ואם]\u0006 אכן מדובר בזמן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כהן\u0004 לפנינו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 תורמים מן הגרוגרות המתקיימות לאורך זמן, ומעדיפים לתרום מהתאנים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 כי ב\u0003מקום שאין כהן\u0004 לפנינו — \u0003תורם\u0004 בעל \u0003הפירות\u0004 \u0003מן\u0004 הדבר \u0003המתקיים\u0004 ולא מן היפה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כהן\u0004 לפנינו.","והדבר תמוה, שכן לפי זה \u0003רישא\u0004 \u0005[תחילת]\u0006 הברייתא מדברת במקרה \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כהן\u0004 לפנינו, ואילו \u0003סיפא\u0004 \u0005[סוף]\u0006 הברייתא \u0003—\u0004 במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כהן\u0004 לפנינו! ומשיבים: \u0003אין\u0004 \u0005[\u0006אכן \u0005כן]\u0006 הוא, \u0003רישא\u0004 \u0005[תחילת]\u0006 הברייתא מדברת במקרה \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003כהן\u0004 לפנינו, ואילו \u0003סיפא\u0004 \u0005[סוף]\u0006 הברייתא \u0003—\u0004 במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כהן\u0004 לפנינו.","בעקבות דברים אלה \u0003אמר רב פפא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 מתירוץ זה לענין דרך הלימוד הראויה, כי כאשר ישנה סתירה בתוך דברי המשנה, \u0003דחקינן ומוקמינן מתניתין בתרי טעמי\u0004 \u0005[דוחקים ומעמידים אנו\u0006 אותה \u0005משנה\u0006 כי עוסקת היא \u0005בשני טעמים,\u0006 מצבים שונים\u0003],\u0004 \u0003ולא מוקמינן בתרי תנאי\u0004 \u0005[ואין אנו מעמידים\u0006 אותה שמדובר בה \u0005ב\u0006שיטותיהם של \u0005שני תנאים]\u0006 החולקים זה על זה.","\u0003כל המנחות\u0004 הבאות מצה, \u0003נילושות ב\u0004מים, שכך תיאפה העיסה יפה, שהרי אין בה אלא שמן מועט. ויהיו אלה מים \u0003פושרין\u0004 (שאינם חמים ואינם קרים). \u0003ו\u0004עושה המנחות \u0003משמרן שלא יחמיצו\u0004 בזמן שהוא לש ועורך אותן. \u0003ואם החמיצו\u0004 עיסת המנחות הבאות מצה, או אפילו רק \u0003שיריה\u0004 (שאריותיה) של המנחה, לאחר שנקמצה, שנאכלות על ידי הכהנים — \u0003עובר\u0004 על כך \u0003ב\u0004מצות \u0003לא תעשה,\u0004 שלא תחמיץ — \u0003שנאמר \"כל המנחה אשר תקריבו לה' לא תעשה חמץ\u0004 כי כל שאור... לא תקטירו ממנו אשה לה' \" (ויקרא ב, יא). \u0003ו\u0004העושה מנחה והחמיצה \u0003חייב\u0004 מלקות הן \u0003על לישתה\u0004 של עיסת חמץ זו, \u0003ו\u0004הן \u0003על עריכתה\u0004 (שיטוח וגלגול הבצק) \u0003ו\u0004הן \u0003על אפייתה\u0004 של מנחה זו.","שנינו במשנתנו שעושה המנחה בחמץ עובר על איסור לא תעשה אף על שאריותיה. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין\u0006 המקור \u0005לדברים הללו],\u0006 שאף על החמצת השיריים הריהו עובר, ולא על המנחה בלבד? \u0003אמר ריש לקיש,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תאפה חמץ חלקם\u0004 נתתי אותה מאשי\" (שם ו, י) — לומר: \u0003אפילו חלקם\u0004 של המנחות, אותם שאריות שאוכלים הכהנים, אף היא \u0003לא תאפה חמץ.\u0004","ושואלים: \u0003ו\u0004האם \u0003האי\u0004 \u0005[זה]\u0006 הפסוק \u0003להכי\u0004 \u0005[ל\u0006למדנו \u0005כך],\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 והרי \u0003האי\u0004 \u0005[זה]\u0006 הפסוק \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004דרשה אחרת, \u0003כדתניא\u0004 \u0005[כמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לא\u0004"],["\u0003תאפה חמץ\"\u0004 (ויקרא ו, י), \u0003מה תלמוד לומר\u0004 (בא ללמדנו), \u0003והלא כבר נאמר\u0004 לפני כן \"כל המנחה אשר תקריבו לה' \u0003לא תעשה חמץ\u0004 כי כל שאור... לא תקטירו ממנו אשה לה' \" (שם ב, יא), וממנו למדים אנו דין זה. אלא הכתוב \"לא תאפה\" נדרש לענין אחר: \u0003לפי שנאמר\u0004 קודם איסור חימוץ המנחה בלשון כוללת, \u0003\"לא תעשה חמץ\",\u0004 שאין בה ציון מעשה מוגדר באותה עשייה, \u0003יכול\u0004 (היה אפשר לומר) שהמחמץ את המנחה \u0003לא יהא חייב\u0004 כעונש \u0003אלא\u0004 סדרת מלקות \u0003אחת על כולם,\u0004 על כל עשיותיו (לישת הבצק, עריכתו, ואפייתו). לכך \u0003תלמוד לומר\u0004 (בא ללמדנו) הכתוב הנוסף \u0003\"לא תאפה\u0004 חמץ\". שחייב המחמץ מלקות על כל עשיה לעצמה.","וכך למדנו: שהרי מעשה \u0003ה\u0004\u0003אפייה בכלל\u0004 כל המלאכות של עשיית המנחה \u0003היתה,\u0004 ו\u0003למה יצאת\u0004 (יצאה) מלאכה זו מכללן, שציינה הכתוב בייחוד? — \u0003להקיש\u0004 (להשוות) \u0003אליה\u0004 את שאר העשיות ולומר: \u0003מה\u0004 מלאכת \u0003אפייה מיוחדת שהיא\u0004 \u0003מעשה יחידי\u0004 שלם, \u0003ו\u0004משום כך \u0003חייבין עליה\u0004 מלקות, על עשייתה בחימוץ, \u0003בפני עצמה.\u0004 \u0003אף אני אביא\u0004 (ארבה) את המעשים הנוספים שבמלאכת המנחה, את \u0003לישתה ו\u0004את \u0003עריכתה\u0004 שאם עשאם בחימוץ חייבים על כל אחת מהן לעצמה.","\u0003ו\u0004הוא הדין ב\u0003כל מעשה יחידי\u0004 (נפרד ומיוחד) אחר \u0003שבה,\u0004 בעשיית המנחה, ו\u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את מעשה ה\u0003קיטוף\u0004 (החלקת פני העיסה במים) אף שאינו מעשה חשוב, \u0003שהוא מעשה יחידי וחייבין עליה\u0004 מלקות \u0003בפני עצמה.\u0004 הרי שמפסוק זה אנו למדים דבר אחר, ומנין לנו שחייבים על חימוצם של השיריים?","ומשיבים: אכן הכתוב \"לא תאפה\" נדרש לענין אחר, ואולם \u0003אנן\u0004 \u0005[אנו]\u0006 לא למדנו זאת מחלק זה של הפסוק, אלא \u0003מ\u0004מה שנאמר \"לא תאפה חמץ \u0003חלקם\" קאמרינן\u0004 \u0005[אומרים,\u0006 לומדים \u0005אנו]\u0006 הלכה זו, שכך אנו דורשים את הכתוב: לא תאפה חמץ אף את \"חלקם\" של הכהנים במנחה, הם השיריים הנאכלים על ידם.","\u0003ו\u0004\u0005שואלים: עתה שהסברנו שהכתוב \"חלקם\" בא ללמדנו\u0006 \u0003איסור חימוץ בשיירי המנחה,\u0004 \u0003אימא כוליה\u0004 \u0005[אמור\u0006 אם כן ש\u0005כולו],\u0006 כל התוספת הזו בפסוק, רק \u0003להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ואין לנו איפוא מקור שחייבים מלקות בנפרד על כל אחד מפרטי עשיית המנחה בחימוץ!","ומשיבים: אין לומר שבאה תוספת זו רק ללמדנו את האיסור בחימוץ שיירי המנחה, ש\u0003אם כן, לכתוב\u0004 \u0005[שיכתוב]\u0006 המקרא בסדר הזה \u0003\"חלקם לא תאפה חמץ\", מאי\u0004 \u0005[מה,\u0006 מדוע\u0005]\u0006 אמר הכתוב כסדר זה \u0003\"לא תאפה חמץ חלקם\"? שמעת מינה תרתי\u0004 \u0005[שמעת,\u0006 למדת, \u0005ממנה שני\u0006 דברים\u0005].\u0006 האיסור של עשיית שיירי המנחה בחמץ, וחיוב מלקות נפרד על כל עשיה ועשיה בחימוץ.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005תאמר]\u0006 כך: אכן מלאכת ה\u0003אפייה\u0004 מיוחדת היא, שכן \u0003פרט בה\u0004 (ציינה אותה כשלעצמה) \u0003רחמנא\u0004 \u0005[הכתוב],\u0006 ולכך \u0003ליחייב חדא\u0004 \u0005[יתחייב\u0006 עליה סדרת מלקות \u0005אחת],\u0006 אבל \u0003אינך\u0004 \u0005[אלה]\u0006 המלאכות האחרות, לישה ועריכה, שלא צוינו במפורט בכתוב \u0003ליחייב חדא אכולהו\u0004 \u0005[יתחייב\u0006 על עשייתן סדרת מלקות \u0005אחת על כולן]!\u0006 ומשיבים: אינך יכול לומר כן, שהרי חייבים מלקות על מלאכה ומלאכה כשלעצמה \u0003משום דהוה\u0004 \u0005[ש\u0006ציון מלאכת אפיה לעצמה \u0005הינו]\u0006 ככל \u0003דבר\u0004 אחר במקרא \u0003שהיה בכלל\u0004 הדברים הדומים לו \u0003ויצא מן הכלל,\u0004 לדון בו בנפרד, כדי \u0003ללמד\u0004 שכלל הוא ב\"מידות שהתורה נדרשת בהן\". \u0003לא ללמד על עצמו\u0004 בלבד \u0003יצא\u0004 מן הכלל, \u0003אלא ללמד על הכלל כולו יצא.\u0004 ואף מלאכת אפיה יצאה מכלל מלאכות, ללמד שחייבים מלקות אף על כל אחת מעבודות המנחה.","ומקשים עוד, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: הכתוב \u0003\"לא תעשה\u0004 חמץ\" — הרי זה \u0003כלל,\u0004 שהרי אין מצויינות בו מלאכות מסויימות, ואילו הכתוב \u0003\"לא תאפה\u0004 חמץ\" — הריהו \u0003פרט,\u0004 שהרי מצויינת בו האפייה שהיא מלאכה מסויימת, וכלל הוא כי כאשר לפנינו מקרא שתוכנו \u0003כלל ו\u0004לאחריו מקרא שתוכנו \u0003פרט\u0004 — \u0003אין בכלל אלא מה שבפרט.\u0004 ומעתה אף בענייננו נאמר, כי המקרא שהוא כלל (\"לא תעשה חמץ\") \u0003אפייה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 כלול בו, ואילו \u0003מידי אחרינא\u0004 \u0005[דבר אחר],\u0006 כגון לישה ועריכה — \u0003לא\u0004 כלול בו!","\u0003אמר ר' אפטוריקי\u0004 בתשובה לשאלה זו: אין שני הפסוקים הללו נחשבים \"כלל ופרט\", \u0003משום דהוי\u0004 \u0005[שהינו]\u0006 \u0003כלל ופרט\u0004 שאינם סמוכים זה לזה אלא \u0003המרוחקין זה מזה,\u0004 שהרי הכתוב \"לא תעשה חמץ\" נכתב בפרשת ויקרא (פרק ב) ואילו הכתוב \"לא תאפה חמץ\" נכתב בפרשת צו (פרק ו). \u0003וכל כלל ופרט המרוחקין זה מזה\u0004 — \u0003אין דנין אותן ב\u0004מידת \u0003\"כלל ופרט\".\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על קביעה זו של ר' אפטוריקי \u0003רב אדא בר אהבה, ואמרי לה כדי\u0004 \u0005[ויש אומרים אותה סתם,\u0006 בלי שם אומרה\u0005]\u0006 : \u0003ו\u0004האם \u0003כלל\u0004 \u0003ופרט המרוחקין זה מזה\u0004 — \u0003אין דנין אותן ב\u0004מידת \u0003\"כלל ופרט\"? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 ממה שנאמר בשעיר חטאת נשיא \u0003\"ושחט אתו במקום אשר ישחט העלה לפני ה' חטאת הוא\"\u0004 (שם ד, כד) למדים אנו היכן מקום שחיטתו, שהרי \u0003היכן\u0004 ה\u0003עולה נשחטת?\u0004 — \u0003בצפון\u0004 העזרה, כאמור \"ושחט אותו על ירך המזבח צפונה לפני ה' \" (ויקרא א, יא), \u0003אף זה\u0004 השעיר מקום שחיטתו הוא \u0003בצפון\u0004 העזרה.","ויש לשאול: \u0003וכי אנו מכאן למידין\u0004 דין זה בשחיטת שעיר הנשיא, \u0003והלא כבר נאמר\u0004 בקרבנות החטאת: \u0003\"במקום אשר תשחט העלה תשחט החטאת\"\u0004 (שם ו, יח), ובכלל החטאת אף שעיר הנשיא שהוא חטאת! \u0003הא\u0004 \u0005[הרי]\u0006 יש לומר: \u0003למה\u0004 פסוק \u0003זה יצא\u0004 מכלל החטאות, לציין את מקום שחיטתו? — כדי \u0003לקובעו\u0004 בהחלט ששחיטתו אך בצפון העזרה, \u0003שאם לא שחט אותו בצפון\u0004 — \u0003פסלו,\u0004 ואין זה רק לכתחילה.","ודנה הברייתא עוד בדבר: \u0003אתה אומר\u0004 כי \u0003לכך\u0004 (ללמדנו פסול שחיטה שלא בצפון בשעיר נשיא) \u0003יצאת\u0004 (יצא) זה הכתוב, \u0003או\u0004 אולי \u0003אינו\u0004 בא מקרא זה \u0003אלא\u0004 ללמדנו \u0003ש\u0004דווקא \u0003זה\u0004 (חטאת שעיר נשיא) הוא ש\u0003טעון\u0004 (חייב) בשחיטה ב\u0003צפון ואין\u0004 קרבן חטאת \u0003אחר טעון צפון,\u0004 ואף הכתוב \"במקום אשר תשחט העולה תשחט החטאת\" אין עניינו כל החטאות אלא חטאת נשיא בלבד?! לכך \u0003תלמוד לומר\u0004 (מלמדנו) כתוב שלישי, בו נאמר \u0003\"ושחט את החטאת במקום אשר ישחט את העלה\"\u0004 (שם ד, כט), והרי כתוב \u0003זה בנה\u0004 (בנין) \u0003אב לכל\u0004 ה\u0003חטאות שטעונות\u0004 כולן שחיטה ב\u0003צפון.\u0004","ויש לדייק בדברי ברייתא זו: \u0003טעמא\u0004 \u0005[הטעם,\u0006 המקור\u0005]\u0006 שכל החטאות נשחטות בצפון, הוא ש\u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"ושחט את החטאת\u0004 במקום העולה\", \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כן],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003ש\u0004רק \u0003זה\u0004 שעיר נשיא הוא ש\u0003טעון\u0004 שחיטה ב\u0003צפון ואין\u0004 קרבן חטאת \u0003אחר טעון\u0004 שחיטה ב\u0003צפון.\u0004 ונדון בדבר: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 מדוע נאמר כך, אף שפשוטו של הפסוק \"במקום אשר תשחט העולה תשחט החטאת\" \u0005עוסק בכל החטאות?\u0006","\u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דהוה\u0004 \u0005[שהינו]\u0006 מקרא שעניינו \u0003כלל\u0004 (שהרי מדבר על כלל החטאות) \u0003ו\u0004אילו הפסוק \"ושחט אותו במקום אשר ישחט את העולה\" עניינו \u0003פרט\u0004 (\"אותו\"), \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003מרוחקין\u0004 שני מקראות אלה \u0003זה מזה דנין אותן\u0004 בכל זאת \u0003ב\"כלל ופרט\".\u0004 ויש איפוא מקום לומר שאין בכלל אלא מה שבפרט, ואין הדברים אמורים אלא בחטאת נשיא בלבד. והרי זו איפוא קושיה על הסברו של ר' אפטוריקי!","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על שאלת רב אדא בר אהבה\u0005]\u0006 \u0003רב אשי:\u0004 וכי \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"כלל ופרט\" הוא?!\u0004 והלא אין זה אלא \u0003פרט וכלל הוא,\u0004 שהרי הכתוב \"ושחט אותו במקום אשר ישחט את העולה\" אמור תחילה בתורה (פרק ד, כד), ואילו הכתוב \"במקום אשר תשחט העולה תשחט החטאת\" אמור אחריו (פרק ו, יח), \u0003ו\u0004לפי כללי הלימוד של מדרש ההלכה, ב\"פרט וכלל\", \u0003נעשה\u0004 ה\u0003כלל מוסיף על הפרט, ואיתרבי להו\u0004 \u0005[והתרבו להם]\u0006 אם כן \u0003כל מילי\u0004 \u0005[\u0006\u0003הדברים]!\u0004","ואין זו קושיה על ר' אפטוריקי \u0003אלא\u0004 בדיוק דברי הברייתא, וכך הוא הסבר הדברים: ה\u0003תנא\u0004 שבברייתא, המלה \u0003\"אתו\"\u0004 האמורה בכתוב (\"ושחט אותו\"), שהיא לשון מיעוט \u0003קא קשיא ליה\u0004 \u0005[היא שהוקשתה לו],\u0006 מה באה למעט. \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003או אינו אלא\u0004 בא הכתוב ללמד רק \u0003ש\u0004דווקא קרבן חטאת \u0003זה\u0004 הוא ש\u0003טעון\u0004 שחיטה ב\u0003צפון ואין\u0004 קרבן חטאת \u0003אחר טעון\u0004 שחיטה ב\u0003צפון,\u0004 שכן \u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"אתו\"\u0004 שהוא לשון מיעוט. לכך בא הכתוב הנוסף \"ושחט את החטאת במקום העולה\" ללמדנו שנוהג דין זה בכל החטאות.","ומעתה נפנים לבירור הדבר הנלמד מהמלה \"אותו\" (\"ושחט אותו\") שנאמרה בחטאת הנשיא. ושואלים: \u0003והשתא דנפקא ליה\u0004 \u0005[ועכשיו שיוצא לו,\u0006 שנלמד\u0005]\u0006 דין זה שכל החטאות שחיטתן בצפון \u0003מ\u0004מה שנאמר \u0003\"ושחט את החטאת\u0004 במקום העולה\", אם כן המלה \u0003\"אתו\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 היא באה? ומשיבים: \u0003אמור כי\u0004 \u0003למעוטי\u0004 \u0005[למעט]\u0006 את הדברים הבאים \u0003(נחשון. ושחט. עוף. בפסח.\u0004 שהם סימן להלכות שונות שתבוארנה) בא.","וכך הוא נדרש: דווקא \u0003\"אותו\",\u0004 קרבן נשיא שחטא, הוא שנשחט \u0003בצפון, ואין\u0004 קרבן חטאת כ\u0003שעיר\u0004 שהובא על ידי \u0003נחשון\u0004 בן עמינדב נשיא שבט יהודה בחנוכת המשכן, ושל שאר נשיאי שבטי ישראל לחנוכת המשכן חייבים להישחט \u0003בצפון.\u0004","וצריך לדרוש דין זה מן הכתוב \"אותו\" אף שהוא קדשי שעה ולא באו לכפרה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתרבי\u0004 \u0005[והתרבה]\u0006 שעיר הנשיא בחנוכת המשכן \u0003לענין\u0004 דין \u0003סמיכה\u0004 הנוהגת בו כבשאר החטאות, היה איפוא מקום לומר כי \u0003ליתרבי נמי\u0004 \u0005[יתרבה גם כן]\u0006 \u0003לענין\u0004 דין שחיטתו ב\u0003צפון\u0004 כבשאר החטאות. לכן בא כתוב זה \"אותו\" ו\u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאין שעיר הנשיא בחנוכת המזבח טעון שחיטה בצפון.","ושואלים: \u0003וסמיכה גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 ששעיר \u0005נחשון חייב בה? ומשיבים:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 נאמר בקרבן שעיר נשיא \"...והביא את קרבנו שעיר עזים זכר תמים. \u0003וסמך ידו על ראש השעיר\"\u0004 (שם ד, כג— כד), והרי זה מקרא יתר, שהרי די היה לכתוב \"וסמך ידו על ראשו\" — אלא בא הוא \u0003לרבות\u0004 אף את קרבן \u0003שעיר נחשון\u0004 בן עמינדב הנשיא, ושאר נשיאי ישראל בחנוכת המשכן \u0003ל\u0004דין ה\u0003סמיכה\u0004 בהם. אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004"],["לא בא מקרא יתר זה (\"השעיר\") אלא \u0003לרבות\u0004 את קרבנות \u0003שעירי עבודה זרה\u0004 של ציבור (שטעה ועבד עבודה זרה \u0003בהוראת בית דין)\u0004 \u0003ל\u0004דין ה\u0003סמיכה\u0004 הנוהג בהם.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על תשובה זו\u0005]\u0006 \u0003רבינא:\u0004 \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה\u0004 הסבור שנוהג דין סמיכה בשעיר נחשון, היה איפוא מקום לומר שינהג בו אף דין שחיטת צפון כבשאר החטאות, ולכך בא המיעוט \"אותו\" ללמדנו שאין בו דין שחיטת צפון. ואולם \u0003ל\u0004דעת \u0003ר' שמעון\u0004 הסבור שבשעיר נחשון אין דין סמיכה, אין איפוא מקום לחשוב שינהג בו דין שחיטה בצפון, ומעתה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בדרשת המיעוט הנלמדת מהמלה היתרה \"אותו\"?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 החכם \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא\u0004 בשאלה על דבריו אלה: והרי \u0003ל\u0004דעת \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 יש לומר \u0003מאי דאיתרבי\u0004 \u0005[מה שהתרבה]\u0006 כגון סמיכה — \u0003איתרבי\u0004 \u0005[התרבה],\u0006 ואולם \u0003מאי\u0004 \u0005דלא איתרבי\u0006 \u0005[מה שלא התרבה],\u0006 כגון שחיטה בצפון — \u0003לא איתרבי\u0004 \u0005[לא ה\u0006\u0003תרבה],\u0004 ואין צורך במיעוט יתר ולשם מה המלה \"אותו\"?!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003אי לא מעטיה קרא\u0004 \u0005[אם לא היה ממעט אותו המקרא]\u0006 \u0003הוה אמינא תיתי\u0004 \u0005[הייתי אומר\u0006 ש\u0005תילמד]\u0006 \u0003ב\u0004דרך הלימוד של \u0003\"בנין אב\"\u0004 (דימוי ממקרים דומים הכתובים בתורה) משאר חטאות שכולן נשחטות בצפון, אם כן \u0003סמיכה גופה\u0004 \u0005[עצמה]\u0006 \u0003לישתוק קרא מיניה ותיתי\u0004 \u0005[שישתוק הפסוק ממנה\u0006 ולא ידבר בה \u0005ותילמד]\u0006 \u0003בבנין אב\u0004 משאר חטאות! \u0003אלא\u0004 קרבן שנעשה ל\u0003שעה\u0004 כגון שעיר נחשון \u0003מ\u0004דבר שנעשה ל\u0003דורות לא ילפינן\u0004 \u0005[לא למדים אנו],\u0006 אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר אותו נימוק: \u0003שעה מדורות לא ילפינן\u0004 \u0005[לא למדים אנו].\u0006","וממשיכים את הדיון, \u0003אלא\u0004 הכתוב \"ושחט אותו\" מה הוא בא למעט? לומר: \u0003אותו\u0004 השעיר דווקא הוא ש\u0003טעון\u0004 (חייב) שתהא שחיטתו ב\u0003צפון, ו\u0004אולם \u0003אין השוחט\u0004 את הקרבן חייב שיהיה אף הוא \u0003עומד בצפון,\u0004 שיכול אף לעמוד בדרום ולשחוט את השעיר העומד בצפון (באמצעות סכין ארוכה).","ומקשים: והרי דינו של השוחט \u0003מ\u0004דבריו של \u0003ר' אחייה נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אחייה אומר\u0004 על הנאמר בשחיטתו של קרבן עולה \u0003\"ושחט אתו על ירך המזבח צפונה\"\u0004 (ויקרא א, יא): \u0003מה תלמוד לומר\u0004 (מלמדנו) \"אותו\" שבפסוק זה?","\u0003לפי שמצינו\u0004 (מצאנו) \u0003ב\u0004דינו של הכהן ה\u0003מקבל\u0004 את דם הקרבן \u0003ש\u0004חייב שיהיה \u0003עמד בצפון ומקבל בצפון, ואם עומד בדרום וקיבל בצפון\u0004 — \u0003פסול,\u0004 ומעתה \u0003יכול\u0004 אדם להסביר ש\u0003אף\u0004 בדינו של \u0003זה\u0004 הכהן השוחט את הקרבן \u0003כן\u0004 הוא הדין. לכך \u0003תלמוד לומר: \"אתו\u0004 על ירך המזבח צפונה\" — להשמיענו כי דווקא \u0003אותו\u0004 (הקרבן עצמו) הוא שצריך להיות \u0003בצפון\u0004 בשחיטתו, \u0003ולא השוחט צריך להיות עומד בצפון!\u0004","\u0003אלא\u0004 כך צריך ללמוד מ\"אותו\" האמור בשעיר נשיא: דווקא \u0003אותו\u0004 שוחטים \u0003בצפון, ואין\u0004 מליקתו \u0003של\u0004 \u0003בן עוף\u0004 חייבת להיעשות \u0003בצפון.\u0004 שכן שנינו בברייתא: נאמר בעולה הבאה מן הצאן \"ושחט אותו על ירך המזבח צפונה\" ולכאורה \"אותו\" האמור בכתוב זה מיותר, אלא \u0003סלקא דעתך אמינא ליתי\u0004 \u0005[יעלה על דעתך לומר\u0006 ש\u0005יבוא,\u0006 שילמד\u0005]\u0006 דינו של קרבן בן עוף \u0003בקל וחומר מ\u0004דינו של קרבן \u0003בן צאן,\u0004 ובאופן זה: \u0003ומה בן צאן\u0004 הקל בדינו, \u0003ש\u0004הרי \u0003לא קבע לו\u0004 (חייבו) הכתוב שדווקא \u0003כהן\u0004 הוא השוחטו, שהרי כל אדם רשאי לשחוט אותו — בכל זאת \u0003קבע לו\u0004 (חייבו) הכתוב שתהא שחיטתו ב\u0003צפון.\u0004 \u0003בן עוף,\u0004 החמור, \u0003ש\u0004הרי \u0003קבע לו כהן\u0004 למליקתו, שאין המליקה נעשית אלא על ידי כהן בלבד — \u0003אינו דין שנקבע לו צפון\u0004 במליקתו. לכך בא הכתוב \"אותו\" למעט את מליקת עוף, שאינה חייבת להיות בצפון.","ודוחים: אין ללמוד מקל וחומר זה, שכן אפשר לפורכו ולומר: \u0003מה לבן צאן\u0004 שיש בו צד חמור מבן עוף, \u0003שכן קבע לו\u0004 (חייבו הכתוב) ב\u0003כלי\u0004 לשחיטתו, סכין, ולכן גם החמירו בו שתהא שחיטתו דווקא בצפון, ואולם בן עוף דינו קל שנמלק בלא כלי, בציפורנו של הכהן ומשום כך אף לא החמירו בו שתהא מליקתו בצפון, וממילא נשאר \"אותו\" מיותר.","\u0003אלא\u0004 כך יש ללמוד מן הכתוב \"אותו\": דווקא \u0003אותו\u0004 שעיר נשיא נשחט \u0003בצפון,\u0004 ו\u0003אין\u0004 קרבן ה\u0003פסח\u0004 נשחט \u0003בצפון.\u0004 ומקשים על כך: והרי דין זה של קרבן ה\u0003פסח,\u0004 שאין הוא נשחט בצפון, אינו נלמד מ\"אותו\", אלא \u0003מ\u0004דברי \u0003ר' אליעזר בן יעקב\u0004 הריהו \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: יכול יהא\u0004 קרבן \u0003הפסח טעון\u0004 (חייב) להישחט ב\u0003צפון? ו\u0004הרי \u0003דין\u0004 (קל וחומר) \u0003הוא\u0004 המלמדנו כן, ובאופן זה: \u0003ומה\u0004 קרבן \u0003עולה,\u0004 שיש בה צד קל, \u0003ש\u0004הרי \u0003לא קבע לה\u0004 הכתוב \u0003זמן\u0004 מוגדר \u0003בשחיטתה\u0004 והיא נשחטת בכל יום, בכל זאת \u0003קבע לה\u0004 הכתוב חיוב שחיטה ב\u0003צפון.\u0004 קרבן \u0003פסח,\u0004 החמור \u0003שקבע לו\u0004 הכתוב \u0003זמן\u0004 מוגדר \u0003לשחיטתו\u0004 (בארבעה עשר בניסן) — \u0003אינו דין שקבע לו\u0004 הכתוב חיוב שחיטתו ב\u0003צפון!\u0004","ומשיבים: אין ללמוד מקל וחומר זה, שהרי ניתן לפורכו, ובאופן זה: \u0003מה לעולה\u0004 שיש בה צד חמור מקרבן פסח, \u0003שכן\u0004 היא עולה על המזבח \u0003כליל,\u0004 ואילו קרבן פסח נאכל!","ומקשים על כך: ועדיין יש מקום לדרשת קל וחומר זו, ויילמד דין קרבן הפסח \u0003מ\u0004דין קרבן ה\u0003חטאת.\u0004 שהרי החטאת קלה היא מקרבן הפסח בזה שאין לה זמן קבוע, ואולם אין בה את צד החומרה (שיש בקרבן עולה) שהרי אינה עולה כליל על המזבח, ודינה של החטאת שנשחטת היא בצפון. וממנה נלמד קל וחומר לקרבן פסח שיישחט בצפון. ודוחים: אף לקל וחומר זה פירכה: \u0003מה ל\u0004קרבן \u0003חטאת\u0004 שיש בו צד חמור מקרבן פסח, \u0003שכן\u0004 החטאת \u0003מכפרת על חייבי\u0004 עונשי \u0003כריתות,\u0004 ואילו קרבן פסח אינו בא לכפרה.","ושואלים עוד: ועדיין היה מקום ללמוד דין קרבן פסח \u0003מ\u0004דין קרבן ה\u0003אשם\u0004 בקל וחומר, ולומר שאם בקרבן האשם הקל בדינו מקרבן פסח שהרי אין זמן מוגדר להבאתו ואין בו לא צד חומרה שיש בעולה (העולה כליל), ולא צד חומרה שיש בחטאת (המכפרת על חייבי כריתות), שחיטתו בצפון — קל וחומר שכך הוא הדין אף בקרבן פסח החמור ממנו! ודוחים: אף קל וחומר זה יש לו פירכה: \u0003מה ל\u0004קרבן \u0003אשם\u0004 שיש בו צד חומרה שאין בקרבן פסח, \u0003שכן\u0004 הריהו מכלל \u0003קדשי קדשים,\u0004 ואילו קרבן פסח אינו אלא מכלל קדשים קלים. ומוסיפים ואומרים: אף \u0003מכולהו\u0004 \u0005[מכולם],\u0006 מכל הקרבנות הללו, עולה חטאת ואשם ביחד, \u0003נמי\u0004 \u0005[גם כן]\u0006 לא היה מקום ללמוד שיהא קרבן הפסח נשחט בצפון, בקל וחומר מהדבר המשותף לכל אלה (\"הצד השווה\"), שהריהם קלים מקרבן פסח (שכן אין להם זמן שחיטה מוגדר) — \u0003שכן\u0004 יש צד חומרה המשותף לכולם שאין בקרבן פסח, שכולם הם \u0003קדשי קדשים,\u0004 ואילו קרבן פסח מכלל קדשים קלים. ואם כן חוזרת השאלה למקומה: מה למדנו מ\"אותו\"?","ומשיבים: \u0003אלא לעולם\u0004 יש לומר \u0003כדקאמרינן מעיקרא\u0004 \u0005[כמו שאמרנו מתחילה]\u0006 ובא הכתוב \"אותו\" האמור בשעיר נשיא ללמדנו כי דווקא \u0003אותו\u0004 הקרבן עצמו הוא שעומד \u0003בצפון\u0004 בשעת שחיטתו, \u0003ואין השוחט\u0004 אותו חייב לעמוד \u0003בצפון, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 שאין צורך בכתוב ללמדנו זאת, שכן \u0003מ\u0004דברי \u0003ר' אחייה\u0004 הדורש את הכתוב \"אותו\" האמור בעולה \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר — על כך יש להשיב: דרשתו של \u0003ר' אחייה, לאו למעוטי\u0004 \u0005[לא למעט]\u0006 \u0003שוחט בצפון הוא דאתא\u0004 \u0005[שבא],\u0006 שהרי דין זה נלמד מ\"אותו\" האמור בשעיר נשיא, \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' \u0005אחייה בדרשתו: הכתוב \"אותו\" האמור בשחיטת עולה בא ללמדנו ש\u0006\u0003אין השוחט\u0004 חייב להיות דווקא \u0003בצפון\u0004 בשעה ששוחט, \u0003אבל מקבל\u0004 הדם צריך להיות \u0003בצפון\u0004 בשעת קבלת הדם.","ומקשים על כך: הרי דין זה ש\u0003מקבל\u0004 הדם צריך להיות בצפון כשמקבל את הדם, לא מכאן הוא נלמד, אלא מייתור הכתוב, \u0003מ\u0004מה שיכול היה הכתוב לומר \u0003\"ולקח\",\u0004 וכתב בוא\"ו יתירה \u0003\"ולקח\u0004 הכהן מדם החטאת\" (ויקרא ד, לד). ומיתור זה \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדין שגם המקבל צריך להיות בצפון! ומשיבים: הלימוד הזה של שינוי המלה מ\u0003\"לקח\"\u0004 ל\u0003\"ולקח\",\u0004 \u0003לא משמע ליה\u0004 \u0005[אינו נשמע,\u0006 נראה \u0005לו,\u0006 לחכם שבברייתא\u0005],\u0006 ולכן \u0005הוא צריך ללמוד את הדברים ממקום אחר.\u0006","\u0003ו\u0004עוד שנינו במשנתנו כי העושה את המנחה בחימוץ הריהו \u0003חייב\u0004 מלקות על כל אחת מעבודותיה. \u0003על לישתה, ועל עריכתה ועל אפייתה\u0004 של המנחה. ובענין זה \u0003אמר רב פפא: אפאה\u0004 למנחה בחימוץ — הרי זה \u0003לוקה שתים\u0004 (\u0005שתי\u0006 סדרות מלקות), \u0003אחת\u0004 — \u0003על עריכתה.\u0004 \u0003ואחת\u0004 נוספת — \u0003על אפייתה.\u0004 ומקשים עליו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 בברייתא (המובאת בעמוד הקודם) כי \u0003מה אפייה מיוחדת, שהיא מעשה יחידי, וחייבין עליה בפני עצמה,\u0004 ואינו מתחייב אלא סדרת מלקות אחת, ולא שתיים!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 מברייתא זו, שכן מדובר באופנים שונים: \u0003הא\u0004 \u0005[זה]\u0006 שאמרה הברייתא שאין חייבים על האפייה עצמה שתים — במקרה \u0003דעריך\u0004 \u0005[שערך]\u0006 \u0003הוא ואפה הוא,\u0004 שאותו אדם גם ערך את עיסת מנחת החמץ, וגם אפאה. וכיון שכבר התחייב מלקות על עריכתה, אין הוא מתחייב באפייה אלא סדרת מלקות אחת נוספת. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב פפא שחייב האופה בשתי סדרת מלקות — מדובר \u0003במקרה\u0004 \u0003דעריך חבריה ויהיב ליה\u0004 \u0005[שערך\u0006 את הבצק \u0005חבירו ונתן לו]\u0006 בצק ערוך \u0003ו\u0004הוא \u0003אפה,\u0004 שאף שהעורך חייב סדרת מלקות אחת על עריכתה, מכל מקום האופה חייב שתי סדרות, שכן באפייתו גם גמר את עריכת הבצק.","ודנים עוד בדין חימוץ המנחה. ובתחילה מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדינו של קרבן \u0003בכור\u0004 תם, שאין בו מום, \u0003שאחזו דם,\u0004 שחלה מחמת ריבוי דם, וכדי להצילו ממוות יש להקיז לו דם, שנחלקו חכמים בדבר. שיש אומרים כי \u0003מקיזין אותו את הדם,\u0004 ואולם \u0003רק\u0004 \u0003במקום שאין עושין בו מום\u0004 קבוע על ידי ההקזה, ששב האיבר שנפגע ומתרפא. \u0003ואין מקיזין את הדם במקום שעושין בו מום,\u0004 שאין האיבר שנפגע שב ומתרפא. אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: יקיז, אף במקום שעושין בו מום, ובלבד שלא ישחוט\u0004 לאחר מכן את הבכור כחולין על מנת לאוכלו, \u0003על\u0004 סמך \u0003אותו מום\u0004 שעשה על ידי ההקזה, אלא ימתין לו עד שיפול בו מום אחר. ואילו \u0003ר' שמעון אומר:\u0004"],["\u0003אף נשחט\u0004 לחולין \u0003על\u0004 סמך \u0003אותו מום.\u0004 ואילו \u0003ר' יהודה אומר: אפילו\u0004 אם \u0003מת\u0004 (ימות) הבכור אם לא יקיזו את דמו — \u0003אין מקיזין לו\u0004 כלל \u0003את הדם.\u0004","ובהתייחס לדעות הללו \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: הכל\u0004 (כל החכמים הללו החולקים אם מותרת הקזת דם בבכור שאחזו דם) \u0003מודים\u0004 באדם הבא ו\u0003מחמץ\u0004 עיסת מנחה \u0003אחר מחמץ\u0004 שקדם לו, שכבר היתה העיסה חמץ, והוא הוסיף להחמיצה, \u0003שהוא חייב\u0004 על מעשהו מלקות. וטעם \u0003הדבר,\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בכתוב בדין זה של איסור חימוץ המנחה \"כל המנחה אשר תקריבו לה' \u0003לא תעשה חמץ\"\u0004 (ויקרא ב, יא) \u0003ו\u0004עוד נאמר בכתוב \u0003\"לא תאפה חמץ\u0004 חלקם נתתי אותה מאשי\" (שם ו, י), הרי איפוא שחייבים על כל מעשה ומעשה של חימוץ הנעשה במנחה עד גמר עשייתה.","וכמו כן, כל החכמים מודים \u0003ב\u0004אדם הבא \u0003ו\u0004\u0003מסרס\u0004 את הבהמה \u0003אחר מסרס\u0004 אחר, שקדם וסירס בהמה זו, והוסיף השני בסירוסה, \u0003ש\u0004אף \u0003הוא חייב, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה' ובארצכם לא תעשו\" (שם כב, כד), ויש מקום לשאול: \u0003אם על כורת\u0004 את ביצי הבהמה (\"וכרות\") בלבד \u0003הוא חייב, על\u0004 ה\u0003נותק\u0004 אותן לגמרי מגוף הבהמה \u0003לא כל שכן\u0004 שהוא חייב, ומה טעם הזכירו הכתוב במיוחד? — לא ציינו הכתוב \u0003אלא\u0004 כדי \u0003להביא\u0004 (לרבות) את ה\u0003נותק אחר\u0004 ה\u0003כורת, ש\u0004גם \u0003הוא חייב\u0004 משום מסרס.","ו\u0003לא נחלקו\u0004 החכמים הללו \u0003אלא ב\u0004אדם ה\u0003מטיל מום ב\u0004בהמת קדשים שהוא כבר \u0003בעל מום.\u0004 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 כי כיון שנאמר בדינו של הקרבן \"תמים יהיה לרצון \u0003כל מום לא יהיה בו\"\u0004 (שם כב, כא), הרי לשון כוללת זו (\"כל מום\") באה לרבות איסור הטלת מום אף בבהמה שהיא כבר בעלת מום. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי כיון שנאמר \u0003\"תמים יהיה לרצון\"\u0004 הרי זה בא להורות שאין איסור הטלת מום נוהג אלא בקרבן שאינו בעל מום (\"תמים\") הראוי להקרבה (\"יהיה לרצון\").","ודנים בטעמיהם של ר' מאיר וחכמים: \u0003ו\u0004ל\u0003ר' מאיר,\u0004 הלומד זאת מן הכתוב \"וכל מום לא יהיה בו\", \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 בכתוב זה \u0003\"תמים יהיה לרצון\",\u0004 המורה שאין המדובר אלא במי שאינו בעל מום! ומשיבים: הכתוב \u0003ההוא\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 מכלל איסור זה רק מי שהיה \u0003בעל מום מעיקרא\u0004 \u0005[מתחילתו],\u0006 שכך נולד, ואולם הקרבן שהיה בתחילתו תמים, ונפל בו מום לאחר מכן, אסורה הטלת מום בו אף לאחר מכן.","ותוהים על כך: \u0003בעל מום מעיקרא\u0004 \u0005[מתחילה]\u0006 אין צורך למעט, שהרי כ\u0003דיקלא בעלמא\u0004 \u0005[דקל בלבד]\u0006 \u0003הוא,\u0004 שאין עליו קדושת הגוף כלל, וברור שאין בו איסור הטלת מום!","\u0003אלא\u0004 צריך לומר כי לא בא הכתוב \"תמים יהיה לרצון\" כי אם \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003פסולי המוקדשים\u0004 (קדשים שנפסלו מהקרבה) \u0003ש\u0004\u0003לאחר פדיונם\u0004 ויציאתם לחולין, אין נוהג בהם איסור הטלת מום. ונדרש כתוב מיוחד ללמדנו כן, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואסירי\u0004 \u0005[ו\u0006הם \u0005אסורים],\u0006 אף לאחר שנפדו והריהם חולין, \u0003בגיזה\u0004 של \u0003צמרם\u0004 \u0003ו\u0004ב\u0003עבודה\u0004 בהם, היה מקום לומר כי \u0003במומם נמי ליתסרי\u0004 \u0005[גם כן ייאסרו],\u0006 בהטלת מום בם, על כן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 כתוב זה \u0005משמיע לנו]\u0006 שמותר להטיל בהם מום.","ומבררים עתה את שיטת חכמים: \u0003ורבנן\u0004 \u0005[ו\u0006ל\u0005חכמים]\u0006 שלמדו כן מהכתוב \"תמים יהיה \u0003לרצון\",\u0004 \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]:\u0006 \u0003\"כל מום לא יהיה בו\"\u0004 הבא לרבות עוד אופנים בהם אסורה הטלת מום. ומשיבים: הכתוב \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו\u0006 לדרשה אחרת, ו\u0005כמו ששנויה\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"וכל מום לא יהיה בו\"\u0004 \u0003אין לי\u0004 ללמוד \u0003אלא שלא יהא בו מום\u0004 על ידי מעשה האדם, \u0003מנין\u0004 שבכלל איסור זה אף \u0003שלא יגרום לו\u0004 מום \u0003על ידי אחרים,\u0004 וכגון \u0003שלא יניח בצק או דבילה על גבי האוזן\u0004 של בהמת הקדשים \u0003כדי שיבא הכלב ויטלנו\u0004 ואגב כך יקרע את האוזן, ויוטל מום בה? \u0003תלמוד לומר: \"כל מום\".\u0004 ש\u0003אמר\u0004 הכתוב \u0003\"מום\",\u0004 והוסיף הכתוב \u0003ואמר\u0004 בלשון כוללת \u0003\"כל מום\"\u0004 — לרבות גרימת הטלת מום על ידי אחרים, שהיא אסורה.","ועוד בענין זה של גרימת חימוץ המנחה \u0003אמר ר' אמי: הניח שאור\u0004 (בצק מחומץ הגורם להתססת העיסה ולחימוצה) \u0003על גבי עיסה\u0004 של מנחה, \u0003והלך וישב לו\u0004 ולא עשה דבר, \u0003ונתחמצה\u0004 העיסה \u0003מאליה\u0004 — \u0003חייב עליה\u0004 מלקות, והרי זה \u0003כמעשה שבת,\u0004 כמי שעושה מלאכה בשבת באופן דומה (וכגון שהניח בשר על גבי גחלים, ונצלה הבשר מאליו), שחייב על כך. ושואלים על השוואה זו: \u0003ומעשה שבת כי האי גוונא, מי מיחייב\u0004 \u0005[כגון זה, האם\u0006 הוא \u0005מתחייב]\u0006 עליו? \u0003והאמר\u0004 \u0005[והרי\u0006 \u0003אמר]\u0004 \u0003רבה בר בר חנה,\u0004"],["\u0003אמר ר' יוחנן:\u0004 מי ש\u0003הניח\u0004 בשבת \u0003בשר על גבי גחלים,\u0004 אם לאחר מכן \u0003היפך בו\u0004 בבשר, שהפכו לצידו האחר, ונצלה בשני צדדיו — הריהו \u0003חייב\u0004 על כך משום בישול בשבת. ואם \u0003לא היפך בו\u0004 בבשר — הריהו \u0003פטור,\u0004 שכל עוד לא נצלה משני צידיו אינו מוגדר כמבושל. ואם כן, אף המניח שאור על גבי עיסת מנחה בלא שהפכה על צידה האחר, אם אמנם הריהו כעושה מעשה שבת, הריהו צריך להיות פטור, ושלא כדברי ר' אמי!","\u0003אמר רבא\u0004 בתשובה: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה במלים \u0003\"חייב\u0004 עליה כמעשה שבת\" \u0003נמי דקאמר\u0004 \u0005[גם כן שאמר]\u0006 ר' אמי? שהמניח שאור על גבי עיסת מנחה (אף שלא הפכה מצד לצד) הריהו נחשב \u0003כ\u0004מי שעשה \u0003מעשה\u0004 חיוב ב\u0003צלי של שבת,\u0004 ונחשב כמי שהפך את הצלי על הגחלים.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהוזכרה למעלה, \u0003אמר רבה בר בר חנה,\u0004 \u0003אמר ר' יוחנן: הניח\u0004 בשבת \u0003בשר על גבי גחלים,\u0004 אם לאחר מכן \u0003היפך בו\u0004 לצידו האחר — \u0003חייב\u0004 משום מבשל בשבת. ואם \u0003לא היפך בו\u0004 לצידו האחר — הריהו \u0003פטור.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003דאי\u0004 \u0005[שאם]\u0006 הוא \u0003לא היפך ביה\u0004 \u0005[לא\u0006 היה \u0005הופך בו]\u0006 את הבשר על הגחלים, הבשר \u0003לא בשיל\u0004 \u0005[לא\u0006 היה \u0005מתבשל]\u0006 — \u0003הרי\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שפטור, ומה צורך להשמיענו זאת? \u0003אלא\u0004 אם תאמר \u0003דאי\u0004 \u0003לא מהפיך ליה, נמי הוה בשיל\u0004 \u0005[שאם לא\u0006 היה \u0005מהפך בו, גם כן היה מתבשל]\u0006 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא מיחייב\u0004 \u0005[אינו מתחייב]\u0006 על הנחת הבשר על הגחלים, אף שלא חזר והפך אותו?","\u0005אלא יש לומר כי\u0006 \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו להיאמר אלא באופן \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא היפך ביה\u0004 \u0005[לא\u0006 היה \u0005הופך בו],\u0006 והיה מונח על הגחלים רק בצידו האחד, \u0003הוה בשיל\u0004 \u0005[היה מתבשל]\u0006 \u0003מצד אחד\u0004 רק בישול חלקי (כשליש הבישול הרגיל), ו\u0003כ\u0004דרך בישול ה\u0003מאכל\u0004 של האיש \u0003בן דרוסאי.\u0004 \u0003ו\u0004אילו עתה \u0003כי מהפיך ביה, בשיל\u0004 \u0005[כאשר מהפך בו\u0006 לצידו האחר, הריהו \u0005מתבשל]\u0006 \u0003משני צדדין כמאכל בן דרוסאי. וקא משמע לן\u0004 \u0005[ומשמיע לנו]\u0006 ר' יוחנן בהלכה זו, ש\u0003כל\u0004 בשר הנצלה \u0003מצד אחד כמאכל בן דרוסאי\u0004 — \u0003לא כלום הוא,\u0004 אינו נחשב למלאכת בישול של ממש, להתחייב עליה בשבת. ואולם אם נצלה משני צדדיו כמאכל בן דרוסאי — נחשב הדבר כבישול, וחייב על כך בשבת.","למעלה הובאו דברי ר' יוחנן במניח בשר על גבי גחלים בשבת, ונצלה הבשר בצידו האחד. ובעקבות דברים אלה \u0003אמר רבא:\u0004 \u0003ואם נצלה בו\u0004 באותו בשר \u0003כ\u0004שיעור \u0003גרוגרת,\u0004 אף אם היה זה רק \u0003מצד אחד\u0004 של חתיכת \u0003הבשר, ו\u0004\u0003במקום אחד\u0004 בה, שלא נצלתה שאר החתיכה — הריהו \u0003חייב\u0004 על כך משום מבשל בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 מדברי רבא יש לדייק שדווקא אם נצלה הבשר כשיעור גרוגרת \u0003במקום אחד\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מתחייבים על כך, ואולם אם היה זה \u0003בשנים או\u0004 ב\u0003שלשה מקומות\u0004 נפרדים — \u0003לא\u0004 מתחייבים על כך. \u0003ו\u0004אולם \u0003התנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]\u0006 בענין \u0003הקודח\u0004 בשבת \u0003חור ששיעורו הוא\u0004 \u0003כל שהוא\u0004 — הרי זה \u0003חייב\u0004 (משום מלאכת בונה או משום מכה בפטיש), ויש לדון,","\u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר במשנה כאשר קדח חור \u0003במקום אחד\u0004 בלבד — מדוע יתחייב בכך, שהרי חור ששיעורו \u0003כל שהוא למאי חזי\u0004 \u0005[למה,\u0006 לאיזה שימוש הוא \u0005ראוי]\u0006 לשמש? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר שמדובר במשנה באופן שקדח \u0003בשנים או שלשה מקומות\u0004 נפרדים, וטעם הדבר שחייבים באופן שקדח על קדיחה שכזו, משום \u0003דחזו\u0004 \u0005[שראויים]\u0006 הם \u0003לצירוף,\u0004 וכדרך שעושים בעלי המלאכה, הנצרכים לחור גדול, שבתחילה הריהם עושים שלשה חורים קטנים, ולאחר מכן מצרפים אותם זה לזה. ומעתה, יש לשאול על רבא, שאף אם התבשל הבשר במספר מקומות בחתיכה, שיתחייב בכך שהרי מצטרפים הם זה לזה! ודוחים את השאלה: \u0003לא,\u0004 \u0003לעולם\u0004 מדובר במשנה זו בקודח \u0003במקום אחד\u0004 בלבד, ואשר לשאלה לאיזה שימוש נועד חור בשיעור כלשהו? — \u0003דחזו לבבא דאקלידא\u0004 \u0005[שראויים ל\u0006שים בהם \u0005פתח,\u0006 שן, \u0005של מפתח],\u0006 שקטן הוא מאד.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את מהלך הדברים הללו העוסק בדינו של רבא באופן אחר. \u0003אמר רבא: אפילו\u0004 נצלה הבשר בשיעור כגרוגרת מצד אחד, ו\u0003בשנים ושלשה מקומות,\u0004 הריהו חייב על כך משום מבשל בשבת. ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנה דין ממנו ראיה \u0005לדברי רבא, שכן שנינו:\u0006 \u0003הקודח\u0004 בשבת בשיעור \u0003כל שהוא\u0004 — \u0003חייב.\u0004 ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה החור \u0003במקום אחד\u0004 — מדוע מתחייב הוא בכך, שהרי חור בשיעור \u0003כל שהוא למאי חזי\u0004 \u0005[למה,\u0006 לאיזה שימוש הוא \u0005ראוי]?\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במשנה זו שקדח \u0003בשנים ושלשה מקומות, דחזי\u0004 \u0005[שראויים]\u0006 החורים הללו \u0003לצירוף\u0004 לחור גדול, והרי זה איפוא כשיטת רבא שמתחייב על בישולם של כמה מקומות בבשר, המצטרפים זה לזה. ודוחים את הראיה: \u0003לא,\u0004 אין \u0003לפרש כן את המשנה, אלא\u0004 \u0003לעולם\u0004 תפרש שמדובר פה בקודח \u0003במקום אחד,\u0004 ואשר לשאלה איזה שימוש יכול להיעשות בחור שכזה? \u0003—\u0004 \u0003דחזו לבבא דאקלידא\u0004 \u0005[שראוי\u0006 הוא לשמש מקום \u0005לפתח,\u0006 לשן \u0005של מפתח].\u0006","ושבים לענין איסור חימוץ עיסת המנחה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בפרשת מנחת מרחשת \"כל המנחה אשר תקריבו לה' לא תעשה \u0005חמץ\" (ויקרא ב, יא), ונראה לכאורה כייתור לשון (\"כל המנחה אשר תקריבו לה' \"). ומסבירים מה טעם נאמרו לשונות אלה:\u0006 \u0003אילו נאמר\u0004 רק \u0003\"אשר תקריבו לה' לא תעשה חמץ\"\u0004 — \u0003הייתי אומר\u0004 כי \u0003אין לי אלא ב\u0004כלל האיסור \u0003\"לא תעשה חמץ\" אלא קומץ\u0004 המנחה \u0003בלבד\u0004 הקרב על המזבח (\"אשר תקריבו לה' \"), והיה מקום לשאול: ה","\u0003מנחה\u0004 שעדיין לא נקמצה \u0003מנין\u0004 לנו שאף על חימוצה חייבים? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) עוד \u0003\"מנחה\"\u0004 שאף היא בכלל איסור זה. ועדיין יש מקום לשאול: אין אנו למדים מכתוב זה אלא ביחס למנחת מרחשת, בה נאמר פסוק זה, ואולם שכך הדין אף ב\u0003שאר מנחות\u0004 שלא נזכרו באותה פרשה \u0003מנין\u0004 לנו? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) עוד בכתוב זה, ובלשון ריבוי, \u0003\"כל המנחה\"\u0004 — לרבות דין זה אף בשאר המנחות.","ועוד נדרש האמור בכתוב זה \u0003\"אשר תקריבו לה' \"\u0004— אין נוהג דין זה של איסור חימוץ המנחה אלא במנחה \u0003כשרה, ולא\u0004 במנחה \u0003פסולה\u0004 (כגון זו שיצאה אל מחוץ למקום המקדש, או שנטמאה). \u0003מכאן אמרו\u0004 חכמים כי \u0003המחמיץ את\u0004 המנחה \u0003הכשירה\u0004 — \u0003חייב\u0004 מלקות על כך, \u0003ו\u0004אולם המחמיץ \u0003את\u0004 \u0003הפסולה\u0004 — \u0003פטור.\u0004","מתוך ששנינו שאין איסור חימוץ נוהג במנחה פסולה, אלא בכשרה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003חימצה\u0004 את המנחה בעודה כשרה, \u0003ו\u0004לאחר מכן \u0003יצאת\u0004 (יצאה) אל מחוץ למקדש (ונפסלה בכך משום יוצא), \u0003וחזר וחימצה, מהו\u0004 דינו; האם חייב גם על החימוץ השני? וצדדי הבעיה: האם נאמר כי \u0003כיון\u0004 ש\u0003יצאת,\u0004 הרי בכך \u0003איפסילה\u0004 \u0005[נפסלה]\u0006 \u0003לה ביוצא, ו\u0004לכן \u0003כי הדר\u0004 \u0005[כאשר\u0006 הוא \u0005חוזר]\u0006 ו\u0003מחמיץ לה\u0004 \u0005[אותה]\u0006 — הוא \u0003לא מיחייב עלה\u0004 \u0005[לא מתחייב עליה]\u0006 \u0003משום מחמיץ אחר מחמיץ.\u0004","\u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לומר, כי \u0003כיון\u0004 שבתחילה המנחה \u0003חימצה,\u0004 מעתה \u0003פסול\u0004 של \u0003יוצא\u0004 שוב \u0003לא מהני ביה\u0004 \u0005[לא מועיל,\u0006 פועל \u0005בה]\u0006 להפקיעה מדין \u0005חימוץ, שרק במנחה כשרה שייך פסול \"יוצא\",\u0006 \u0003ו\u0004לכן \u0003כי הדר\u0004 \u0005[כאשר\u0006 הוא \u0005חוזר]\u0006 ו\u0003מחמיץ לה\u0004 \u0005[אותה]\u0006 — הוא \u0003מיחייב עלה\u0004 \u0005[מתחייב עליה]\u0006 \u0003משום מחמיץ אחר מחמיץ?\u0004 לשאלה זו לא נמצאה תשובה ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","ועוד בעיה בדין חימוץ המנחה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב מרי:\u0004 \u0003חימצה\u0004 הכהן את המנחה בהיותו עומד \u0003בראשו של מזבח, מהו\u0004 הדין? וצדדי השאלה: \"כל המנחה \u0003אשר תקריבו\u0004 לה' לא תעשה חמץ\" \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומלשון הכתוב \"אשר תקריבו\" משמע שמדובר במנחה שטרם הקריב אותה הכהן על המזבח, \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זו]\u0006 הרי כבר \u0003אקרבה\u0004 \u0005[הקריבה],\u0006 שהרי כבר עלתה על המזבח, אף שטרם הקטירה, ולכן אין היא עוד בכלל איסור החמצה.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 תאמר, כל שהוא \u0003מחוסר הקטרה\u0004 (שטרם הקטירוהו) הרי \u0003כמחוסר מעשה\u0004 הקרבה למזבח \u0003דמי\u0004 \u0005[הוא נחשב]\u0006 אף שכבר עלה, והריהו איפוא בכלל \"אשר תקריבו\", ואף הוא עדיין באיסור החמצה. גם שאלה זו לא נמצאה לה תשובה ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","ושבים לבירורה של הברייתא שהובאה למעלה. שנינו בה שאילו לא היה נאמר בכתוב אלא \"אשר תקריבו לה' לא תעשה \u0003חמץ\" היינו אומרים כי אין דין חימוץ אמור אלא בקומץ המנחה, ולכן בא הכתוב \"כל המנחה\" וריבה את המנחה כולה שלא נקמצה, ואת כל המנחות כולן, ולא רק מנחת מרחשת. ושואלים:\u0004 \u0003והשתא דנפקא ליה\u0004 \u0005[ועכשיו שיוצאת,\u0006 שנלמדת \u0005לה]\u0006 הלכה זו \u0003מ\"כל המנחה\",\u0004 אם כן הכתוב \u0003\"אשר תקריבו\"\u0004 שנאמר בהמשך \u0003למה לי,\u0004 מה הוא מלמדנו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה כדי \u0003ל\u0004השמיענו \u0003כדתניא\u0004 \u0005[כ\u0006פי \u0005ששנינו\u0006 בברייתא\u0003]:\u0004 מה שנאמר בפרשת המנחות \u0003\"אשר תקריבו\"\u0004 — הרי זה בא \u0003לרבות\u0004 אף את \u0003מנחת נסכים\u0004 (המנחה הבאה עם קרבנות שיש בהם גם נסכים, כגון עולת בהמה או קרבנות שלמים וחטאת ואשם של מצורע, והריהי נשרפת כולה על גבי המזבח) \u0003ל\u0004איסור \u0003חימוץ,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר:\u0004 כתוב זה בא \u0003לרבות\u0004 אף \u0003את\u0004 \u0003לחם הפנים ל\u0004איסור \u0003חימוץ.\u0004 ומבררים את שיטותיהם.","שנינו כי לשיטת ר' יוסי הגלילי אף מנחת נסכים בכלל איסור חימוץ, ויש לשאול: הרי אי אפשר להחמיץ \u0003מנחת נסכים,\u0004 שכן אין היא נילושה אלא בשמן בלבד (שהרי שמנה מרובה), והשמן הלא \u0003מי פירות הם,\u0004"],["\u0003ו\u0004כלל הוא ש\u0003מי פירות אין מחמיצין! אמר ריש לקיש\u0004 בתשובה: \u0003אומר היה ר' יוסי הגלילי\u0004 כי על אף ששמנה של \u0003מנחת נסכים\u0004 מרובה, יש והעושה אותה \u0003מגבלה במים\u0004 אם נראה לו שנצרכת להם, \u0003וכשרה\u0004 היא בכך, ויתכן שתחמיץ בשל אותם מים. ולכך בא הכתוב \"אשר תקריבו\" להשמיענו שאף בה נוהג איסור חימוץ.","ושואלים: ולדעת ר' עקיבא הסבור שבא הכתוב לרבות את לחם הפנים לאיסור חימוץ, והרי לשיטתו אין מקום לאסור חימוץ ב\u0003לחם הפנים,\u0004 שהרי הכלי המשמש למדידתו של קמח העשרון, \u0003מדת\u0004 דבר \u0003יבש\u0004 בלבד \u0003היא,\u0004 כקמח זה. \u0003ושמענא ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 כי כלי \u0003מדת יבש לא נתקדשה\u0004 בקדושת כלי שרת, ולכן לדעתו לא התקדש לחם הפנים אלא משעה שניתן על שולחן הפנים, לאחר שכבר נאפה, ובשלב זה אין שייך בו חימוץ!","ובתירוץ השאלה \u0003מוסרים כי\u0004 \u0003שלח ר' ראובן\u0004 מארץ ישראל לבבל אגרת ובה מסורת דברים \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן,\u0004 ובה נאמר כי \u0003כך היא הצעה של משנה\u0004 (כך הוא נוסחה המדוייק של ברייתא זו), \u0003ואיפוך\u0004 \u0005[ו\u0006יש \u0005ל\u0006\u0005הפוך]\u0006 בה את שמות החכמים החולקים בה, וכך יש לגורסה: \u0003\"אשר תקריבו\"\u0004 (ויקרא ב, יא) — \u0003לרבות לחם הפנים לחימוץ,\u0004 אלו \u0003דברי ר' יוסי הגלילי\u0004 (ולא דברי ר' עקיבא). ואילו \u0003ר' עקיבא אומר:\u0004 בא הכתוב \u0003לרבות מנחת נסכים לחימוץ\u0004 (ואין אלה דברי ר' יוסי הגלילי). ומעתה אין מקום להקשות מדברי ר' עקיבא שבענין מדת יבש על דבריו שבברייתא.","למעלה הובאו דבריו של ר' יוחנן כי יש להפוך את שמות התנאים שבברייתא, והדעה האומרת כי \"אשר תקריבו\" בא לרבות אף את לחם הפנים לאיסור חימוץ היא דעת ר' יוסי הגלילי, שלדעתו כלי המשמש למידת יבש אף הוא התקדש. ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 בכך \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר ר' יוחנן: ר' יוסי הגלילי ו\u0004כן עוד חכם \u0003אחד מתלמידי ר' ישמעאל,\u0004 שניהם \u0003אמרו דבר אחד\u0004 (שווה), \u0003ומנו\u0004 \u0005[ומיהו]\u0006 תלמיד זה של ר' ישמעאל? — \u0003ר' יאשיה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 נאמר בקידוש המשכן וכליו לפני חנוכתו \"ויהי ביום כלות משה להקים את המשכן וימשח אותו ויקדש אותו ואת כל כליו ואת המזבח ואת כל כליו וימשחם ויקדש אותם\" (במדבר ז, א). ונחלקו חכמים בענין הכתוב \u0003\"וימשחם ויקדש אתם\". ר' יאשיה אומר:\u0004 הכלי המשמש ל\u0003מדת\u0004 (מדידת) \u0003הלח\u0004 (כגון השמן והיין שבנסכים) \u0003נמשח\u0004 והתקדש במשיחתו זו להיות קדוש \u0003בין מבפנים\u0004 (בתוכו) \u0003ו\u0004\u0003בין מבחוץ\u0004 לו. ואילו הכלים המשמשים ל\u0003מדת\u0004 (מדידת) הדבר ה\u0003יבש\u0004 (כגון הקמח למנחות) \u0003נמשחו\u0004 והתקדשו בכך להיות קדושים רק \u0003מבפנים\u0004 להם, \u0003ואין נמשחו\u0004 להיות קדושים \u0003אף\u0004 \u0003מבחוץ\u0004 להם.","\u0003ר' יונתן אומר:\u0004 הכלים המשמשים ל\u0003מדת\u0004 (מדידת) \u0003הלח\u0004 — \u0003נמשחו\u0004 להיות קדושים רק \u0003מבפנים\u0004 להם, \u0003ואין נמשחו\u0004 להיות קדושים אף \u0003מבחוץ\u0004 להם. ואילו הכלים המשמשים ל\u0003מדות\u0004 (מדידות) של הדבר ה\u0003יבש\u0004 — \u0003לא נמשחו\u0004 להתקדש \u0003כל עיקר.\u0004 ומוכיח ר' יונתן כשיטתו: \u0003תדע לך\u0004 שמידות היבש לא התקדשו כלל, \u0003שהרי\u0004 למדנו ש\u0003אין\u0004 הכלים הללו \u0003מקדשות\u0004 את הדברים שמכניסים בתוכם, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בשתי הלחם הבאות בחג השבועות \u0003\"ממושבתיכם תביאו לחם תנופה שתים שני עשרנים סלת תהיינה חמץ תאפינה בכורים לה' \"\u0004(ויקרא כג, יז), \u0003אימתי הן\u0004 נחשבות כמקודשות \u0003\"לה' \"\u0004(\"בכורים לה' \")? — רק \u0003לאחר שנאפו\u0004 (\"תאפינה... בכורים לה' \"), הרי שלא התקדשו קודם לכן, כשנמדדו במדת העשרון לקמח.","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 ר' יאשיה ור' יונתן? — \u0003ב\u0004דרשת המלה \u0003\"אתם\"\u0004 האמורה בכתוב ב\u0005משיחת המשכן וכליו. שלדעת שניהם המלה \"אותם\" באה למעט דבר שאינו בכלל משיחה והתקדשות, אלא שנחלקו מהו. ש\u0006\u0003ר' יאשיה סבר\u0004 \u0005[סבור]\u0006 כי המלה \u0003\"אתם\"\u0004 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את קדושת הכלים המשמשים ל\u0003מדת\u0004 (מדידת) \u0003יבש\u0004 מ\u0003בחוץ\u0004 להם, שהם קדושים בתוכם בלבד. \u0003ו\u0004אילו \u0003ר' יונתן סבר\u0004 \u0005[סבור]\u0006 כי הכלי המשמש ל\u0003מדת\u0004 (מדידת) \u0003יבש\u0004 — כלי של \u0003חול הוא,\u0004 ואינו קדוש כלל, לא מחוצה לו ולא בתוכו. \u0003ו\u0004לכן \u0003לא אצטריך קרא למעוטי\u0004 \u0005[לא הוצרך הפסוק למעט]\u0006 אותו. ואולם \u0003כי איצטריך קרא למעוטי\u0004 \u0005[כאשר הוצרך הפסוק למעט]\u0006 הרי זה את הכלי המשמש ל\u0003מדת\u0004 (מדידת) \u0003הדבר ה\u0004\u0003לח,\u0004 וללמדנו שאין הוא קדוש \u0003מבחוץ\u0004 לו.","ושואלים: כיון שמחלוקת ר' יאשיה ור' יונתן היא בדינו של כלי יבש, \u0003לימא נמי\u0004 \u0005[יאמר גם כן]\u0006 ר' יוחנן, כדרך שאמר לגבי ר' יוסי הגלילי, כי \u0003ר' עקיבא ואחד מתלמידי ר' ישמעאל אמרו דבר אחד, ומנו\u0004 \u0005[ומיהו]\u0006 תלמיד זה? \u0003ר' יונתן,\u0004 ששניהם סבורים כי כלי מדידת יבש אינו קדוש! ומשיבים: סיבת הדבר שלא אמר ר' יוחנן שר' עקיבא ור' יונתן אמרו דבר אחד היא \u0003משום\u0004 ש\u0003לא שוו\u0004 \u0005[לא משתוות]\u0006 שיטותיהם \u0003ב\u0004דינו של הכלי המשמש ל\u0003מדת\u0004 (מדידת) \u0003לח להדדי\u0004 \u0005[זו לזו],\u0006 שכן ר' עקיבא סבור שכלים אלה קדושים הן בתוכם והן מחוצה להם, ואילו ר' יונתן סבור שהריהם קדושים רק בתוכם ולא מחוצה להם. ודנים עוד בענין זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי\u0004 בשאלה: כיצד אומרים אנו (לשיטת הסבורים כי כלי מדידת יבש לא התקדש) כי לחם הפנים לא התקדש אלא בנתינתו על השולחן, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 לפני כן השלב בו ניתן הבצק ב\u0003ביסא\u0004 (הכלי המשמש ללישה), שכלי המשמש את ה\u0003לח הוא,\u0004 והתקדשה העיסה כבר אז? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא בתשובה: אין המדובר בזמן שלש את המנחה בביסא, אלא \u0003כגון שלש\u0004 אותה \u0003על גבי קטבליא\u0004 (מצע עור) שטוח, שאינו מקדש.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבכך מדובר, אף זה \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003ר' יונתן\u0004 לר' יאשיה כהוכחה לשיטתו \u0003תדע לך שהרי אינה מקדשת\u0004 (מתקדשת) שתי הלחם לפני אפייתה, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 ר' יאשיה בדחיית הראיה, שאף כאן מדובר \u0003כגון דכיילא\u0004 \u0005[שמדד]\u0006 את הקמח הבא לשתי הלחם \u0003בעשרון\u0004 (כלי למדידת כמות עשרון) שהוא של","\u0003חול,\u0004 שאינו מקדש! ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]\u0006 את לישת המנחה למדידת הקמח, \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין לישה בקטבליא ולא ב\u0003ביסא\u0004 ניתן להעמיד את \u0003הדברים כך, שהרי\u0004 \u0003לא כתב רחמנא\u0004 \u0005[לא כתבה התורה]\u0006 \u0003דלעביד\u0004 \u0005[שיעשה]\u0006 דווקא ב\u0003ביסא למילש ביה\u0004 \u0005[ללוש בה],\u0006 ולכן גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לש לה\u0004 את עיסת המנחה \u0003על גבי קטבליא\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 דבר לומר \u0003בה. אלא\u0004 במדידה ב\u0003עשרון,\u0004 אי אפשר לומר כך, שכן \u0003כיון דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 במפורש \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003עשרון וכייל ביה\u0004 \u0005[ומדוד בו],\u0006 האם יתכן שעושה המנחה \u0003שביק\u0004 \u0005[יעזוב]\u0006 \u0003עשרון\u0004 של \u0003קודש וכייל\u0004 \u0005[וימדוד]\u0006 \u0003בעשרון\u0004 של \u0003חול?!\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין ל\u0004כהן ה\u0003מעלה\u0004 למזבח \u0003מבשר\u0004 קרבן ה\u0003חטאת\u0004 לאחר שכבר הוקרבו אימוריו על המזבח על מנת להקטירו, \u0003ו\u0004כן \u0003מבשר\u0004 \u0003ה\u0004\u0003אשם\u0004 לאחר שקרב החלק המוקטר על המזבח, שאמור להנתן לכהנים לאכילה, \u0003ו\u0004כן \u0003מבשר\u0004 קרבנות \u0003קדשי הקדשים,\u0004 כגון שלמי ציבור, \u0003ו\u0004כן המעלה \u0003מ\u0004בשר \u0003קדשים קלים\u0004 הנאכלים לבעליהם, \u0003וממותר העומר\u0004 לאחר קמיצתו, \u0003וממותר שתי הלחם, ומלחם הפנים, ומשירי מנחות\u0004 לאחר שנקמצו והוקטר הקומץ, שבכל אלה כיון שאינם מהדברים האמורים לעלות על המזבח \u0003שהוא\u0004 עובר על כך \u0003ב\u0004איסור \u0003לא תעשה?\u0004","\u0003תלמוד לומר: \"כי כל שאר וכל דבש לא תקטירו ממנו אשה לה' \"\u0004— לומר כי \u0003כל\u0004 דבר \u0003שהוא\u0004 כבר העלה \u0003ממנו לאישים\u0004 (לאש המזבח, שכבר הוקרב), \u0003הרי הוא\u0004 עומד \u0003ב\u0004איסור \u0003בל תקטירו\u0004 (\"לא תקטירו\" האמור בכתוב).","ותוהים: \u0003ו\u0004האם ב\u0003שתי הלחם ו\u0004ב\u0003לחם הפנים יש\u0004 דבר הניתן \u0003מהן לאישים?\u0004 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 כל הקרבנות חלק מהם קרב על המזבח, \u0003יצאו\u0004 מכלל זה \u0003שתי הלחם ולחם הפנים שאין\u0004 חלק \u0003מהם\u0004 ניתן \u0003לאישים!\u0004","ומשיבים: \u0003אמר רב ששת:\u0004 אמנם \u0003אין\u0004 דבר \u0003מגופו\u0004 של שתי הלחם ושל לחם הפנים שניתן \u0003לאישים,\u0004 אבל לענין איסור העלאתם למזבח, הריהם כשאר הקרבנות שקרב חלקם על המזבח, שאסורים בהעלאה שכן אף הלחם נחשב כשיריים לכבשים והבזיכים שכן בהקטרתם התירו אותו באכילה.","ועוד בדין המעלה על המזבח מכל אלה שכבר הוקרב חלקם על המזבח. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדינו של \u0003המעלה\u0004 ומקטיר \u0003מכולם\u0004 לא על המזבח עצמו \u0003אלא\u0004 \u0003על גבי הכבש\u0004 של המזבח, אם אף הוא בכלל איסור בל תקטירו. ש\u0003ר' יוחנן אמר:\u0004 \u0003חייב,\u0004 ואילו \u0003ר' אלעזר אמר: פטור.\u0004","ומסבירים את שיטותיהם: \u0003ר' יוחנן אמר\u0004 ש\u0003חייב, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 לאחר שנאמר בפסוק \"כל המנחה אשר תקריבו לה' לא תעשה חמץ כי כל שאור וכל דבש לא תקטירו ממנו אשה לה' \" ממנו למדנו איסור הקטרת הדבר שחלק ממנו הוקרב כבר, נאמר בפסוק שלאחריו \"קרבן ראשית תקריבו אותם לה' ואל המזבח לא יעלו לריח ניחוח\". ומן האמור בפסוק זה \u0003\"המזבח\"\u0004 — \u0003אין לי\u0004 ללמוד שבכלל איסור זה \u0003אלא\u0004 דבר שהוקרב ממנו ל\u0003מזבח\u0004\u0003,\u0004 ואילו דבר שהוקרב ממנו ל\u0003כבש\u0004 המזבח \u0003מנין\u0004 לי שאף הוא בכלל איסור זה? לכך \u0003תלמוד לומר\u0004 (מלמד הנאמר) \u0003\"ואל המזבח לא יעלו לרצון\".\u0004","\u0003ור' אלעזר\u0004 ש\u0003אמר\u0004 \u0003ש\u0004\u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"כי כל \u0003שאור ו\u0004כל \u0003דבש\u0004 לא תקטירו ממנו אשה לה'. \u0003קרבן ראשית תקריבו אתם\u0004 לה' ואל המזבח לא יעלו לריח ניחוח\".","אחז הכתוב בלשון \u0003\"אתם\"\u0004 ללמדנו: דווקא בשתי הלחם וביכורים שהם באים משאור ודבש, ומכונים גם \"קרבן ראשית\". (שתי הלחם — הבא חמץ, \"שאור\", והריהו ראשון לכל המנחות הבאות מהתבואה החדשה, וביכורים — הבאים משבעת המינים, \"דבש\" והם \"ראשית בכורי אדמתך\". שמות כג, יט), \u0003הוא דרבי\u0004 \u0005[שריבה]\u0006 \u0003לך\u0004 הפסוק שדינו של \u0003כבש\u0004 המזבח לגביהם הוא \u0003כ\u0004דינו של ה\u0003מזבח,\u0004 לענין איסור העלאה. \u0003אבל\u0004 כל \u0003מידי אחרינא\u0004 \u0005[דבר אחר],\u0006 כגון בשר חטאות ובשר האשם — \u0003לא\u0004 נתרבה כבש המזבח להיחשב לעניינם כמזבח עצמו."],["ושואלים: \u0003ו\u0004לדעת \u0003ר' יוחנן\u0004 הסבור שכל המנויים בברייתא הריהם בכלל איסור הקטרה אף על הכבש, \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"אתם\"\u0004 האמור בפסוק \"קרבן ראשית תקריבו אותם\" (ויקרא ב, יב) שממנו למד ר' אלעזר למעט את שאר המנויים בברייתא (מלבד שתי הלחם וביכורים), \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו,\u0006 לומד ממנו\u0005]?\u0006","ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כתוב זה \u0003ל\u0004למדנו הלכה אחרת, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003יכול יהא\u0004 הדין שאף \u0003יחיד\u0004 (אדם מישראל) \u0003מתנדב ומביא\u0004 למקדש \u0003כיוצא בה\u0004 (כמו) מנחת שתי הלחם (הבאה דווקא על ידי ציבור) ויביאנה \u0003ב\u0004\u0003נדבה, וקורא אני בה\u0004 בנדבה זו את האמור בדינו של הנודב למקדש \u0003\"מוצא שפתיך תשמר ועשית\u0004 כאשר נדרת לה' אלקיך נדבה אשר דברת בפיך\" (דברים כג, כד), שחלה עליה קדושה וחייב להביאה כדבריו?","\u0003לכך\u0004 \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"קרבן ראשית תקריבו\"\u0004 הכתוב בלשון רבים (\"תקריבו\") כי דווקא \u0003ציבור אמרתי לך\u0004 שמקדיש ומביא את שתי הלחם (שהם \"קרבן ראשית\"), \u0003ולא יחיד\u0004 מקדיש ומביא אותם.","ודנים עוד בדבר: \u0003יכול\u0004 \u0003ש\u0004\u0003לא יהא\u0004 ה\u0003יחיד מביא\u0004 שתי הלחם בנדבה, משום \u0003ש\u0004היחיד \u0003אינו מביא חובתו כיוצא בה,\u0004 שהרי אין לו מנחת חובה בדומה לזו, \u0003אבל\u0004 אפשר \u0003יהא\u0004 ה\u0003ציבור מביא\u0004 בנדבה שתי הלחם, \u0003ש\u0004הרי הציבור \u0003מביא חובתו כיוצא בה?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"אתם\"\u0004 למעט אף את הציבור מהבאת שתי הלחם בנדבה. \u0003ו\u0004מסכמים: \u0003מה יש לך להביא\u0004 לקיום הנאמר בכתוב \"כי כל שאור וכל דבש לא תקטירו... קרבן ראשית תקריבו אותם\"? את \u0003שתי הלחם\u0004 הבאים \u0003מן השאור,\u0004 שבאים רק בציבור, \u0003ו\u0004את ה\u0003בכורים\u0004 הבאים \u0003מן הדבש\u0004 (מן הפירות המתוקים) שאותם מביא היחיד.","ושואלים: \u0003ו\u0004האם \u0003שתי הלחם לא יקרבו נדבה? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על האמור בפסוק \"כי כל שאור וכל דבש \u0005לא תקטירו\" —\u0006 \u0003אם\u0004 כבר \u0003נאמר\u0004 בכתוב איסור \u0003\"כל שאר\",\u0004 שהריהו לשון ריבוי, \u0003למה נאמר\u0004 עוד \"ו \u0003כל דבש\",\u0004 ואינו נלמד מ\"כל שאור\". \u0003ו\u0004כן לצד האחר: \u0003אם נאמר \"כל דבש\", למה נאמר \"כל שאר\"?\u0004 ומשיבים: נצרכו שניהם להיאמר, שאין אחד למד מחבירו, \u0003מפני שיש\u0004 דין הנוהג דווקא \u0003בשאור, מה שאין\u0004 נוהג \u0003בדבש. ויש\u0004 דין הנוהג דווקא \u0003בדבש, מה שאין\u0004 נוהג \u0003בשאור.\u0004","ומפרטים: \u0003דבר הנוהג בשאור, ואינו נוהג בדבש —\u0004 ה\u0003שאור,\u0004 אף שבכללו הריהו אסור בהקרבה על המזבח, מצאנו בו ש\u0003הותר\u0004 איסור זה \u0003מכללו במקדש,\u0004 שהרי שתי הלחם ולחמי תודה קרבים חמץ, ואילו ה\u0003דבש לא הותר מכללו במקדש\u0004 שאין קרבן הבא מהפירות המתוקים.","ולהיפך, דבר הנוהג בדבש, ואינו נוהג בשאור — \u0003ה\u0004\u0003דבש הותר\u0004 באכילה \u0003בשירי מנחות,\u0004 שמותר לאוכלם כשמעורב בהם דבש, ואילו \u0003שאור לא הותר בשירי מנחות,\u0004 שאסור להחמיץ אותם. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מפני שיש בשאור מה שאין בדבש, ויש בדבש מה שאין בשאור,\u0004 לכך \u0003הוצרך\u0004 הכתוב \u0003לומר \"כל שאר\" והוצרך\u0004 גם \u0003לומר\u0004 \"ו \u0003כל דבש\",\u0004 ונדייק בדברי הברייתא הללו: זה ששנינו בה כי ה","\u0003שאור הותר מכללו במקדש, מאי ניהו\u0004 \u0005[מה הוא\u0006 עניינו\u0005]?\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא \u0003ש\u0004מנחת \u0003שתי הלחם קרבה\u0004 על ידי הציבור גם ב\u0003נדבה,\u0004 ושלא כדברי הברייתא הקודמת! \u0003אמר רב עמרם: לא,\u0004 אין כוונת הברייתא בצד ייחודו של השאור שהותר מכללו, ששתי הלחם באים בנדבת ציבור, אלא כוונתה שהשאור \u0003בא\u0004 \u0003ליקרב עמהם,\u0004 ששתי הלחם שהם חמץ באים עם כבשי העצרת. ואף שהכבשים בלבד הם שעולים למזבח ובלא שתי הלחם, מכל מקום הריהם באים כאחד, ולכך הוא נחשב כאילו הותר מכללו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שהלשון \"הותר מכללו\" מתייחסת אף לחלק הנלווה לקרבן, ב\u0003בכורים נמי\u0004 \u0005[גם כן]\u0006 יש הותר מכללו כיוצא בזה בדבר הקרב עם הביכורים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 את \u0003הגוזלות ש\u0004היו \u0003על גבי הסלין\u0004 בהם נתונים הביכורים המובאים למקדש \u0003היו\u0004 מביאים לקרבנות \u0003עולות, ו\u0004אילו \u0003הסלים שבידם\u0004 של מביאי הביכורים היו \u0003ניתנין לכהנים.\u0004 הרי איפוא שיש עולות שהותרו מכלל, שהרי הן באות מ\"דבש\" (מפירות המתוקים של הביכורים)! ומתרצים: \u0003הנהו\u0004 \u0005[אלה]\u0006 העופות הבאים עם הביכורים, אינם באים כחובה, ולכך אינם נחשבים כחלק הקשור לביכורים, שכן הגוזלות הללו רק כדי \u0003לעטר\u0004 בהם את ה\u0003בכורים\u0004 בלבד \u0003הוא דאתו\u0004 \u0005[שבאו]\u0006 ואף שאחר כך מעלים אותם כעולות אינם חלק מהביכורים.","ועוד בדינו של המעלה למזבח מן הקרבנות לאחר שהוקרב חלקם. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא מרב חסדא: המעלה מבשר חטאת העוף\u0004 שאינה עולה למזבח אלא כולה עומדת לאכילת הכהנים \u0003על גבי המזבח, מהו\u0004 דינו? האם לוקה על העלאה זו משום בל תקטירו?","וצדדי השאלה: האם דווקא ב\u0003כל\u0004 דבר מן הקדשים \u0003ש\u0004ניתן \u0003ממנו לאישים\u0004 (על אש המזבח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שהחוזר ומעלה ממנו על המזבח עובר בבל תקטירו, \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה\u0006 בשר חטאת העוף\u0005]\u0006 \u0003אין\u0004 ניתן \u0003ממנו לאישים,\u0004 שהרי אינו קרב כלל על המזבח, ולכן פטור על כך. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא ש\u0003כל ששמו 'קרבן'\u0004 הריהו בכלל איסור העלאה, \u0003והאי נמי\u0004 \u0005[וזה,\u0006 בשר חטאת העוף, \u0005גם כן]\u0006 \u0003שמו 'קרבן',\u0004 ויהיה חייב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא בפתרון שאלתו: \u0003כל ששמו 'קרבן'\u0004 הריהו בכלל איסור העלאה, \u0003ו\u0004כיון ש\u0003האי נמי\u0004 \u0005[זה,\u0006 בשר חטאת העוף, \u0005גם כן]\u0006 \u0003שמו 'קרבן',\u0004 לכן הריהו חייב על כך.","ומעירים: ספקו זה של רמי בר חמא, הריהו \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בדבר. שכן שנינו ש\u0003ר' אליעזר אומר:\u0004 רק \u0003כל שממנו לאישים\u0004 הריהו בכלל איסור העלאה. ואילו \u0003ר' עקיבא אומר:\u0004 אף \u0003כל ששמו 'קרבן'\u0004 הריהו בכלל איסור זה.","ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל להלכה, יש \u0005ביניהם]?\u0006 \u0003אמר רב חסדא:\u0004 הבדל בדינו של המעלה \u0003מ\u0004\u0003בשר חטאת העוף\u0004 למזבח \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת ר' עקיבא חייב שהרי שם 'קרבן' עליו, ולדעת ר' אליעזר פטור שהרי אינו עולה לאישים.","\u0003רב אמר:\u0004 בדינו של המעלה למזבח \u0003לוג שמן של מצורע איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003לוי\u0004 על הכתוב בקדשים הניתנים לכהנים לאכילה \"זה יהיה לך מקדש הקדשים מן האש \u0003כל קרבנם...\u0004 קדש קדשים לך והוא ולבניך\" (במדבר יח, ט), ובאה לשון ריבוי זה \"כל קרבנם\" \u0003לרבות לוג שמן של מצורע,\u0004 שאף הוא נקרא \"קרבן\", ואולם אינו עולה לאש המזבח. ומעתה, לדעת ר' עקיבא המעלהו למזבח חייב, שהריהו בכלל \"כל ששמו קרבן\", ואילו לדעת ר' אליעזר פטור, שכן איננו בכלל \"כל שממנו לאישים\".","ודנים עוד באיסור הקטרת שאור. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממה שנאמר בתורה \"כי כל \u0003שאור... בל\u0004 (לא) \u0003תקטירו\u0004 ממנו\" (ויקרא ב, יא) \u0003אין לי\u0004 \u0003אלא\u0004 המקטיר את \u0003כולו,\u0004 ואולם המקריב רק את \u0003מקצתו\u0004 של השאור \u0003מנין\u0004 לנו שאף הוא בכלל איסור זה? — \u0003תלמוד לומר\u0004 \u0003\"כל\u0004 שאור\" בלשון ריבוי, שאף זה אסור. ודנים עוד: אין לי בכלל האיסור אלא המקריב את השאור בעינו, ואולם המקריב אותו ב\u0003עירובו\u0004 בדבר אחר, \u0003מנין?\u0004 — \u0003תלמוד לומר\u0004 בתוספת הלשון \u0003\"כי כל\",\u0004 שאף זה בכלל האיסור.","ומבררים את דברי החכם בברייתא, \u0003מאי קאמר\u0004 \u0005[מה הוא אמר],\u0006 מה כוונת הדברים \"כולו\" ו\"מקצתו\"? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אמר]:\u0006 ממה שנאמר בתורה \u0003\"שאר בל תקטירו\" אין לי\u0004 ללמוד איסור \u0003אלא\u0004 לענין הקטרת שאור ששיעורו \u0003כזית,\u0004 ואולם שאור ששיעורו הוא רק כ\u0003חצי זית מנין?\u0004 — \u0003תלמוד לומר: \"כל\".\u0004 הקטרת שאור שאינו בעין אלא \u0003עירובו מנין\u0004 לי שגם הוא אסור? לכך \u0003תלמוד לומר: \"כי כל\".\u0004 שהלשונות \"כולו\" ו\"מקצתו\" מתייחסים לשיעור שלם של כזית, ולחלק משיעור זה.","ואילו \u0003רבא אמר\u0004 לפרש את דברי הברייתא באופן שונה, ו\u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 החכם שבברייתא, \u0005אמר]:\u0006 ממה שנאמר בתורה \u0003\"שאר בל תקטירו\" אין לי\u0004 ללמוד איסור \u0003אלא\u0004 לענין הקטרת כל ה\u0003קומץ\u0004 של השאור, ואולם איסור הקטרתו של \u0003חצי קומץ מנין?\u0004 — \u0003תלמוד לומר\u0004 לשון הריבוי \u0003\"כל\".\u0004 הקטרת שאור ב\u0003עירובו מנין\u0004 לי שאף הוא אסור? — \u0003תלמוד לומר: \"כי כל\".\u0004","ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון, \u0005הם,\u0006 אביי ורבא \u0005חלוקים]?\u0006 \u0003אביי סבר: יש קומץ\u0004 גם \u0003פחות מ\u0004שיעור של כ\u0003שני זיתים.\u0004 ולכן האיסור \"שאור לא תקטירו\" המתייחס לקומץ שלם אמור אף בפחות משני זיתים, והריבוי \"כל שאור\" מלמד שאף בחלק מקומץ זה, ואפילו פחות משיעור כזית הריהו עובר ב\"לא תקטירו\","],["\u0003ו\u0004משום כך סבור אביי כי \u0003יש\u0004 איסור \u0003הקטרה\u0004 גם כשמידת השאור \u0003פחותה מכ\u0004 שיעור \u0003זית. ו\u0004","אילו \u0003רבא אמר\u0004 כי \u0003אין קומץ\u0004 ב\u0003פחות מ\u0004שיעור כ\u0003שני זיתים,\u0004 ולכן האיסור \"שאור... לא תקטירו\" \u0003(ויקרא ב, יב) נאמר בשיעור שני זיתים ומעלה, ואילו הריבוי \"כל שאור... לא תקטירו\" מלמד שאף בחלק משיעור זה הריהו עובר\u0004 \u0003ו\u0004לעולם \u0003אין הקטרה פחותה מכזית.\u0004","ועוד ממחלוקת אביי ורבא בענין זה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אביי ורבא בדינו של \u0003המעלה\u0004 תערובת שיש בה \u0003משאור ומדבש על גבי המזבח,\u0004 מה דינו? \u0003אמר רבא:\u0004 הרי זה \u0003לוקה\u0004 על העלאה זו ארבע סדרות מלקות, שכן יש במשמעות הכתוב \"כי כל שאור וכל דבש לא תקטירו\" (ויקרא ב, יא) ארבעה איסורים. ומפרטים: לוקה אחת \u0003משום\u0004 איסור העלאה למזבח של \u0003שאור\u0004 (\"שאור... לא תקטירו\"). \u0003ולוקה\u0004 שניה \u0003משום\u0004 איסור העלאה למזבח של \u0003דבש\u0004 (\"דבש לא תקטירו\"). ו\u0003לוקה\u0004 עוד \u0003משום\u0004 איסור העלאה למזבח של \u0003עירובי שאור\u0004 (הנלמד מלשון הריבוי \"כל שאור\"), \u0003ו\u0004לוקה עוד \u0003משום\u0004 איסור העלאה למזבח של \u0003עירובי דבש\u0004 (הנלמד מלשון הריבוי \"וכל דבש\").","ואילו \u0003אביי אמר: אין לוקין על לאו שבכללות\u0004 (לאו הכולל כמה איסורים), שכיון שנאמר בכל אלה ה\u0003לאו \"לא תקטירו\", הרי זה לאו כולל שאין לוקים עליו. ובפירוש שיטת אביי נחלקו חכמים,\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי לדעת אביי סדרת מלקות \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על הקטרת השאור, וכן אחת נוספת על הקטרת הדבש, שכן שני איסורים אלה אינם בגדר לאו שבכללות (שהרי הכתוב \"לא תקטירו\" מתייחס לשניהם, וכאילו נאמר בכתוב \"שאור לא תקטירו\", \"דבש לא תקטירו\").","\u0003ואיכא דאמרי\u0004 \u0005[ויש\u0006 \u0003שאומרים]\u0004 כי לדעת אביי אף סדרת מלקות \u0003חדא\u0004 \u0005[אחת]\u0006 על השאור ועל הדבש \u0003נמי לא לקי\u0004 \u0005[גם כן אינו לוקה],\u0006 וטעם הדבר: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא מיחד לאויה\u0004 \u0005[אין הלאו שלו מיוחד,\u0006 מוגדר לעצמו\u0003]\u0004 \u0003כ\u0004דרך שמוגדר ה\u0003לאו\u0004 של \u0003חסימה\u0004 של שור בדישו (דברים כה, ד), שממנו למדים לכל הדינים של מלקות לעובר על מצוות לא תעשה."],["\u0003יש\u0004 מנחות ש\u0003טעונות\u0004 (חייבות שיהיה בהן) הן \u0003שמן ו\u0004הן \u0003לבונה.\u0004 ויש שחייבות ב\u0003שמן ולא\u0004 ב\u0003לבונה.\u0004 ויש שחייבות ב\u0003לבונה ולא\u0004 ב\u0003שמן,\u0004 ויש שאין חייבות \u0003לא\u0004 ב\u0003לבונה ולא\u0004 ב\u0003שמן.\u0004","ומפרטים, \u0003ואלו\u0004 הן ה\u0003טעונות\u0004 גם \u0003שמן ו\u0004גם \u0003לבונה\u0004 אף שהתנדב ואמר \"מנחה\" סתם, ולא פירש שבכלל זה שמן ולבונה: \u0003מנחת הסולת\u0004 (בה נאמר בכתוב \"ויצק עליה שמן ונתן עליה לבונה\". ויקרא ב, א), \u0003ו\u0004הוא הדין במנחת \u0003המחבת, ו\u0004במנחת \u0003המרחשת,\u0004 ומנחת מאפה תנור, \u0003ה\u0004באה \u0003חלות\u0004 (לחמים) \u0003ו\u0004כן זו \u0003ה\u0004באה \u0003רקיקין\u0004 (הדקות כמצות), שכן יכול הוא להביאה אם מחלות אם מרקיקים.","וכיוצא באלה אף \u0003מנחת כהנים\u0004 המתנדבים להביא אחת מהמנחות הללו, וכן \u0003מנחת כהן משיח\u0004 (גדול) (\"מנחת חביתין\"), וכן \u0003מנחת\u0004 ה\u0003גוי\u0004 שהתנדב אחת מהמנחות הללו, וכן \u0003מנחת נשים\u0004 שהתנדבו אחת מהמנחות הללו, וכן \u0003מנחת העומר\u0004 הקרבה ביום ט\"ז בניסן, למחרת יום ראשון של חג הפסח.","ולעומת כל אלה \u0003מנחת נסכים\u0004 הקרבה עם קרבנות העולה והשלמים — \u0003טעונה שמן ו\u0004אולם \u0003אין\u0004 היא \u0003טעונה לבונה.\u0004 ו\u0003לחם הפנים\u0004 הריהו \u0003טעון לבונה, ו\u0004אולם \u0003אין\u0004 הוא \u0003טעון שמן.\u0004","ונבדלות מכל אלה \u0003שתי הלחם\u0004 הבאה בחג השבועות, \u0003ומנחת חוטא\u0004 הבאה על ידי העני כשחטא בדבר המחייב קרבן חטאת הבא לפי מעמדו הכספי של החוטא (\"עולה ויורד\"), \u0003ומנחת קנאות\u0004 (מנחת הסוטה) — כל אלה \u0003אין טעונין לא שמן ולא לבונה,\u0004 אם משום שלא הוזכרו בהן שמן או לבונה (כבשתי הלחם), מנחת חוטא — משום שנאמר בה במפורש שאין נותנים עליה שמן ולבונה \"לא ישים עליה שמן ולא יתן עליה לבונה כי חטאת היא\" (ויקרא ה, יא), ומנחת סוטה — שנאמר בה \"לא יצוק עליו שמן ולא יתן עליו לבונה כי מנחת קנאות הוא מנחת זכרון מזכרת עון\" (במדבר ה, טו).","\u0003אמר רב פפא\u0004 כי כלל הוא בלשון משניות מסכת מנחות (ובכלל זה משנתנו): \u0003כל היכא\u0004 \u0005[מקום]\u0006 במסכתנו \u0003דתנן\u0004 \u0005[ששנינו]\u0006 בו \"מנחות\" — במנחות הבאות ב\u0003עשר\u0004 דומות (שיש בהן או עשרה לחמים או עשרה רקיקים, ובלבד שיהיו כולם מאותו הסוג) \u0003תנן\u0004 \u0005[שנינו].\u0006 ומסבירים: דברים אלה של רב פפא באו \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שהנודר להביא מנחת מאפה, מביא עשרה לחמים, ואולם סוג הלחמים תלוי ברצונו: שיכול הוא להביאה בעשרה לחמים, או בעשרה רקיקים, ואם רצה להביא \u0003מחצה\u0004 (חמש מהן) \u0003חלות ומחצה\u0004 (וחמש אחרות) \u0003רקיקין\u0004 — \u0003יביא,\u0004 ולכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 רב פפא \u0005משמיע לנו]\u0006 בכלל זה שאמר, ש\u0003לא\u0004 כך סבורה משנתנו, ואין \u0003עשרת הלחמים באים אלא מאותו הסוג.\u0004","שנינו במשנתנו כי מנחת העומר חייבת בשמן ובלבונה, ומקור הדבר בפסוק \"ונתת עליה שמן ושמת עליה לבונה מנחה היא\" (ויקרא ב, טו). ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"ונתת עליה שמן\"\u0004 המלה \"עליה\" שלשון מיעוט היא באה ללמד כי דווקא על מנחת העומר נותנים שמן, \u0003ולא על לחם הפנים\u0004 נותנים \u0003שמן.\u0004","ונצרך הכתוב למעט את לחם הפנים מנתינת שמן עליו, \u0003ש\u0004כן \u0003יכול\u0004 היה אדם לטעון: \u0003והלא דין\u0004 (דבר הנלמד במידת קל וחומר) \u0003הוא\u0004 שיהא לחם הפנים חייב בנתינת שמן עליו, ובאופן זה: \u0003ומה מנחת נסכים\u0004 (הנלוית לקרבנות העולה והשלמים) הקלה בדינה מלחם הפנים, \u0003ש\u0004הרי היא \u0003אינה טעונה לבונה\u0004 — בכל זאת הריהי \u0003טעונה שמן, לחם הפנים\u0004 החמור בדינו ממנחת נסכים, \u0003ש\u0004הרי הוא \u0003טעון לבונה\u0004 — \u0003אינו דין ש\u0004יהא גם הוא \u0003טעון שמן!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) במנחת העומר \u0003\"עליה\"\u0004 שהוא לשון מיעוט — דווקא \u0003עליה\u0004 אתה מצווה לתת \u0003שמן, ולא על לחם הפנים\u0004 אתה מצווה לתת \u0003שמן.\u0004 ודנים עוד בכתוב זה שבמנחת העומר.","נאמר עוד בכתוב: \u0003\"ושמת עליה לבנה\"\u0004 והרי המלה \"עליה\" לשון מיעוט היא, וללמד כי דווקא \u0003עליה,\u0004 על מנחת העומר אתה נותן \u0003לבונה, ולא על מנחת נסכים\u0004 נותנים \u0003לבונה.\u0004","ונצרך הכתוב למעט את מנחת נסכים מנתינת לבונה עליה, \u0003ש\u0004כן \u0003יכול\u0004 היה אדם לטעון: \u0003והלא דין הוא\u0004 שתהא מנחת נסכים חייבת בנתינת לבונה עליה, ובאופן זה: \u0003ומה לחם הפנים\u0004 הקל בדינו ממנחת נסכים, \u0003ש\u0004הרי \u0003אינו טעון שמן\u0004 — בכל זאת הריהו \u0003טעון לבונה, מנחת נסכים\u0004 החמורה מלחם הפנים בדינה, \u0003ש\u0004הרי היא \u0003טעונה שמן\u0004 — \u0003אינו דין ש\u0004תהא \u0003טעונה לבונה!\u0004 לכך \u0003תלמוד לומר\u0004 במנחת העומר \u0003\"עליה\"\u0004 שהוא לשון מיעוט — דווקא \u0003עליה\u0004 אתה נותן \u0003לבונה, ולא על מנחת נסכים\u0004 אתה נותן \u0003לבונה.\u0004","ועוד נאמר באותו כתוב שבמנחת העומר \u0003\"מנחה\u0004 היא\" — והרי הכתוב \u0003\"מנחה\" בא\u0004 \u0003לרבות\u0004 (להוסיף) לחיוב לבונה אף את \u0003מנחת\u0004 היום ה\u0003שמיני\u0004 למילואים בחנוכת המשכן במדבר. שכן נאמר שם \"...ומנחה בלולה בשמן\" (ויקרא ט, ד). ואולם חיוב לבונה לא נאמר, לכך נאמר \"מנחה\" \u0003ל\u0004הוסיף את חובת נתינת \u0003לבונה\u0004 עליה. אכן נאמר בסיומו של כתוב זה \"מנחה היא\", והרי הלשון \u0003היא\"\u0004 לשון מיעוט — דווקא מנחת העומר חייבת בשמן ולבונה — \u0003להוציא\u0004 (למעט) את \u0003שתי הלחם\u0004 הבאות בחג השבועות \u0003שלא יטענו\u0004 (שאינן חייבות) \u0003לא\u0004 בנתינת \u0003שמן\u0004 עליהן \u0003ולא\u0004 בנתינת \u0003לבונה\u0004 עליהן.","ולאחר שהובאו בברייתא זו כמה הלכות הנלמדות מהכתוב במנחת העומר, דנים בכל הלכה לעצמה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא כי הכתוב \"ונתת עליה שמן\" בא ללמדנו כי דווקא \u0003עליה\u0004 (על מנחת העומר) אתה מצווה בנתינת \u0003שמן, ולא על לחם הפנים\u0004 אתה מצווה בנתינת \u0003שמן.\u0004 ומקשים: מדוע נמעט מכאן דווקא את לחם הפנים, \u0003אימא\u0004 \u0005[אמור]\u0006 מיעוט אחר: דווקא \u0003עליה\u0004 (על מנחת העומר) אתה נותן \u0003שמן, ולא על מנחת כהנים\u0004 (שהתנדבו לתת מנחה) אתה נותן \u0003שמן!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 שאת \u0003מנחת כהנים הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 שאף עליה נותנים שמן, \u0003שכן\u0004 מנחת כהנים דומה למנחת העומר בצדדים מרובים. ומפרטים את צדדי הדמיון ביניהן: שתיהן באות מ\u0003עשרון\u0004 קמח (בעוד שבלחם הפנים, כל לחם מבין שנים עשר הלחמים שבו בא משני עשרונים). וכן שתיהן נילושות ומתקדשות ב\u0003כלי\u0004 שרת (בעוד שלחם הפנים אינו מתקדש בכלי שרת, אלא באפייתו בתנור בעזרה).","ועוד, ששתיהן נעשות \u0003חוץ\u0004 להיכל, על מזבח החיצון (בעוד שלחם הפנים נעשה על השולחן שבהיכל). \u0003ו\u0004עוד, שבשתיהן נוהג דין עיבור \u0003צורה\u0004 (שינוי מהות), שנפסלו אם עבר עליהן הלילה בלא שקרבו (ואילו לחם הפנים מונח על שולחן הפנים כל ימי השבוע). ועוד, שבשתיהן נוהגת חובת \u0003הגשה\u0004 כנגד הקרן הדרומית-מערבית של המזבח למטה (בעוד שלחם הפנים אינו טעון הגשה למזבח).","\u0003ו\u0004כן שבשתיהן (כבכל המנחות) יש דבר הניתן \u0003ל\u0004\u0003אישים\u0004 (אש המערכה), שמנחת העומר קומצה קרב, ומנחת כהנים קרבה כולה, בעוד שלחם הפנים אינו קרב על המזבח כלל. הרי איפוא ששה צדדי דמיון בין מנחת כהנים למנחת העומר, שאינם קיימים בלחם הפנים. ומשום כך, ריבו את מנחת הכהנים לדין נתינת שמן ולא את לחם הפנים.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 דווקא את \u0003לחם הפנים הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לדין נתינת שמן עליו, ולא את מנחת הכהנים, \u0003שכן\u0004 יש בו צדדי דמיון למנחת \u0005העומר. ומפרטים: שתיהן מנחות\u0006 \u0003ציבורא\u0004 \u0005[ציבור]\u0006 (בעוד שמנחת כהנים היא מנחתם של יחידים). ועוד, ששניהם באים כ\u0003חובה\u0004 ולא בנדבה (כמנחת כהנים). ועוד, ששניהם באים אף ב\u0003טמיא\u0004 \u0005[טומאה],\u0006 שטומאה הותרה בקרבן ציבור (בעוד שמנחת כהנים, שהיא של יחידים, אינה באה בטומאה).","ועוד, שאת שניהם \u0003אכיל\u0004 \u0005[אוכל]\u0006 הכהן (בעוד שמנחת כהנים מוקטרת כולה, ואינה נאכלת). ועוד, שבשניהם נוהג דין \u0003פיגולא\u0004 \u0005[פיגול],\u0006 שנפסלים הם במחשבת הכהן לאוכלם לאחר זמנם (בעוד שאין דין פיגול במנחת כהנים). ועוד, שעבודת שניהם נעשית אף \u0003בשבתא\u0004 \u0005[בשבת],\u0006 מה שאין כן במנחת כהנים. הרי איפוא שאף בלחם הפנים יש ששה צדדי דמיון למנחת העומר, ומדוע איפוא לא נרבה מהכתוב את לחם הפנים שהוא החייב בנתינת שמן עליו, ואילו מנחת כהנים תתמעט מדין זה!","ומשיבים: אף על פי כן \u0003מסתברא\u0004 \u0005[מסתבר],\u0006 יותר לרבות את מנחת כהנים לדין נתינת שמן עליה, שכן בראשיתה של פרשת המנחות (בה הובאה פרשיית מנחת העומר), אמר הכתוב בדין מנחת הסולת \"ו\u0003נפש\u0004 כי תקריב קרבן מנחה לה' סולת יהיה קרבנו\" (ויקרא ב, א), והרי זה בא לרבות כל מנחות יחיד, ובכלל זה מנחת כהנים.","ודנים עוד בדברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: נאמר בכתוב \"ונתן עליה לבונה\" — \u0003עליה\u0004 (על מנחת העומר) אתה מצווה לתת \u0003לבונה ולא על מנחת נסכים\u0004 אתה מצווה לתת \u0003לבונה.\u0004 ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 דרשה זו באופן אחר: \u0003עליה\u0004 אתה מצווה לתת \u0003לבונה, ולא על מנחת כהנים\u0004 אתה מצווה לתת \u0003לבונה!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר ש\u0003מנחת כהנים הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 שתינתן בה לבונה, \u0003שכן\u0004 יש במנחת כהנים כמה צדדי דמיון למנחת העומר. ומפרטים: שתיהן באות מ\u0003עשרון\u0004 אחד של קמח (בעוד מנחת נסכים באה באופנים שונים, שיש בה שלושה עשרונים כשהיא נלוית לקרבן מפר, ושני עשרונים לקרבן מאיל, ועשרון לקרבן מכבש). ועוד, שבשתיהן עשרון הקמח הריהו \u0003בלול בלוג\u0004 שמן אחד (בעוד שבמנחת נסכים נבלל העשרון הבא עם הכבש בשלושה לוגים שמן, ובמנחת נסכים הבאה עם הפר והאיל נבלל כל עשרון בשני לוגים שמן).","ועוד, שבשתיהן נוהג דין \u0003מוגש\u0004 (הגשה) למזבח (מה שאין כן במנחת נסכים). ועוד, ששתיהן באות \u0003בגלל עצם\u0004 (עצמן), שאין מנחת העומר ומנחת הכהנים נלוות לקרבן אחר (מה שאין כן במנחת נסכים הבאה עם קרבן). הרי איפוא ארבעה צדדי דמיון בין מנחת כהנים למנחת העומר, שאינם במנחת נסכים.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מנחת נסכים הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לדין נתינת לבונה, \u0003שכן\u0004 יש בה צדדי דמיון למנחת העומר, שאין במנחת כהנים. ומפרטים: שתיהן מנחות \u0003ציבורא\u0004 \u0005[ציבור]\u0006 (מה שאין כן מנחת כהנים, שהיא מנחת היחיד).","ועוד, שתיהן באות כ\u0003חובה\u0004 (מה שאין כן מנחת כהנים הבאה בנדבה). \u0003ו\u0004עוד, ששתיהן באות אף ב\u0003איטמי\u0004 \u0005[טומאה],\u0006 שהרי טומאה הותרה בקרבן ציבור (מה שאין כן במנחת כהנים). ועוד, ששתיהן נעשות אף \u0003בשבתא\u0004 \u0005[בשבת]\u0006 (מה שאין כן במנחת כהנים). הרי איפוא שיש גם בין מנחת נסכים למנחת העומר ארבעה צדדי דמיון, ותתרבה היא לדין נתינת הלבונה עליה!","ומשיבים: על כל פנים \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר כי מנחת כהנים היא שהתרבתה לענין נתינת הלבונה עליה, שכן בתחילת פרשת המנחות נאמר \u0003\"נפש\"\u0004 (וכדרך שהוסברו הדברים למעלה).","עוד שנינו בברייתא שם: נאמר בכתוב \u0003\"מנחה\"\u0004 — הרי זה בא \u0003לרבות\u0004 אף את \u0003מנחת\u0004 היום ה\u0003שמיני\u0004 למילואים \u0003ל\u0004נתינת \u0003לבונה\u0004 עליה. ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הדבר \u0003להוציא\u0004 (למעט) את מנחת היום השמיני מחובת נתינת לבונה עליה, לומר שאין נותנים בה לבונה? ודוחים בתמיהה: \u0003האי מאי\u0004 \u0005[\u0006הצעה \u0005זו, מה\u0006 מקומה\u0005],\u0006 שכן, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי הכתוב בא \u0003לרבות\u0004 את מנחת היום השמיני למילואים שאף לבונה ניתנת בה — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005]\u0006 שנאמר ריבוי לעניינה, שכן לא הייתי למד דינה של מנחה זו שבאה לשעה בלבד מדינה של מנחת העומר שהיא לדורות, ולא הייתי יודע בה שחייבת בלבונה.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003להוציא\u0004 (למעט) את הלבונה מנתינת לבונה עליה בא הכתוב — \u0003למה לי\u0004 כתוב לשם כך? והרי כלל הוא שדינו של דבר הבא ל\u0003שעה\u0004 (לזמנו בלבד, חד פעמי) \u0003מ\u0004דינו של דבר הבא ל\u0003דורות\u0004 (הקבוע) \u0003לא ילפינן\u0004 \u0005[אין אנו למדים],\u0006 ולא היינו מעלים על דעתנו שמנחת היום השמיני חייבת בלבונה ואין איפוא צורך בכתוב הממעט מהנחה זו.","ועוד שנינו בברייתא כי מהמלה \u0003\"היא\"\u0004 האמורה במנחת העומר למדים אנו \u0003להוציא\u0004 (למעט) את \u0003שתי הלחם, שלא יטענו לא שמן ולא לבונה.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הכתוב \u0003להוציא מנחת כהנים\u0004 מדין שמן ולבונה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לומר ש\u0003מנחת כהנים הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 לדין זה, ולמעט את שתי הלחם, \u0003שכן\u0004 ישנם כמה צדדי דמיון בין מנחת כהנים לבין מנחת העומר, שאינם בשתי הלחם. ומפרטים: שתיהן באות ב\u0003עשרון\u0004 קמח (מה שאין כן שתי הלחם).","ושתיהן מתקדשות בלישתן ב\u0003כלי\u0004 שרת (בעוד ששתי הלחם מתקדשות באפייתן בתנור). ושתיהן באות \u0003מצה,\u0004 שאסורות הן בחימוץ (בעוד ששתי הלחם באים חמץ). \u0003ו\u0004שתיהן באות בגלל \u0003עצם\u0004 (עצמן) ולא מחמת קרבן אחר (בעוד ששתי הלחם באים עם הכבשים בעצרת). ועוד, שבשתיהן נוהג דין \u0003הגשה\u0004 למזבח (מה שאין כן בשתי הלחם). \u0003ו\u0004עוד, ששתיהן ניתנות ל\u0003אישים\u0004 אש המזבח, אם בקומצן ואם כולן (מה שאין כן שתי הלחם שאינם קרבים)","\u0003.\u0004 ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006"],["ראוי לומר כי את \u0003שתי הלחם\u0004 ולא את מנחת הכהנים \u0003הוה ליה לרבויי\u0004 \u0005[היה לו לרבות]\u0006 ממנחת העומר, לענין חיובם בנתינת שמן ולבונה, \u0003שכן\u0004 יש ביניהם צדדי דמיון מרובים. ומפרטים: מנחת העומר ושתי הלחם הריהן קרבנות \u0003ציבור\u0004 (מה שאין כן מנחת כהנים שהיא של יחידים). ועוד, שתיהן באות כ\u0003חובה\u0004 (בעוד שמנחת כהנים באה בנדבה). ועוד, שתיהן קרבות אף ב\u0003טמיא\u0004 \u0005[טומאה],\u0006 שהרי טומאה הותרה בקרבן ציבור (מה שאין כן מנחת כהנים שאינה קרבה בטומאה). ועוד, את שתיהן \u0003אכל\u0004 \u0005[אוכל]\u0006 הכהן (בעוד שמנחת כהנים קרבה כליל על המזבח ואינה נאכלת).","ועוד, בשתיהן נוהג דין \u0003פיגולא\u0004 \u0005[פיגול],\u0006 שמחשבת הכהן בשעת עבודתו בהן לאוכלן חוץ לזמנם הראוי פוסלתן (מה שאין כן במנחת כהנים שאין נוהג בה דין פיגול, שהרי כולה מוקטרת ואין בה כלל אכילה). ועוד, ששתיהן קרבות \u0003בשבתא\u0004 \u0005[בשבת]\u0006 (מה שאין כן מנחת כהנים, שאינה קרבה בשבת). ועוד, שהן מנחת העומר והן שתי הלחם הריהן דבר ה\u0003מתיר\u0004 דברים אחרים (מנחת העומר מתירה את אכילת התבואה החדשה, ושתי הלחם מתירות את הקרבת המנחות הבאות מהתבואה החדשה, מה שאין כן מנחת כהנים שאינה מתירה דבר). ועוד, שבשתיהן נוהג דין ה\u0003תנופה\u0004 (מה שאין כן מנחת כהנים שאין מניפים אותה). ועוד, ששתיהן אינן באות אלא מתבואת ה\u0003ארץ,\u0004 ארץ ישראל (מה שאין כן מנחת כהנים הבאה אף מתבואת חוץ לארץ).","ועוד, שלשתיהן \u0003זמן\u0004 מסויים קבוע להקרבתן (מנחת העומר — למחרת יום ראשון של חג הפסח, ושתי הלחם — בחג השבועות, מה שאין כן מנחת כהנים שאין לה זמן קבוע). ועוד, ששתיהן אינן באות אלא מן יבול התבואה ה\u0003חדש,\u0004 ואילו מנחת כהנים באה אף מן התבואה הישנה. \u0003ו\u0004נמצא איפוא כי \u0003הני\u0004 \u0005[אלה],\u0006 צדדי הדמיון שבין שתי הלחם ומנחת העומר (שמספרם אחד עשר), \u0003נפישן\u0004 \u0005[מרובים]\u0006 הם \u0005מצדדי הדמיון שבין מנחת כהנים ומנחת העומר (שמספרם ששה)!\u0006","ומשיבים: אף על פי כן, \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 יותר לרבות ממנחת העומר את מנחת כהנים לדין חיוב נתינת שמן ולבונה, ולא את שתי הלחם, שכן נאמר בתחילת פרשת מנחת הסולת \"ו \u0003נפש\u0004 כי תקריב קרבן מנחה...\" (ויקרא ב, א), והרי זה מורה שיש לרבות לענין מתן השמן והלבונה את המנחה הבאה מיחידים, כמנחת כהנים, ולא את קרבן הציבור כשתי הלחם.","\u0003ו\u0004כהמשך למה ששנינו בסוף המשנה הקודמת כי אין נותנים שמן ולבונה על מנחת חוטא או על מנחת קנאות (מנחת סוטה). מוסיפים כי העובר ונותן על אחת מן המנחות הללו שמן ולבונה, הריהו \u0003חייב\u0004 מלקות \u0003על\u0004 איסור נתינת \u0003השמן בפני עצמו, ו\u0004כן הריהו \u0003חייב\u0004 מלקות \u0003על\u0004 איסור נתינת ה\u0003לבונה בפני עצמה.\u0004 שכן אלו הם שני איסורים נפרדים. והמנחה עצמה ש\u0003נתן עליה שמן\u0004 — \u0003פסלה\u0004 בכך, שהרי אין הוא יכול לחזור וללקט את השמן שניתן בה. ואולם אם נתן עליה \u0003לבונה\u0004 — \u0003ילקטנה\u0004 את הלבונה מהמנחה, שהדבר ניתן להיעשות, והריהי כשרה בכך.","ועוד באיסור נתינת שמן במנחת חוטא: אין הדבר אסור אלא כשטרם נקמצה המנחה, ואולם מי ש\u0003נתן שמן על שיריה\u0004 של מנחת החוטא, לאחר שכבר נקמצה, ואלה נאכלים לכהנים — \u0003אינו עובר בלא תעשה.\u0004 ועוד בדין נתינת שמן למנחת חוטא: אין נתינת השמן פוסלת אותה אלא רק כאשר ניתן השמן עצמו לתוכה, ואולם אם \u0003נתן כלי\u0004 שבתוכו שמן \u0003על גבי כלי\u0004 שבתוכו המנחה — \u0003לא פסלה\u0004 בכך.","שנינו במשנתנו כי מנחת חוטא נפסלת במתן שמן לתוכה, ואין היא נפסלת במתן לבונה עליה אם חזר ולקט את הלבונה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 נאמר בדינה של מנחת החוטא \"לא ישים עליה שמן ולא יתן עליה לבונה כי חטאת היא\" (שם ה, יא). ודנים: מן הכתוב \u0003\"לא ישים עליה שמן\"\u0004 הנאמר בכתוב זה למדים אנו איסור נתינת שמן, \u0003ו\u0004ש\u0003אם\u0004 עבר ו\u0003שם\u0004 שמן במנחה — \u0003פסל\u0004 אותה בכך.","\u0003יכול\u0004 יהא כן הדין אף באיסור \u0003\"לא יתן עליה לבונה\", ו\u0004ש\u0003אם\u0004 עבר ו\u0003נתן\u0004 עליה לבונה — \u0003פסל\u0004 אותה בכך? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בסוף הפסוק \u0003\"כי חטאת\u0004 היא\" — שאף אם נתן עליה לבונה, עדיין בגדר חטאת היא, שאינה פסולה בכך. ודנים עוד: \u0003יכול\u0004 יהא כן הדין \u0003אף בשמן\u0004 שניתן למנחה, שאין היא נפסלת בכך? לכך \u0003תלמוד לומר\u0004 הלשון \u0003\"היא\"\u0004 (\"מנחה היא\"), למיעוט: דווקא בנתינת הלבונה עליה היא עדיין בכלל חטאת, מה שאין כן בנתינת שמן לתוכה.","ושואלים: \u0003ומה ראית\u0004 (מדוע עדיף) בעיניך לדרוש באופן זה את הכתוב, ו\u0003לפסול\u0004 את המנחה \u0003ב\u0004נתינת \u0003שמן ולהכשיר\u0004 את המנחה \u0003ב\u0004נתינת \u0003לבונה,\u0004 אפשר היה ללמוד באופן הפוך: להכשיר את המנחה בנתינת שמן, ולפסול אותה בנתינת לבונה! ומשיבים: סברה היא, \u0003פוסל אני ב\u0004נתינת \u0003שמן, ש\u0004כן \u0003אי אפשר\u0004 לשוב \u0003ו\u0004\u0003ללקטו\u0004 ולהוציאו מהמנחה, שהרי השמן נספג בקמח בו הוא ניתן, \u0003ומכשיר אני ב\u0004נתינת \u0003לבונה, ש\u0004הרי \u0003אפשר ללוקטה\u0004 ולהוציאה מהמנחה.","\u0003בעא\u0004 \u0005[שאל]\u0006 \u0003רבה בר רב הונא מר' יוחנן:\u0004 אם \u0003נתן עליה\u0004 על מנחת החוטא \u0003לבונה\u0004 ה\u0003שחוקה\u0004 לאבקה דקה, שאי אפשר ללוקטה ולהוציאה, \u0003מהו\u0004 דינה של המנחה, האם נפסלה בכך? וצדדי השאלה: האם הטעם בהכשר המנחה לאחר שנתנה עליה הלבונה הוא \u0003משום\u0004 ש\u0003אפשר ללקטה, ו\u0004אילו \u0003הא\u0004 \u0005[זו],\u0006 \u0003לא אפשר ללקטה,\u0004 ותהא איפוא המנחה פסולה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הטעם שאין המנחה שניתנה עליה לבונה נפסלת \u0003משום דלא מיבלעא\u0004 \u0005[שאין\u0006 הלבונה היבשה \u0005נבלעת,\u0006 נספגת\u0005]\u0006 בתוך קמח המנחה\u0005,\u0006 \u0003ו\u0004לפי טעם זה, \u0003הא\u0004 \u0005[זו]\u0006 הלבונה השחוקה שניתנה על המנחה, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מיבלעא\u0004 \u0005[לא נבלעת]\u0006 במנחה, ותהא המנחה כשרה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 פתרון לשאלה ממה ששנינו במשנתנו \u0003\"ולבונה\u0004 שניתנה על המנחה \u0003ילקטנה\",\u0004 וכשרה בכך. הרי שהכשר המנחה תלוי בליקוט, ולבונה שחוקה שאינה יכולה להילקט, פוסלת נתינתה את המנחה!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 התנא במשנתנו בסגנון \u0003\"חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 \u0003ועוד\u0004 טעם\" \u0003קאמר\u0004 \u0005[הוא אומר,\u0006 שונה דבריו\u0005],\u0006 שיש שני טעמים בדבר, האחד (שלא הזכירו במפורש) ועוד טעם שני. ואף כאן, אמר התנא כי יש שני טעמים להתיר את המנחה שניתנה עליה לבונה: טעם \u0003חדא\u0004 \u0005[אחד],\u0006 הריהו משום ש\u0003לא\u0004 פסלה התורה את המנחה שניתן עליה דבר האסור בנתינה, אלא בנתינה ש\u0003מיבלעא\u0004 \u0005[נבלעת]\u0006 בה, ולכך אין נתינת הלבונה (אף השחוקה) פוסלת, שהרי אינה נבלעת במנחה. \u0003ועוד\u0004 טעם שאין המנחה נפסלת בנתינת לבונה עליה, שהרי יכול הוא ש\u0003ילקטנה,\u0004 ותחזור המנחה לכמות שהיתה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון \u0005לבעיה ממה ששנינו בברייתא שהובאה למעלה\u0006 \u0005:\u0006 \u0003מכשיר אני בלבונה,\u0004 משום \u0003שאפשר ללוקטה,\u0004 ומכאן שהכשרה של המנחה שנתנו לבונה עליה, אינו אלא משום שאפשר ללוקטה, ואילו לבונה שחוקה, שאי אפשר ללוקטה — פסולה. ודוחים: אין זו ראיה, שכן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר כדרך שאמרנו כי התנא בברייתא בסגנון \u0003\"חדא\u0004 \u0005[אחד]\u0006 \u0003ועוד\" קא אמר\u0004 \u0005[הוא אומר,\u0006 שונה דבריו\u0005],\u0006 והנימוק שאפשר ללוקטה הוא הסבר נוסף, ואולם הנימוק הראשון הוא שאין היא נאסרת אלא בדבר הנבלע בה, ולפי טעם זה — אף בנתינת לבונה שחוקה, אינה נאסרת.","ושואלים: אם כן \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 כיצד הוכרעה\u0005]\u0006 בעייתו זו של רבה בר רב הונא? \u0003אמר רב נחמן בר יצחק, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנחת חוטא ומנחת קנאות שנתן עליה לבונה\u0004 — \u0003מלקט את הלבונה, וכשרה. ואם עד שלא\u0004 (בטרם) \u0003ליקט\u0004 את \u0003לבונתה חישב\u0004 (חשב) \u0003עליה\u0004 הכהן העובד בה להקטיר את קומצה או לאכול את שייריה \u0003בין\u0004 \u0003חוץ לזמנו\u0004 הראוי, \u0003בין\u0004 \u0003חוץ למקומו\u0004 הראוי — בכך עשאה קרבן \u0003פסול, ו\u0004אולם \u0003אין בו\u0004 באכילתו חיוב \u0003כרת\u0004 כשאר קרבן שהתפגל משום מחשבת אכילה חוץ לזמנו.","וטעם הדבר: שהרי בשעה שחשב מחשבת פסול זו, לא היתה המנחה כשרה (שהרי יש עליה לבונה). \u0003ו\u0004אכן \u0003אם מש\u0004כבר \u0003ליקט\u0004 (לאחר שליקט) את \u0003לבונתה מחשב עליה\u0004 מחשבת פסול של עבודה או אכילה \u0003חוץ למקומו \u0004 — הרי דינו כמו בשאר מחשבת חוץ כזו ש\u0003פסול\u0004 הקרבן \u0003ו\u0004אולם \u0003אין בו\u0004 באכילתו \u0003כרת.\u0004 ואם חשב עליה מחשבת פסול של עבודה או אכילה \u0003חוץ לזמנו\u0004 — הרי זה כשאר \u0003פיגול,\u0004 שנפסל בכך הקרבן, \u0003וחייבין עליו כרת.\u0004 למדנו איפוא מדברי ברייתא זו שכל עוד הלבונה נמצאת על המנחה, הרי המנחה פסולה, ומכאן שטעם הכשרה של המנחה שניתנה עליה לבונה הוא משום ליקוט הלבונה, ולא מטעם שאין דבר שאינו בלוע פוסל את המנחה. ונפתרה בכך בעייתו של רבה בר רב הונא, והנותן לבונה שחוקה על לבונה — פסלה בכך.","בברייתא שהובאה למעלה שנינו שמחשבת פסול במנחה, בזמן שיש עליה לבונה, פוסלת אותה. ושואלים: \u0003ותיהוי\u0004 \u0005[ושתיחשב]\u0006 מנחה זו שניתנה עליה לבונה, כמנחה שניתן עליה מ\u0003פך\u0004 שמן, שנפסלה בכך, ושוב אין מחשבת פסול פועלת בה, \u0003ואמאי פסלה\u0004 \u0005[ומדוע פוסלת]\u0006 \u0003ב\u0004מנחה שניתנה עליה לבונה \u0003מחשבה\u0004 של פסול, והלא כל עוד לא ליקטו את הלבונה מעליה \u0003דחוי הוא\u0004 הקרבן מקדושה!","\u0003אמר אביי:\u0004 אף על פי שפסולה היא המנחה בזמן שנתונה עליה לבונה, עדיין \u0003\"חטאת\" קרייה רחמנא\u0004 \u0005[קראה אותה התורה],\u0006 ולכך פועלת בה מחשבת פסול באותה עת. \u0003רבא אמר\u0004 הסבר אחר: ברייתא \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 — כשיטת \u0003חנן המצרי הוא, דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו מקבל\u0005]\u0006 כלל מושג זה של \u0003דחויין\u0004 בקדשים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינם של שני שעירי יום הכיפורים, \u0005האחד הקרב לה' לאחר שנשחט, והשני הנשלח לעזאזל\u0006\u0005,\u0006 \u0003חנן המצרי אומר:\u0004 אם מת השעיר המשתלח לעזאזל, \u0003אפילו\u0004 מת משכבר נשחט השעיר הפנימי, וה\u0003דם\u0004 העומד לזריקה כבר נתון \u0003בכוס\u0004 ועומד להיזרק על המזבח — אין השעיר הפנימי נדחה ולכן אין אותו הדם נדחה מזריקה. ומה עושים? \u0003מביא חבירו\u0004 (שעיר אחר להשתלח), ובוחר אותו (שלא כמו השעיר הראשון שאבד) \u0003שלא בהגרלה\u0004 בין שני שעירים, \u0003ומזווג\u0004 את השעיר החדש כבן זוג \u0003לו,\u0004 לשעיר הנשחט, וזורק את הדם כראוי.","\u0003רב אשי אמר\u0004 הסבר אחר, שכן כלל הוא: \u0003כל\u0004 דבר \u0003שבידו\u0004 לתקן — \u0003לא הוי\u0004 \u0005[אין בו]\u0006 דין \u0003דחוי,\u0004 ואף כאן, כיון שבידו לחזור וללקט את הלבונה מעל המנחה, אין היא נחשבת כדחויה מן הקדשים, ולכך תופסת בה מחשבת פסול של הכהן.","ולאחר שהובאו הסבריהם של אביי, רבא ורב אשי, \u0003אמר רב אדא: כוותיה\u0004 \u0005[כמותו,\u0006 כהסברו\u0005]\u0006 של \u0003רב אשי\u0004 שאין דיחוי במקום שבידו לתקן את הדבר \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר. \u0003דמאן\u0004 \u0005[ש\u0006כן \u0005מיהו]\u0006 החכם ש\u0003שמעת ליה דאית ליה\u0004 \u0005[\u0006ש\u0005שמעת אותו שיש לו,\u0006 שסבור הוא שיש דין\u0003]\u0004 \u0003דחויין?\u0004 הלא שיטת \u0003ר' יהודה היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ועוד אמר ר' יהודה:\u0004 אם \u0003נשפך הדם\u0004 של שעיר יום הכיפורים המוקרב לה' — \u0003ימות\u0004 בן זוגו, השעיר \u0003המשתלח\u0004 לעזאזל, וכן אם \u0003מת\u0004 השעיר \u0003המשתלח\u0004 קודם שנזרק דם השעיר הקרב לה' — \u0003ישפך הדם.\u0004 \u0003הרי שסבור ר' יהודה כי השעיר המשתלח (או במקרה השני, דם השעיר הקרב) נדחה לגמרי.\u0004","\u0003ואילו היכא\u0004 \u0005[היכן,\u0006 באופן\u0005]\u0006 ש\u0003בידו\u0004 לתקן, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 לאחר שנשחטו קרבנות הפסח בעזרה, \u0003כוס היה ממלא\u0004 הכהן \u0003מדם התערובות\u0004 שעל הרצפה, \u0003וזרקו זריקה אחת\u0004 על המזבח \u0003כנגד היסוד\u0004 כדינו של קרבן פסח. שאם נשפך דמו של אחד מן הקרבנות לרצפה, יוכשר בדרך זו. משמע מכאן, שלמרות שנשפך הדם מן הכלי בתחילה ולכאורה נדחה, כיון שבידו לתקן את הדבר — אין זה נחשב דיחוי.","ועוד בדיני נתינת שמן על מנחת חוטא (או על מנחת סוטה), \u0003אמר רב יצחק בר יוסף, אמר ר' יוחנן:\u0004 אם \u0003נתן\u0004 שיעור \u0003משהו שמן על גבי\u0004 \u0003כזית\u0004 מן ה\u0003מנחה\u0004 של חוטא — \u0003פסל\u0004 בכך את המנחה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן נאמר באיסור נתינת שמן במנחת חוטא \u0003\"לא ישים\u0004 עליה שמן\", ולשון זו של \u0003שימה\u0004 אין לה שיעור, והריהי אף בשיעור \u0003כל דהו\u0004 \u0005[שהוא].\u0006 \u0005וממה שנאמר בכתוב זה הלשון\u0006 \u0003\"עליה\",\u0004 למדנו שאין המנחה נפסלת בנתינת שמן עליה אלא \u0003עד דאיכא שיעורא\u0004 \u0005[שיש\u0006 בה \u0005שיעור]\u0006 ראוי שהוא כזית.","\u0003ו\u0004עוד הלכה בדין נתינת לבונה על מנחת חוטא \u0003אמר רב יצחק בר יוסף, אמר ר' יוחנן:\u0004 אם \u0003נתן כזית לבונה על גבי\u0004 כשיעור \u0003משהו\u0004 ב\u0003מנחה\u0004 של חוטא — \u0003פסל\u0004 בכך את המנחה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן בכתוב זה \u0003\"לא יתן\u0004 עליה לבונה\" \u0003כתיב\u0004 \u0005[נאמר]\u0006 — ללמדנו, שאין היא אסורה אלא \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 בה כשיעור \u0003נתינה,\u0004 שהוא לפחות בכזית. ואולם מה שנאמר עוד בכתוב זה הלשון \u0003\"עליה\",\u0004"],["\u0003הוי\u0004 \u0005[הינה]\u0006 לשון המורה על ריבוי, ואם כן, הרי לפנינו בכתוב זה לשון \u0003רבוי אחר\u0004 לשון \u0003רבוי,\u0004 אחד בענין השמן ואחד בענין הלבונה, \u0003ו\u0004כלל הוא בידינו: \u0003אין רבוי אחר רבוי\u0004 בא \u0003אלא למעט,\u0004 ומכאן למדנו שנתינת לבונה אפילו על מנחה בשיעור כל שהוא, פוסלת אותה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת אותה הלכה ש\u0003אמר רב יצחק בר יוסף\u0004 בשמו של ר' יוחנן. לא היתה זו הלכה פסוקה אלא \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן:\u0004 אם עבר אדם ו\u0003נתן משהו שמן על גבי כזית מנחה\u0004 של חוטא, \u0003מהו\u0004 דינה של המנחה להיפסל בכך? וצדדי השאלה: כיון שאמרה התורה באיסור נתינת שמן על מנחת חוטא בלשון \"לא ישים עליה שמן\" (ויקרא ה, יא), ובאיסור נתינת הלבונה אמר אותו כתוב \"ולא יתן עליה לבונה\", ויש לדון: \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 בדין ה\u0003שימה\u0004 של השמן שיהא \u0003כ\u0004דין ה\u0003נתינה\u0004 של הלבונה, שהיא בכזית דווקא, \u0003או לא?\u0004 ומסכמים: לבעיה זו לא נמצא פתרון, ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","שנינו במשנתנו כי מי ש\u0003נתן שמן על שיריה\u0004 של מנחת חוטא — אינו עובר בכך. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממשמעות הכתוב \u0003\"לא ישים עליה שמן ולא יתן\u0004 עליה לבונה\", \u0003יכול\u0004 היה הלומד לומר כי רק \u0003ב\u0004אופן בו \u0003שני כהנים\u0004 עובדים במנחת החוטא, שהאחד נתן עליה את השמן והאחר נתן עליה את הלבונה, כל אחד מהם חייב מלקות. ואולם אם כהן אחד עשה את שתי הפעולות הללו — הריהו מתחייב רק פעם אחת מלקות.","לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בפסוק \u0003\"עליה\"\u0004 הן באיסור שימת שמן והן באיסור נתינת הלבונה, כי \u0003בגופה של\u0004 ה\u0003מנחה הכתוב מדבר, ולא בכהן\u0004 העושה אותם. וכיון שבמנחה זו נעשו שתי פעולות האיסור — מתחייב העושה אותם בשתי סדרות מלקות, גם אם היה זה כהן אחד שעשה את שתיהן.","ועוד, שמא \u0003יכול\u0004 הלומד לומר כי בכלל איסורים אלה אף ש\u0003לא יתן כלי\u0004 שבו שמן או לבונה \u0003על גבי כלי\u0004 שבו נמצאת מנחת החוטא, \u0003ואם\u0004 עבר ו\u0003נתן\u0004 כלי בו שמן או לבונה על גבי המנחה — \u0003פסל\u0004 אותה בכך? לכך \u0003תלמוד לומר \"עליה\"\u0004 — דווקא \u0003בגופה של מנחה הכתוב מדבר\u0004 שאין לתת עליה ממש שמן או לבונה, ולא כלי שבו שמן או לבונה על כלי שבו נמצאת המנחה.","\u0003יש\u0004 מנחות ש\u0003טעונות\u0004 (חייבות) קודם קמיצתן \u0003ב\u0004\u0003הגשה\u0004 של הכלי בו הן נמצאות אל חודה של הקרן הדרומית-מערבית של המזבח, \u0003ו\u0004אולם \u0003אין טעונות תנופה\u0004 (שיניפו אותן). ויש שחייבות הן ב\u0003הגשה ו\u0004הן ב\u0003תנופה.\u0004 ויש שחייבות ב\u0003תנופה ולא\u0004 ב\u0003הגשה,\u0004 ויש שאינן חייבות \u0003לא\u0004 ב\u0003תנופה ולא\u0004 ב\u0003הגשה. ו\u0004מפרטים:","\u0003אלו\u0004 הן המנחות ה\u0003טעונות הגשה ואין טעונות תנופה: מנחת הסולת, ו\u0004מנחת \u0003המחבת, ו\u0004מנחת ה\u0003מרחשת, והחלות\u0004 של מנחת מאפה תנור, \u0003והרקיקין\u0004 של מנחת מאפה \u0003תנור, ו\u0004\u0003מנחת כהנים\u0004 המתנדבים להביא אחת מאלה, \u0003ומנחת כהן משיח\u0004 (חביתי כהן גדול), \u0003ו\u0004\u0003מנחת גוים\u0004 שנדבו מנחה, וכן \u0003מנחת נשים, ומנחת חוטא.\u0004","\u0003ר' שמעון אומר: מנחת כהנים ומנחת כהן משיח אין בהן\u0004 חיוב \u0003הגשה.\u0004 וטעם הדבר: \u0003לפי שאין\u0004 נוהגת \u0003בהן קמיצה\u0004 הבאה לייחד את החלק העולה למזבח, ולהתיר את שאר המנחה לאכילת כהנים (שהרי הן עולות כליל על המזבח), \u0003וכל\u0004 המנחות \u0003שאין בהן קמיצה\u0004 אף \u0003אין בהן הגשה.\u0004","\u0003אמר רב פפא\u0004 כלל הוא בלשון משניות מסכת מנחות (ובכלל זה משנתנו): \u0003כל היכא\u0004 \u0005[מקום]\u0006 במסכתנו \u0003דתנן\u0004 \u0005[ששנינו]\u0006 בו \"מנחות\" — במנחות הבאות ב\u0003עשר\u0004 דומות (שיש בהן עשרה לחמים או עשרה רקיקים) \u0003תנן\u0004 \u0005[שנינו].\u0006 ואין יותר. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 רב פפא, \u0005משמיע לנו]\u0006 בכך?","ומסבירים: דברים אלה של רב פפא באו \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שהנודר להביא מנחת מאפה, מביא עשרה לחמים, ואולם סוג הלחמים תלוי ברצונו: שיכול הוא להביאה לחמים או רקיקים, ואם רצה להביא \u0003מחצה\u0004 (חמש מהן) \u0003חלות ומחצה\u0004 (וחמש אחרות) \u0003רקיקין\u0004 — \u0003יביא,\u0004 ולכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 רב פפא, \u0005משמיע לנו]\u0006 ש\u0003לא\u0004 כך סבורה משנתנו, ו\u0003עשרת הלחמים באים רק מאותו הסוג.\u0004","שנינו במשנתנו שנחלקו חכמים ור' שמעון בדינן של מנחת כהנים ומנחת כהן משיח אם חייבות בהגשה. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה מקור הדברים\u0005]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בדינה של מנחת המרחשת \"והבאת את המנחה אשר יעשה \u0005מאלה לה' והקריבה אל הכהן והגישה אל המזבח\" (ויקרא ב, ח):\u0006 \u0003אילו\u0004 היה \u0003נאמר\u0004 בכתוב רק \u0003\"והבאת אשר יעשה מאלה לה' והקריבה אל הכהן והגישה\"\u0004 ולא היה נאמר \"המנחה\" — \u0003הייתי אומר: אין לי\u0004 מכאן \u0003שטעון הגשה אלא\u0004 ה\u0003קומץ\u0004 הקרב על המזבח \u0003בלבד,\u0004 ואולם ה","\u0003מנחה\u0004 קודם שנקמצת, \u0003מנין\u0004 לי שחייבת בהגשה למזבח? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בייתור לשון \"ה \u0003מנחה\"\u0004 — שכל המנחה חייבת בהגשה למזבח. ושואלים עוד: אין לי בכתוב זה אלא דין הגשה במנחת מרחשת, חובת הגשה אף ב\u0003מנחת חוטא מנין\u0004 לי? \u0003תלמוד לומר\u0004 עוד בכתוב \u0003\"את המנחה\"\u0004 — לרבות אף את מנחת החוטא לדין הגשה.","ושואלים: מדוע נצרך כתוב ללמדנו דין הגשה במנחת חוטא, \u0003ו\u0004הרי דבר הנלמד מ\u0003דין\u0004 (קל וחומר) \u0003הוא\u0004 זה. ומפרטים: \u0003נאמר הכא\u0004 \u0005[כאן],\u0006 במנחת חוטא"],["שיש להביאה, והריהי איפוא \u0003מנחת חובה, ונאמר הכא\u0004 \u0005[כאן]\u0006 במנחת מרחשת, שהיא \u0003מנחת נדבה.\u0004 ומעתה נאמר: \u0003מה מנחת נדבה\u0004 כמנחת המרחשת — \u0003טעונה הגשה, אף מנחת חובה\u0004 כמנחת החוטא — \u0003טעונה הגשה!\u0004","ואולם השווואה זו ניתנת לפירכה: \u0003מה למנחת נדבה\u0004 החייבת בהגשה, \u0003שכן\u0004 יש בה צד מעלה, ש\u0003טעונה\u0004 נתינת \u0003שמן ולבונה\u0004 עליה, מה שאין כן מנחת חוטא! ומשיבים: \u0003מנחת סוטה תוכיח,\u0004 שאף בה אין נתינת שמן ולבונה, וחייבת בהגשה!","ודוחים: אין ללמוד מנחת חוטא ממנחת סוטה לענין הגשה, שהרי יש צד מעלה במנחת סוטה, שכן \u0003מה למנחת סוטה,\u0004 החייבת בהגשה, \u0003שכן\u0004 \u0003טעונה תנופה,\u0004 מה שאין כן מנחת חוטא! ומשיבים: \u0003מנחת נדבה תוכיח,\u0004 שאף שאין בה דין תנופה, נוהג בה דין הגשה. ונאמר כן שמנחת חוטא תנהג בה הגשה, אף שאין בה תנופה.","ומסכמים: \u0003וחזר הדין,\u0004 כלומר, חוזרת ההוכחה למקומה, שהרי \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 כל אחת מן ההוכחות אינה דומה לחברתה, שיש בה צד חמור יותר, אבל צד דמיון שווה לכולם, ו\u0003הצד השוה שבהן,\u0004 במנחת נדבה ובמנחת סוטה — \u0003ש\u0004שתיהן \u0003שוו\u0004 בדינן \u0003ל\u0004ענין חובת ה\u0003קמיצה\u0004 בהן, \u0003ו\u0004כן \u0003שוו\u0004 בדינן \u0003ל\u0004חובת \u0003הגשה, אף אני אביא\u0004 (ארבה) את \u0003מנחת חוטא ששוה להן ל\u0004חובת ה\u0003קמיצה,\u0004 ש\u0003תשוה להן\u0004 אף \u0003להגשה!\u0004","ודוחים: אינך יכול לומר כן, שהרי \u0003מה להצד השוה שבהן,\u0004 בין מנחת נדבה ומנחת סוטה, \u0003שכן\u0004 שתיהן \u0003הוכשרו\u0004 (ראויות) \u0003לבא בעשיר כבעני, תאמר במנחת חוטא שלא הוכשרה לבא בעשיר כבעני,\u0004 שהרי אין מנחה זו אלא של העני בלבד, \u0003תלמוד לומר\u0004 (מלמדנו האמור), הכתוב היתר במנחת המרחשת \u0003\"את המנחה\"\u0004 (ויקרא ב, ח) — לרבות את מנחת חוטא לדין ההגשה.","ומוסיף \u0003ר' שמעון\u0004 על דברי חכמים בדין הגשה במנחות, ו\u0003אומר,\u0004 נאמר במנחת המרחשת: \"והבאת את המנחה אשר יעשה מאלה והקריבה אל הכהן והגישה אל המזבח. והרים הכהן מן המנחה את אזכרתה והקטיר המזבחה אשה ריח ניחוח לה' \" (שם ח— ט). ומן הכתוב \u0003\"והבאת\"\u0004 יש \u0003לרבות\u0004 אף את \u0003מנחת העומר ל\u0004חובת \u0003הגשה\u0004 למזבח. ש\u0003כן\u0004 במנחת העומר \u0003הוא אומר\u0004 לשון \"הבאה\": \u0003\"והבאתם את עמר ראשית קצירכם אל הכהן\"\u0004 (שם כג, י). והאמור במנחת המרחשת \u0003\"והקריבה\"\u0004 בא \u0003לרבות\u0004 אף את \u0003מנחת סוטה ל\u0004חובת \u0003הגשה\u0004 למזבח. ש\u0003כן\u0004 במנחת סוטה \u0003הוא אומר\u0004 לשון \"הקרבה\": \"ולקח הכהן מיד האשה את מנחת הקנאות והניף את המנחה לפני ה' \u0003והקריב אתה אל המזבח\"\u0004 (במדבר ה, כה).","ודנים בהלכה זו: \u0003ו\u0004הלא דבר הנלמד מן ה\u0003דין\u0004 (קל וחומר) \u0003הוא\u0004 זה. ובאופן זה: \u0003ומה מנחת חוטא\u0004 שיש בה צד קל, \u0003ש\u0004כן \u0003אינה טעונה תנופה\u0004 — הריהי \u0003טעונה הגשה. מנחת סוטה,\u0004 שיש בה צד חמור, \u0003ש\u0004כן היא \u0003טעונה תנופה\u0004 — \u0003אינו דין ש\u0004תהא \u0003טעונה הגשה!\u0004 ודוחים: יש לפרוך קל וחומר זה, שכן יש צד חמור במנחת חוטא ממנחת סוטה, \u0003מה למנחת חוטא שכן\u0004 היא \u0003באה\u0004 מן ה\u0003חיטין\u0004 שהן משובחות, מה שאין כן במנחת סוטה הבאה מן השעורים, הפחותות!","ודוחים: \u0003מנחת העומר תוכיח,\u0004 שאף שהיא באה מן השעורים, בכל זאת היא חייבת בהגשה ויהא כן אף דין מנחת סוטה! ומשיבים: אין להביא ראיה ממנחת העומר למנחת סוטה, שכן מנחת העומר דינה חמור משל מנחת סוטה, שהרי \u0003מה למנחת העומר\u0004 שנוהג בה דין הגשה, \u0003שכן\u0004 חמורה היא שהרי \u0003טעונה שמן ולבונה,\u0004 בעוד שמנחת סוטה אין ניתנים בה שמן ולבונה. ודוחים: \u0003מנחת חוטא תוכיח\u0004 שאין בה שמן ולבונה, ובכל זאת חייבת בהגשה.","ומסכמים: \u0003וחזר הדין,\u0004 כלומר, חוזרת ההוכחה למקומה, שהרי \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 כל אחת מן ההוכחות אינה דומה לחברתה, שיש בה צד חמור יותר, אבל \u0003הצד השוה שבהן,\u0004 בשתי המנחות הללו, מנחת העומר ומנחת חוטא, \u0003ששוו\u0004 שתיהן \u0003ל\u0004חובת ה\u0003קמיצה ושוו ל\u0004חובת ה\u0003הגשה. אף אני אביא\u0004 את \u0003מנחת סוטה\u0004 כיון \u0003ששוותה להן לקמיצה\u0004 — \u0003תשוה להן\u0004 גם \u0003להגשה!\u0004","ודוחים: אינך יכול לומר כן, שהרי \u0003מה להצד השוה שבהן\u0004 במנחת העומר ומנחת חוטא — שיש בהן צד חמור, \u0003שכן\u0004 שתיהן \u0003לא הוכשרו\u0004 (ראויות) \u0003לבא קמח\u0004 אלא סולת (הקמח המנופה היטב) בלבד, \u0003תאמר\u0004 שיהא כן הדין ב\u0003מנחת סוטה\u0004 הקלה מהן בדינה, \u0003שהוכשרה לבא קמח?\u0004 לכך \u0003תלמוד לומר\u0004 הכתוב היתר בפרשת מנחת המרחשת \u0003\"והקריבה\"\u0004 לרבות את מנחת הסוטה להגשה. מקודם נאמר כי ר' שמעון לומד מלשון \"הבאה\" האמורה בכתוב (\"והבאת\") שבפרשת מנחת מרחשת את דינה של מנחת העומר להגשה, שכן אף בה נאמרה לשון \"הבאה\".","ואילו \u0003ר' יהודה אומר\u0004 כי האמור \u0003\"והבאת\"\u0004 בא \u0003לרבות\u0004 את \u0003מנחת סוטה להגשה,\u0004 ש\u0003כן\u0004 במנחת הסוטה \u0003הוא אומר\u0004 לשון \"הבאה\": \"והביא האיש את אשתו אל הכהן \u0003והביא את קרבנה עליה\u0004 עשירית האיפה קמח שעורים... כי מנחת קנאות היא מנחת זכרון מזכרת עון\" (שם ה, טו).","\u0003אבל מנחת העומר לא צריכא קרא\u0004 \u0005[לא צריכה פסוק]\u0006 ללמדנו שחייבת היא בהגשה, \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 שכן הלכה זו, \u0003מדינא קא אתיא\u0004 \u0005[מן הדין,\u0006 מקל וחומר היא \u0005באה,\u0006 נלמדת\u0005],\u0006 ובאופן זה: \u0003ומה מנחת חוטא\u0004 שיש בה צד קל, \u0003ש\u0004כן היא \u0003אינה טעונה תנופה\u0004 — \u0003הריהי\u0004 \u0003טעונה\u0004 בכל זאת \u0003הגשה.\u0004 \u0003מנחת העומר\u0004 שיש בה צד \u0003חמור,\u0004 \u0003ש\u0004כן \u0003טעונה תנופה\u0004 — \u0003אינו דין שטעונה הגשה!\u0004","ודוחים: קל וחומר זה ניתן לפירכה: \u0003מה למנחת חוטא שכן\u0004 יש בה צד חמור, ש\u0003באה חיטין,\u0004 ואילו מנחת העומר קלה שבאה מן השעורים! ומשיבים: \u0003מנחת סוטה תוכיח,\u0004 שאף שבאה מן השעורים חייבת בהגשה. ודוחים: אין להוכיח ממנחת סוטה, \u0003שכן\u0004 \u0003מה למנחת סוטה\u0004 שיש בה דין מיוחד, \u0003שכן\u0004 היא \u0003באה לברר עו‍ן\u0004 (אם זנתה האשה), שכן \u0003\"מזכרת עו‍ן\" היא\u0004 נקראת בכתוב! ואומרים: אם כן \u0003מנחת חוטא תוכיח\u0004 שאינה באה לברר עוון, וחייבת בהגשה.","\u0003וחזר הדין,\u0004 כלומר, חוזרת ההוכחה למקומה, \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 שיש אמנם בכל הלכה שהובאה כהוכחה צד חמור שאין בהלכה הנלמדת, ואולם \u0003הצד השוה שבהן,\u0004 בשתי ההלכות שהובאו כהוכחה — \u0003שכן\u0004 שתיהן \u0003שוו\u0004 בדין \u0003ל\u0004ענין \u0003ה\u0004\u0003קמיצה\u0004 בהן, \u0003ו\u0004כמו כן הן \u0003שוו\u0004 בדינן \u0003ל\u0004ענין ה\u0003הגשה. אף אני אביא\u0004 ללמוד מכאן את \u0003מנחת העומר ששוותה להן ל\u0004ענין \u0003ה\u0004\u0003קמיצה,\u0004 ש\u0003תשוה להן\u0004 גם \u0003ל\u0004ענין ה\u0003הגשה.\u0004","ונמצא שלמדנו דין הגשה במנחת העומר ממנחת סוטה וממנחת חוטא, \u0003ומאי פרכת\u0004 \u0005[ובמה אתה פורך,\u0006 דוחה, \u0005אותו]?!\u0006 אין לכך פירכה, ומדוע היה צריך ר' שמעון ללמוד את דין הגשה במנחת העומר מהכתוב \"והבאת\"? ומשיבים: \u0003ר' שמעון פריך הכי\u0004 \u0005[פורך\u0006 לימוד זה \u0005כך]:\u0006 \u0003מה להצד השוה שבהן,\u0004 במנחת סוטה ובמנחת חוטא, \u0003שכן\u0004 בשתיהן יש צד חמור שאין במנחת העומר, שהן מהדברים ה\u0003מצויין\u0004 תמיד, שיכולות לבוא פעמים רבות במהלך ימות השנה, תאמר במנחת העומר שאינה אלא פעם אחת בשנה!","ושואלים: \u0003ור' יהודה,\u0004 שלמד ממנחת סוטה וממנחת חוטא, מה הוא משיב על פירכה זו? — לדעתו אין זו פירכה, שכן \u0003אדרבה\u0004 \u0005[להיפך]\u0006 הוא, שהרי \u0003הא\u0004 \u0005[זו,\u0006 מנחת העומר\u0005]\u0006 היא \u0003מצוייה טפי\u0004 \u0005[יותר]\u0006 מאשר מנחת סוטה ומנחת חוטא, שכן מנחת העומר בוודאי באה פעם אחת בשנה, ואילו \u0003הנך\u0004 \u0005[הללו],\u0006 מנחת חוטא ומנחת סוטה, \u0003זימנין\u0004 \u0003דלא משכחת לה\u0004 \u0005[פעמים שאין מוצא אתה אותם]\u0006 \u0003כלל,\u0004 אם אין חוטאים, ואין נשים נחשדות. ושבים אל המשך דברי הברייתא.","\u0003או\u0004 אפשר לומר ש\u0003אינו אומר\u0004 הכתוב \u0003\"והבאת\"\u0004 לרבות חיוב הגשה, \u0003אלא\u0004 לענין אחר: \u0003ש\u0004ה\u0003יחיד\u0004 (אדם מישראל) \u0003מתנדב ומביא\u0004 אף \u0003מנחה אחרת\u0004 הבאה מן \u0003השעורים (כמנחת העומר),\u0004 \u0003חוץ מאלה\u0004 חמש המנחות \u0003ש\u0004הזכירן הכתוב \u0003בענין\u0004 (באותה פרשה, ויקרא ב, א— יג: מנחת סולת, מנחת מחבת, מנחת מרחשת, חלות שבמנחת מאפה תנור, ורקיקין שבמנחת מאפה תנור), שכולן באות מחיטים.","\u0003ו\u0004לכאורה הרי דבר זה ב\u0003דין\u0004 (היקש) \u0003הוא\u0004 נלמד, ובזה האופן: כשם ש\u0003ציבור מביא מנחה מן החיטין\u0004 כ\u0003חובה\u0004 שתי הלחם, \u0003ו\u0004הריהו \u0003מביא מנחה מן השעורין\u0004 כ\u0003חובה\u0004 (מנחת העומר). \u0003אף יחיד שמביא\u0004 ככלל \u0003מנחה מן החיטין\u0004 כ\u0003נדבה, יכול\u0004 ש\u0003יביא מנחה מן השעורין\u0004 גם כן ב\u0003נדבה!\u0004 לכך \u0003תלמוד לומר \"אלה\"\u0004 (\"והבאת את המנחה אשר יעשה מאלה\") — \u0003אין לי\u0004 בנדבת מנחה של היחיד \u0003אלא\u0004 את חמש המנחות ה\u0003אלה\u0004 בלבד.","ומקשים: \u0003או אינו אומר \"אלה\"\u0004 \u0003אלא\u0004 למעט דבר אחר, \u0003ל\u0004נודר מנחה ו\u0003אומר \"הרי עלי מנחה\",\u0004 בלא שאמר במפורש איזו מנחה נדר — \u0003שמביא\u0004 את \u0003חמישתן?\u0004 לכך \u0003תלמוד לומר \"מאלה\"\u0004 — \u0003רצה\u0004 הנודר, מנחה \u0003אחת\u0004 הוא \u0003מביא, רצה\u0004 הנודר, את \u0003חמישתן\u0004 הוא \u0003מביא.\u0004 ועוד בדברי הברייתא.","\u0003ר' שמעון אומר:\u0004 מה שנאמר בכתוב שבמנחת המרחשת \u0003\"את המנחה\"\u0004 בא \u0003לרבות\u0004 אף \u0003את\u0004 \u0003שאר\u0004 ה\u0003מנחות, כגון מנחת גוים,\u0004 ו\u0003מנחת נשים\u0004 לחיוב \u0003הגשה.\u0004 ויש לשאול: \u0003יכול שאני מרבה\u0004 מכתוב זה לענין הגשה \u0003אף\u0004 את \u0003שתי הלחם ו\u0004את \u0003לחם הפנים?\u0004 לכך \u0003תלמוד לומר\u0004 לשון הכתוב \u0003\"מאלה\"\u0004 למעט, שאין כל המנחות בכלל הגשה.","\u0003ו\u0004שואלים: אחר שבכתוב זה יש לשון ריבוי (\"את המנחה\") ולשון מיעוט (\"מאלה\"), \u0003מה ראית\u0004 להעדיף \u0003לרבות\u0004 את \u0003שאר\u0004 ה\u0003מנחות\u0004 להגשה, \u0003ולהוציא\u0004 (למעט) \u0003את\u0004 \u0003שתי הלחם ולחם הפנים\u0004 מהגשה, והרי אפשר היה לומר להיפך, לרבות את שתי אלה להגשה ולמעט את שאר המנחות?! ומשיבים: \u0003מרבה אני\u0004 את \u0003שאר\u0004 ה\u0003מנחות\u0004 להגשה, \u0003ש\u0004כן \u0003יש מהן\u0004 חלק שניתן \u0003לאישים\u0004 (הקרב על אש המזבח), \u0003ומוציא\u0004 (ממעט) \u0003אני\u0004 את \u0003שתי הלחם ולחם הפנים\u0004 מהגשה, כיון \u0003שאין מהן\u0004 דבר הניתן \u0003לאישים,\u0004 אלא נאכלים כולם לכהנים.","ושואלים: \u0003והלא מנחת נסכים\u0004 ש\u0003כולה\u0004 ניתנת \u0003לאישים, יכול יהא\u0004 דינה, לפי סברה זו, שתהא \u0003טעונה הגשה?\u0004 לכך \u0003תלמוד לומר\u0004 בהמשך אותו כתוב \"אשר יעשה מאלה לה' \u0003והקריבה\",\u0004 והרי זה בא להורות שאין דין ההגשה (\"והקריבה\") אלא במנחות האמורות באותה פרשה, ולא במנחת נסכים שאינה נזכרת בה.","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת,\u0006 דרשת\u0005]\u0006 מלה זו \"והקריבה\" לענין שאף מנחת סוטה בכלל הגשה? ומשיבים: היה יכול הכתוב לומר \u0003\"והקריב\"\u0004 ונאמר \u0003\"והקריבה\"\u0004 ובאה האות ה\"א היתרה ללמדנו מיעוט זה של מנחת נסכים מהגשה. \u0003ו\u0004שואלים: אחר שבכתוב זה יש לשון ריבוי (\"את המנחות\") ויש לשון מיעוט (\"והקריבה\"), \u0003מה ראית\u0004 להעדיף \u0003לרבות\u0004 את \u0003שאר\u0004 ה\u0003מנחות\u0004 לדין הגשה, \u0003ולהוציא\u0004 (למעט) את \u0003מנחת נסכים\u0004 מהגשה, והרי אפשר היה לומר להיפך, לרבות את מנחת הנסכים ולמעט את אלה?!"],["ומשיבים: \u0003מרבה אני\u0004 (מעדיף אני לרבות) מן הכתוב את \u0003שאר\u0004 ה\u0003מנחות, ש\u0004הן \u0003באות בגלל עצמן,\u0004 בדומה לחמש המנחות המנויות בפרשתנו (ויקרא ב, א— יג). \u0003ומוציא\u0004 (ממעט) \u0003אני\u0004 מן הכתוב \"והקריבה\" את \u0003מנחת נסכים, ש\u0004כן \u0003אינה באה בגלל עצמה\u0004 אלא כנלוית אל הקרבן. ושואלים: \u0003והלא מנחת כהנים ומנחת כהן משיח\u0004 אף הן \u0003באות בגלל עצמן,\u0004 ולפי סברה זו \u0003יכול יהו\u0004 אף הן \u0003טעונות הגשה?\u0004","לכך \u0003תלמוד לומר\u0004 \u0003\"והגישה\"\u0004 — למעט את אלה, שאינן בכלל הגשה. ומקשים על כך: איך אתה יכול לדרוש הלכה זו מהכתוב \"והגישה\", והלא \u0003האי מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה נצרך לו]\u0006 \u0003לגופה\u0004 של ההלכה \u0003שטעונה\u0004 המנחה \u0003הגשה\u0004 למזבח! ומשיבים: למדים זאת \u0003מן\u0004 הה\"א הנוספת, שהיה יכול לומר \u0003\"והגיש\",\u0004 ואמר \u0003\"והגישה\". ו\u0004שואלים: אחר שבכתוב יש לשון ריבוי (\"את המנחה\"), ויש לשון מיעוט (\"והגישה\") יש מקום לשאול","\u0003מה ראית\u0004 להעדיף \u0003לרבות\u0004 את \u0003שאר מנחות\u0004 להגשה, \u0003ולהוציא\u0004 (למעט) את \u0003מנחת כהנים ומנחת כהן משיח,\u0004 אמור להיפך, ונרבה את שתי אלה ונמעט את שאר המנחות? ומשיבים : הטעם ש\u0003מרבה אני\u0004 לדין הגשה דווקא את \u0003שאר\u0004 ה\u0003מנחות, ש\u0004כן בהן כמה דברים מיוחדים ש\u0003יש מהן\u0004 חלק הניתן \u0003לאישים\u0004 (אש המזבח), \u0003ו\u0004הן \u0003באות בגלל עצמן\u0004 ולא מחמת קרבן אחר, \u0003ו\u0004אף \u0003יש מהן\u0004 חלק הניתן \u0003ל\u0004אכילתם של \u0003כהנים. ומוציא אני\u0004 מדין הגשה את המנחות שאין בהן דינים אלה. את \u0003שתי הלחם ו\u0004את \u0003לחם הפנים שאין מהן\u0004 חלק הניתן \u0003לאישים, ו\u0004את \u0003מנחת נסכים שאינה באה בגלל עצמה, ו\u0004את \u0003מנחת כהנים ומנחת כהן משיח שאין מהן\u0004 דבר הניתן \u0003ל\u0004אכילת \u0003כהנים.\u0004 ועוד בדרשת הברייתא. נאמר עוד בכתוב \"והרים הכהן מן המנחה את אזכרתה והקטיר המזבחה אשה ריח ניחוח לה' \" (שם ט).","ויש לדון: מן הכתוב \u0003\"והרים\"\u0004 — \u0003יכול\u0004 היית ללמוד שאף \u0003בכלי\u0004 מרים הכהן? לכך \u0003תלמוד לומר\u0004 (מלמדנו האמור) בדין המנחה \"וזאת תורת המנחה הקרב אותה בני אהרן לפני ה' אל פני המזבח. \u0003והרים ממנו בקומצו...\"\u0004 (שם ו, ז— ח). ומכאן נלמד: \u0003מה\u0004 דין \u0003הרמה האמור להלן\u0004 — הרי זה דווקא \u0003בקומצו\u0004 של הכהן, בידו ולא בכלי. \u0003אף\u0004 דין \u0003הרמה האמור כאן\u0004 — הרי זה דווקא \u0003בקומצו,\u0004 ולא בכלי.","\u0003אלו\u0004 הם הדברים הקרבים שהם \u0003טעונות תנופה ואין טעונות הגשה: לוג שמן\u0004 הבא עם קרבן אשם \u0003של\u0004 ה\u0003מצורע\u0004 שהתרפא מצרעתו, \u0003ו\u0004כן \u0003אשמו\u0004 של המצורע, שכן נאמר בהם \"...ולקח הכהן את הכבש האחד והקריב אותו לאשם ואת לוג השמן והניף אותם תנופה לפני ה' \" (שם יד, יב). \u0003ו\u0004כן \u0003הבכורים.\u0004 ודין זה בביכורים הוא אך \u0003כדברי\u0004 (לשיטת) \u0003ר' אליעזר בן יעקב. ו\u0004כן \u0003אימורי\u0004 (החלק הקרב על המזבח) של \u0003שלמי יחיד. ו\u0004אף \u0003חזה ושוק שלהן\u0004 הניתנים לכהנים לאכילה (שנאמר בהם \"שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף תנופה לפני ה' \". שם י, טו).","ומציינים: דין זה של חובת התנופה בשלמי יחיד, אמור \u0003אחד\u0004 (בין) בשלמי \u0003אנשים\u0004 (גברים) \u0003ואחד\u0004 בשל \u0003נשים.\u0004 ואולם אין ההנפה נעשית אלא \u0003ב\u0004ידי בני \u0003ישראל\u0004 הזכרים \u0003ולא באחרים\u0004 (הנשים או הגויים). ועוד החייבים בתנופה הם \u0003שתי הלחם\u0004 הבאות בחג השבועות \u0003ו\u0004כן \u0003שני כבשי עצרת\u0004 (שכן נאמר באלה ובאלה \"והניף הכהן אותם על לחם הביכורים תנופה לפני ה' על שני כבשים\" שם כג, כ).","ומסבירים: \u0003כיצד הוא\u0004 המניף את שתי הלחם ושני כבשי העצרת \u0003עושה\u0004 על מנת לקיים את הכתוב \"והניף... אותם על לחם הביכורים... על שני כבשים\"? — הריהו \u0003נותן\u0004 את \u0003שתי הלחם על גבי שני\u0004 ה\u0003כבשים, ומניח שתי ידיו\u0004 מ\u0003למטה\u0004 מהם, ומניף אותם, וכך הוא עושה: \u0003מוליך\u0004 (מושיט) אותם אל כנגד ארבע רוחות השמים, ושב \u0003ומביא\u0004 (ומחזיר) אותם. ולאחר מכן הריהו \u0003מעלה\u0004 אותם כלפי מעלה ושב \u0003ומוריד\u0004 אותם מטה. וטעם הדבר: \u0003ש\u0004כן \u0003נאמר\u0004 במצות התנופה של איל המילואים \u0003\"אשר הונף ואשר הורם\"\u0004 (שמות כט, כז). ומובן הדברים: \"אשר הונף\" — בהולכה ובהבאה, \"ואשר הורם\" — בהעלאה ובהורדה. ה\u0003תנופה היתה\u0004 נעשית \u0003אף\u0004 \u0003במזרח\u0004 המזבח, \u0003ו\u0004אילו ה\u0003הגשה\u0004 היתה נעשית דווקא \u0003במערב\u0004 המזבח, בקרן הדרומית מערבית שבו. ועוד: בכל המנחות החייבות בתנופות ובהגשות, ה\u0003תנופות קודמות\u0004 בעשייתן \u0003להגשות,\u0004 שבתחילה מניפים אותן ורק לאחר מכן מגישים אותן אל קרן המזבח.","\u0003מנחת העומר\u0004 הקרבה למחרת יום ראשון של חג הפסח, בט\"ז בניסן, וכן \u0003מנחת קנאות\u0004 (מנחת סוטה) הריהן \u0003טעונות\u0004 הן \u0003הגשה\u0004 \u0003ו\u0004הן \u0003תנופה\u0004 שנאמר במנחת הסוטה \"והניף את המנחה לפני ה' והקריב אותה אל המזבח\" (במדבר ה, כה) — הרי זו תנופה והגשה. ובמנחת העומר נאמר \"והניף את העומר\" (ויקרא כג, יא) — הרי זו תנופה, ומצות הגשה נלמדה בדרשות חז\"ל (בעמוד הקודם). \u0003לחם הפנים ומנחת נסכים\u0004 \u0003אין טעונות לא הגשה ולא תנופה.\u0004","\u0003ר' שמעון אומר: שלשה מינין\u0004 של קרבנות \u0003טעונין שלש מצו‍ת\u0004 הנעשות בהם. \u0003שתים\u0004 משלוש המצוות הללו נוהגות \u0003בכל אחת ואחת\u0004 משלושת הקרבנות הללו, אף כי לא בכולן אותן שתיים, \u0003ו\u0004אילו מצוה \u0003שלישית אין\u0004 נוהגת \u0003בהן.\u0004 \u0003ואלו הן\u0004 שלושת מיני הקרבנות: \u0003זבחי שלמי יחיד\u0004 (קרבנות שלמים שמביא היחיד), \u0003וזבחי שלמי ציבור\u0004 (שני כבשי עצרת), \u0003ו\u0004קרבן \u0003אשם\u0004 שמביא ה\u0003מצורע\u0004 הנרפא מצרעתו.","\u0003זבחי שלמי יחיד\u0004 — \u0003טעונין סמיכה\u0004 על ראש הקרבן בעודו ב\u0003חיים, ו\u0004כן \u0003תנופה\u0004 של אימורי הקרבנות ה\u0003שחוטין,\u0004 אבל \u0003אין בהן\u0004 מצות \u0003תנופה\u0004 בעודם ב\u0003חיים.\u0004 ולעומת זאת \u0003זבחי שלמי ציבור\u0004 — \u0003טעונים תנופה\u0004 בעודם \u0003חיים ו\u0004כן בהנפת החזה והשוק הנלקחים מהם כשהם \u0003שחוטין, ו\u0004אולם \u0003אין בהם סמיכה,\u0004 שאין הסמיכה נוהגת ברוב קרבנות ציבור, \u0003ו\u0004אילו \u0003אשם מצורע\u0004 — \u0003טעון\u0004 הן \u0003סמיכה\u0004 ברוב קרבנות היחיד הטעונים סמיכה, \u0003ו\u0004הן \u0003תנופה\u0004 בעודו \u0003חי\u0004 (כמבואר למעלה), \u0003ו\u0004אולם \u0003אין בו\u0004 מצוה של \u0003תנופה\u0004 בקרבן ה\u0003שחוט.\u0004","שנינו בראשית משנתנו כי לוג שמן של מצורע וכן אשמו חייבים בתנופה. \u0003ומבארים את מקור הדין,\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר במצורע המתרפא מצרעתו \u0003\"והקריב אתו לאשם ואת לוג השמן והניף אתם תנופה\u0004 לפני ה' \" (שם יד, יב) — והרי לשון הרבים \"והניף אותם\" \u0003מלמד ש\u0004לוג השמן והקרבן \u0003טעונין תנופה\u0004 שתיעשה בהם \u0003כאחד\u0004 (ביחד).","\u0003ומנין ש\u0004אין ההנפה יחד מעכבת ו\u0003אם\u0004 עבר המניף ו\u0003הניף\u0004 את \u0003זה בעצמו ו\u0004את \u0003זה בעצמו\u0004 ש\u0003יצא\u0004 בכל זאת ידי חובתו? \u0003תלמוד לומר\u0004 בלשון יחיד \u0003\"והקריב אתו לאשם והניף\".\u0004 ומבררים: \u0003יכול\u0004 כוונת הכתוב (שיש בו הן לשון רבים והן לשון יחיד בתנופה) ללמדנו שהמצוה היא שבתחילה \u0003יניף\u0004 את שניהם כאחד, \u0003ו\u0004לאחר מכן \u0003יחזיר\u0004 (יחזור) \u0003ויניף\u0004 כל אחד מהם לחוד? לכך \u0003תלמוד לומר\u0004 בכתוב המסכם \u0003\"תנופה\u0004 לפני ה' \" בלשון יחיד — תנופה אחת, \u0003ולא\u0004 כמה \u0003תנופות.\u0004","ומה שנאמר בכתוב זה \u0003\"תנופה\u0004 \u0003לפני ה' \"\u0004בא ללמד שתהא התנופה נעשית אף \u0003במזרח\u0004 המזבח, כדברי משנתנו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר\u0004 התנא בברייתא (שהובאה לעיל במסכתנו, יט,ב) בדין הגשת המנחה למזבח: ממה שנאמר \u0003\"לפני ה' \"\u0004— \u0003יכול\u0004 שיגיש אותן \u0003במערב,\u0004 שהוא לפני ה', מול ההיכל? לכך בא הכתוב \"אל פני המזבח\" — בדרום, שמשם עולים אל המזבח. ומכאן שנעשית ההגשה בקרן הדרומית מערבית. הרי שהביטוי \u0003\"לפני ה' \" מורה על צד מערב!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהביטוי \"לפני ה' \" מורה על המערב במקדש, אמורים דווקא ב\u0003מנחה, דאיקרי\u0004 \u0005[ש\u0006כן \u0005נקראת,\u0006 מכונה היא\u0005]\u0006 בכתוב בשם \u0003\"חטאת\"\u0004 (\"קדש קדשים היא כחטאת\". ויקרא ו, י), \u0003ו\u0004ה\u0003חטאת טעונה\u0004 שפיכת הדמים הנותרים בה אל \u0003יסוד\u0004 המזבח. ומעתה, אף המנחה צריכה איפוא להיות מוגשת כנגד היסוד. \u0003ו\u0004אולם מאחר שב\u0003קרן\u0004 ה\u0003דרומית מזרחית לא היה לו\u0004 למזבח \u0003יסוד,\u0004 משום כך הריהי מוגשת בקרן הדרומית_מערבית בה יש למזבח יסוד. ומתקיימים בקרן זו הן \"אל פני המזבח\" (=צד דרום), והן \"לפני ה' \". \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בדין תנופת לוג השמן ואשם של מצורע \u0003\"לפני ה' \" קרינא ביה\u0004 \u0005[קוראים אנו בו,\u0006 נחשב הדבר\u0005]\u0006 אף בצד המזרחי של המזבח.","\u0003ו\u0004עוד שנינו במשנתנו כי נוהגת תנופה אף אצל \u0003הבכורים\u0004 ואולם אין זה אלא \u0003כדברי\u0004 \u0003ר' אליעזר בן יעקב\u0004 בלבד. ומבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 אותה שיטה של \u0003ר' אליעזר בן יעקב\u0004 הנרמזת כאן? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר במצות הביכורים \u0003\"ולקח הכהן\u0004 הטנא מידך והניחו לפני מזבח ה' אלהיך\" (דברים כו, ד) — \u0003לימד\u0004 כתוב זה \u0003על הבכורים ש\u0004הם \u0003טעונין תנופה,\u0004 אלו \u0003דברי ר' אליעזר בן יעקב.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב,\u0004 כיצד לדבריו נלמד הדבר מן הכתוב? ומשיבים: ר' אליעזר בן יעקב \u0003גמר\u0004 \u0005[למד]\u0006 זאת מגזירה שווה של המלים \u0003\"יד\"\u0004 האמורה במצות הביכורים, ו\u0003\"יד\" מ\u0004האמור בקרבן ה\u0003שלמים.\u0004 ומפרטים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בביכורים\u0005]\u0006 \u0003\"ולקח הכהן הטנא מידך\", וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 בשלמים\u0005]\u0006 \u0003\"ידיו תביאנה\u0004 את אשי ה' את החלב על החזה יביאנו את החזה להניף אותו תנופה לפני ה' \" (ויקרא ז, ל), ומכאן, שאף בביכורים נוהגת מצות תנופה, כבשלמים."],["ולמדנו עוד מגזירה שווה זו: \u0003מה כאן\u0004 במצות הביכורים ה\u0003כהן\u0004 הוא שמניף את הביכורים, \u0003אף להלן\u0004 בשלמים, ה\u0003כהן\u0004 הוא שמניף את השלמים. \u0003ומה להלן\u0004 בשלמים ה\u0003בעלים\u0004 הוא שמניף, \u0003אף כאן\u0004 בביכורים \u0003ה\u0004\u0003בעלים\u0004 הוא שמניף. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מקיים את שני הדברים יחד? \u0003כהן מניח ידו תחת ידי בעלים ומניף.\u0004","ושואלים: ומדוע יוחסה הלכה זו לר' אליעזר בן יעקב, \u0003ולימא נמי\u0004 \u0005[ושיאמר\u0006 במשנה \u0005גם כן]\u0006 שהוא \u0003כדברי ר' יהודה! דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בפרשת הביכורים \"ולקח \u0005הכהן הטנא מידך והניחו לפני מזבח ה' אלהיך... והנחתו לפני ה' אלהיך...\"\u0006(דברים כו, ד— י), \u0003ר' יהודה אומר:\u0004 אין משמעות הכתוב \u0003\"והנחתו\u0004 לפני ה' אלהיך\" כמשמעה שצריך לעשות הנחה, אלא הרי \u0003זו תנופה\u0004 (הנפה). ודן הוא בדבר: \u0003אתה אומר\u0004 כי הרי \u0003זו תנופה, או\u0004 שמא \u0003אינו אלא הנחה\u0004 ממש?","אינך יכול לומר כן, כי \u0003כשהוא\u0004 (הכתוב) \u0003אומר\u0004 לפני כן \u0003\"והניחו\u0004 לפני מזבח ה' אלהיך\" — \u0003הרי\u0004 דין \u0003הנחה\u0004 כבר \u0003אמור, הא\u0004 \u0005[הרי]\u0006 מעתה ב\u0003מה אני מקיים\u0004 את הכתוב \u0003\"והנחתו\"?\u0004 — \u0003זו תנופה.\u0004 הרי שאף ר' יהודה סבור שנוהגת מצות הנפה בביכורים!","\u0003אמר רבא:\u0004 אכן אפשר היה לייחס הלכה זו כשיטת ר' יהודה, והתנא העדיף לייחסה כשיטת ר' אליעזר בן יעקב \u0003הואיל ופתח בו\u0004 בדין הנפה בביכורים \u0003הכתוב תחלה,\u0004 שהרי לשיטת ר' אליעזר בן יעקב נלמד דין זה מן האמור בתחילת הדברים (מן הכתוב \"ולקח הכהן הטנא מידך\"), בעוד שר' יהודה למד דין זה מן הנאמר לאחר מכן (\"והנחתו\"). \u0003רב נחמן בר יצחק אמר\u0004 תשובה אחרת: התנא העדיף לייחס הלכה זו כר' אליעזר בן יעקב, \u0003הואיל ורב גבריה\u0004 \u0005[וגדול כוחו]\u0006 של ר' אליעזר בן יעקב בתורה, שהלכה כמותו תמיד.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003אימורי\u0004 (החלבים הקרבים על המזבח) \u0003של\u0004 \u0003שלמי יחיד ו\u0004כן ה\u0003חזה ושוק שלהן,\u0004 הניתנים לכהנים לאכילה, חייבים בתנופה. וחיוב זה נוהג \u0003אחד\u0004 (בין) בשלמים של \u0003האנשים ואחד\u0004 בשל \u0003הנשים.\u0004 ואין נוהגת מצות התנופה אלא \u0003ב\u0004קרבנות של \u0003ישראל, אבל לא ב\u0004קרבנות של \u0003אחרים.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 שכן נראים הדברים כסתירה, שבראשית הדברים אנו למדים כי קרבנות הנשים חייבים בתנופה, והמשכם של הדברים מורה כי אין קרבנות הנשים (\"אחרים\") חייבים בתנופה.","\u0003אמר רב יהודה\u0004 בהסבר דברי התנא, \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003אחד אנשים ואחד נשים\u0004 — \u0003קרבנן טעון תנופה, ו\u0004אולם ה\u0003תנופה עצמה\u0004 נעשית \u0003ב\u0004ידי גברים \u0003\"ישראל\",\u0004 והבעלים והכהן מניפים יחד, \u0003אבל\u0004 בקרבן של נשים התנופה \u0003לא\u0004 נעשית \u0003בידי נשים\u0004 בעלות הקרבן, אלא הכהן בלבד הוא המניף.","ועוד בדין תנופה בקרבנן של נשים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0005בראשית פרשת הנפת השלמים נאמר \"דבר אל בני ישראל לאמר המקריב את זבח שלמיו... ידיו תביאינה את אשי ה' את החלב על החזה יביאנו את החזה להניף אותו תנופה לפני ה' \" (ויקרא ז, כט—\u0006 ל). ומן הכתוב \"בני ישראל\" למדים אנו כי רק \u0003בני ישראל\u0004 המביאים \u0003קרבנות\u0004 \u0003מניפין\u0004 אותם, \u0003ואין הגוים\u0004 המביאים קרבנות \u0003מניפין\u0004 אותם. ועוד נלמד מכתוב זה כי רק \u0003בני ישראל\u0004 הגברים \u0003מניפין\u0004 את קרבנותיהם, \u0003ואין הנשים\u0004 המביאות קרבן \u0003מניפות.\u0004","\u0003אמר ר' יוסי: מצינו\u0004 (מצאנו) \u0003שחלק\u0004 (שהבדיל) \u0003הכתוב בין קרבן ישראל ל\u0004בין \u0003קרבן\u0004 של \u0003גוים\u0004 וכן \u0003ל\u0004בין \u0003קרבן נשים ב\u0004ענין חיוב ה\u0003סמיכה\u0004 על הקרבן. שכן קרבן גברים מישראל חייב בסמיכה, ולא של גוים ושל נשים. ומעתה יש לשאול: \u0003יכול\u0004 שנלמד מדין הסמיכה לדין התנופה ו\u0003נחלוק\u0004 ביניהם גם \u0003ב\u0004דין ה\u0003תנופה\u0004 בקרבנות שרק של האנשים מישראל יהא חייב בה?","ויש להשיב: \u0003לא,\u0004 אין ללמוד כך, שיש \u0003לומר כי\u0004 \u0003מה לי\u0004 (מה טעם) \u0003חלק\u0004 הכתוב בין אנשים מישראל לבין גוים ונשים \u0003בסמיכה\u0004 — משום \u0003ש\u0004מיוחד הוא דין \u0003הסמיכה,\u0004 שנעשית רק \u0003בבעלים\u0004 של הקרבן עצמם, ואין אחרים יכולים לסמוך עבורם. ומעתה יש מקום לומר, כי כשם שהתמעטו הכהנים ממעשה הסמיכה, התמעטו הגוים והנשים מסמיכה.","ואולם האם נבוא ו\u0003נחלוק\u0004 בין אנשים לבין גוים ונשים גם \u0003ב\u0004ענין ה\u0003תנופה? שהתנופה\u0004 נעשית אף \u0003בכהנים,\u0004 וממילא אין סיבה גם לחלק בין גוים ונשים לבין אחרים שיכולים לעשות את הכהנים לשליחיהם לתנופה! \u0003אם כן\u0004 שאף קרבנם של גוים ושל נשים חייב בתנופה, יש לשאול: \u0003מה תלמוד לומר\u0004 \u0003\"בני ישראל\"?\u0004 — \u0003בני ישראל מניפין\u0004 בעצמם את קרבנם, \u0003ואין הגוים מניפין\u0004 בעצמם את קרבנם. וכמו כן: \u0003בני ישראל מניפין\u0004 בעצמם את קרבנם, \u0003ואין הנשים מניפות\u0004 בעצמן את קרבנן.","ועוד בענין מצות התנופה \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 ממה שנאמר בתחילת פרשת הנפת השלמים \u0003\"בני ישראל\"\u0004 — \u0003אין לי\u0004 ללמוד שחייבים בתנופה \u0003אלא בני ישראל\u0004 ממש, ואולם \u0003גרים ועבדים משוחררין\u0004 שדינם כישראל, \u0003מנין\u0004 לי שגם הם חייבים בתנופת קרבנם? — \u0003תלמוד\u0004 \u0003לומר\u0004 מיד לאחר מכן \u0003\"המקריב\u0004 את זבח שלמיו\" — לרבות לדין ההנפה כל אדם המביא קרבן למקדש (\"המקריב\"), ובכלל זה אף הגרים והעבדים המשוחררים.","ואם תשאל: \u0003או\u0004 אפשר שכוונת הכתוב \"המקריב\" \u0003אינו\u0004 כן, \u0003אלא\u0004 לומר שהמניף הוא \u0003זה\u0004 ה\u0003כהן המקריב\u0004 ממש את אימורי וחלבי הקרבן על המזבח? — אינך יכול לומר כן, שהרי \u0003כשהוא\u0004 (הכתוב) \u0003אומר\u0004 בפסוק הבא \u0003\"ידיו תביאינה\u0004 את אשי ה'... להניף אותו תנופה לפני ה' \" — \u0003הרי\u0004 שב\u0003בעלים אמור\u0004 דין ההנפה. ומעתה יש לשאול: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתקיימת איפוא מצוות ההנפה, על ידי הבעלים ועל ידי הכהן? — ה\u0003כהן מניח\u0004 את \u0003ידיו תחת ידי הבעלים, ומניף\u0004 את הקרבן."]]};
